    /******************************************************************
     * v12.34.54：患者信息脚本患者级大缓存统一Tampermonkey GM存储层
     *
     * - GM保存完整患者数据，localStorage仅保留轻量同步/迁移信号；
     * - 旧localStorage完整对象首次读取时自动迁移：先写GM成功，再替换信号；
     * - GM不可用时仍允许回退localStorage，避免缓存功能成为单点故障；
     * - 这些患者缓存不进入WebDAV长期设置备份，仅由统一缓存管理手动备份。
     *
     * 查房本主体已有独立medicalPatientRoundBookLargeStoreV1，本层主要承接
     * 病案质控、检查申请单草稿和AI诊疗分析等其它患者级长期缓存。
     ******************************************************************/
    const PATIENT_LARGE_CACHE_GM_PREFIX =
        'medicalPatientInfoLargeCacheV1::';

    const PATIENT_LARGE_CACHE_SIGNAL_MODE =
        'tampermonkey-gm-large-cache-v1';

    const PATIENT_CACHE_MANAGEMENT_CHANGED_EVENT =
        'medical-userscript-cache-data-changed';

    function patientLargeCacheGmKey(storageKey) {
        return (
            PATIENT_LARGE_CACHE_GM_PREFIX +
            String(storageKey || '')
        );
    }

    function patientLargeCachePlainStore(value) {
        if (
            value &&
            typeof value === 'object' &&
            !Array.isArray(value)
        ) {
            return value;
        }
        return {};
    }

    function patientLargeCacheParseStore(value) {
        if (
            value &&
            typeof value === 'object' &&
            !Array.isArray(value)
        ) {
            return value;
        }

        const raw =
            String(
                value == null
                    ? ''
                    : value
            ).trim();

        if (!raw) return {};

        try {
            return patientLargeCachePlainStore(
                JSON.parse(raw)
            );
        } catch (error) {
            return {};
        }
    }

    function patientLargeCacheSignalObject(value) {
        let parsed = value;

        if (typeof value === 'string') {
            try {
                parsed =
                    JSON.parse(
                        value || 'null'
                    );
            } catch (error) {
                return null;
            }
        }

        if (
            parsed &&
            typeof parsed === 'object' &&
            !Array.isArray(parsed) &&
            parsed.storageMode ===
                PATIENT_LARGE_CACHE_SIGNAL_MODE
        ) {
            return parsed;
        }

        return null;
    }

    function patientLargeCacheByteLength(value) {
        const textValue =
            String(
                value == null
                    ? ''
                    : value
            );

        try {
            return new Blob(
                [textValue]
            ).size;
        } catch (error) {
            return (
                textValue.length *
                2
            );
        }
    }

    function patientLargeCacheBuildSignal(
        storageKey,
        serialized,
        store
    ) {
        return {
            schemaVersion: 1,
            storageMode:
                PATIENT_LARGE_CACHE_SIGNAL_MODE,
            gmKey:
                patientLargeCacheGmKey(
                    storageKey
                ),
            updatedAt: Date.now(),
            entryCount:
                Object.keys(
                    patientLargeCachePlainStore(
                        store
                    )
                ).length,
            byteLength:
                patientLargeCacheByteLength(
                    serialized
                )
        };
    }

    function patientLargeCacheNotifyChanged(
        storageKey
    ) {
        try {
            document.dispatchEvent(
                new CustomEvent(
                    PATIENT_CACHE_MANAGEMENT_CHANGED_EVENT,
                    {
                        detail: {
                            adapterKey:
                                'patient',
                            storageKey:
                                String(
                                    storageKey ||
                                    ''
                                ),
                            time:
                                Date.now()
                        }
                    }
                )
            );
        } catch (error) {
            // 管理器未加载或页面正在销毁时不影响缓存读写。
        }
    }

    function patientLargeCacheWriteSignal(
        storageKey,
        serialized,
        store
    ) {
        const signalText =
            JSON.stringify(
                patientLargeCacheBuildSignal(
                    storageKey,
                    serialized,
                    store
                )
            );

        try {
            localStorage.setItem(
                storageKey,
                signalText
            );
        } catch (error) {
            /*
             * 旧完整缓存可能已经占满localStorage。GM完整数据写入成功后，
             * 可安全删除旧大对象并仅写回几十/几百字节的信号。
             */
            try {
                localStorage.removeItem(
                    storageKey
                );
                localStorage.setItem(
                    storageKey,
                    signalText
                );
            } catch (ignored) {
                // GM数据已存在；同步信号失败不影响本标签页继续读取。
            }
        }

        return signalText;
    }

    function patientLargeCacheReadSerializedFromGmOnly(
        storageKey
    ) {
        if (
            typeof GM_getValue !==
                'function' ||
            !storageKey
        ) {
            return null;
        }

        try {
            const value =
                GM_getValue(
                    patientLargeCacheGmKey(
                        storageKey
                    ),
                    undefined
                );

            if (
                value === undefined ||
                value === null ||
                value === ''
            ) {
                return null;
            }

            if (
                typeof value ===
                    'string'
            ) {
                return value;
            }

            return JSON.stringify(
                value
            );
        } catch (error) {
            return null;
        }
    }

    function patientLargeCacheReadStore(
        storageKey
    ) {
        const gmSerialized =
            patientLargeCacheReadSerializedFromGmOnly(
                storageKey
            );

        if (gmSerialized) {
            return patientLargeCacheParseStore(
                gmSerialized
            );
        }

        let localRaw = '';

        try {
            localRaw =
                localStorage.getItem(
                    storageKey
                ) ||
                '';
        } catch (error) {
            localRaw = '';
        }

        if (!localRaw) {
            return {};
        }

        if (
            patientLargeCacheSignalObject(
                localRaw
            )
        ) {
            /*
             * 信号本身不含患者正文。若GM授权被撤销，不能把信号误认为
             * 完整缓存；此时返回空对象，待授权恢复后即可重新读取GM。
             */
            return {};
        }

        const legacyStore =
            patientLargeCacheParseStore(
                localRaw
            );

        /*
         * 旧localStorage完整缓存懒迁移。只有GM写入成功后才替换旧值，
         * 因此升级过程中即使异常也不会先删除患者资料。
         */
        if (
            typeof GM_setValue ===
                'function' &&
            Object.keys(
                legacyStore
            ).length
        ) {
            try {
                const serialized =
                    JSON.stringify(
                        legacyStore
                    );

                GM_setValue(
                    patientLargeCacheGmKey(
                        storageKey
                    ),
                    serialized
                );

                patientLargeCacheWriteSignal(
                    storageKey,
                    serialized,
                    legacyStore
                );

                patientLargeCacheNotifyChanged(
                    storageKey
                );
            } catch (error) {
                // 迁移失败继续使用旧localStorage完整对象。
            }
        }

        return legacyStore;
    }

    function patientLargeCacheWriteStore(
        storageKey,
        store
    ) {
        const normalized =
            patientLargeCachePlainStore(
                store
            );

        const serialized =
            JSON.stringify(
                normalized
            );

        let gmError = null;

        if (
            typeof GM_setValue ===
                'function'
        ) {
            try {
                GM_setValue(
                    patientLargeCacheGmKey(
                        storageKey
                    ),
                    serialized
                );

                patientLargeCacheWriteSignal(
                    storageKey,
                    serialized,
                    normalized
                );

                patientLargeCacheNotifyChanged(
                    storageKey
                );

                return {
                    mode:
                        'tampermonkey-gm',
                    byteLength:
                        patientLargeCacheByteLength(
                            serialized
                        ),
                    entryCount:
                        Object.keys(
                            normalized
                        ).length
                };
            } catch (error) {
                gmError = error;
            }
        }

        /*
         * 兼容非Tampermonkey或GM授权异常环境；正常安装v12.34.54不会走这里。
         */
        try {
            localStorage.setItem(
                storageKey,
                serialized
            );

            patientLargeCacheNotifyChanged(
                storageKey
            );

            return {
                mode:
                    'localStorage-fallback',
                byteLength:
                    patientLargeCacheByteLength(
                        serialized
                    ),
                entryCount:
                    Object.keys(
                        normalized
                    ).length
            };
        } catch (error) {
            throw new Error(
                '患者大缓存保存失败：Tampermonkey GM大容量存储不可用，且浏览器localStorage容量不足' +
                (
                    gmError &&
                    gmError.message
                        ? '（GM错误：' +
                          gmError.message +
                          '）'
                        : ''
                )
            );
        }
    }

    function patientLargeCacheDeleteStore(
        storageKey
    ) {
        try {
            if (
                typeof GM_deleteValue ===
                    'function'
            ) {
                GM_deleteValue(
                    patientLargeCacheGmKey(
                        storageKey
                    )
                );
            }
        } catch (error) {
            // 继续清理localStorage旧值/信号。
        }

        try {
            localStorage.removeItem(
                storageKey
            );
        } catch (error) {
            // 忽略。
        }

        patientLargeCacheNotifyChanged(
            storageKey
        );

        return true;
    }

    function patientLargeCacheStats(
        storageKey,
        entryCounter
    ) {
        const store =
            patientLargeCacheReadStore(
                storageKey
            );

        const serialized =
            JSON.stringify(
                store
            );

        let entryCount =
            Object.keys(
                store
            ).length;

        if (
            typeof entryCounter ===
                'function'
        ) {
            try {
                entryCount =
                    Math.max(
                        0,
                        Number(
                            entryCounter(
                                store
                            )
                        ) ||
                        0
                    );
            } catch (error) {
                // 统计失败时使用顶层键数量。
            }
        }

        return {
            storageKey:
                String(
                    storageKey ||
                    ''
                ),
            gmKey:
                patientLargeCacheGmKey(
                    storageKey
                ),
            storageMode:
                patientLargeCacheReadSerializedFromGmOnly(
                    storageKey
                )
                    ? 'Tampermonkey GM'
                    : 'localStorage兼容',
            entryCount:
                entryCount,
            byteLength:
                patientLargeCacheByteLength(
                    serialized
                )
        };
    }

    function normalize(text) {
        return String(text || '')
            .replace(/\s+/g, '')
            .replace(/[：:*＊]/g, '')
            .trim();
    }

    function normalizeLookup(text) {
        return normalize(text)
            .replace(/（/g, '(')
            .replace(/）/g, ')');
    }

    function isVisible(element) {
        if (
            !element ||
            !element.isConnected
        ) {
            return false;
        }

        const win =
            element.ownerDocument.defaultView;

        const style =
            win.getComputedStyle(element);

        const rect =
            element.getBoundingClientRect();

        return (
            style.display !== 'none' &&
            style.visibility !== 'hidden' &&
            style.opacity !== '0' &&
            rect.width > 0 &&
            rect.height > 0
        );
    }

    /******************************************************************
     * 主页面和同源iframe
     ******************************************************************/

    function getAllDocuments() {
        const documents = [];
        const visited = new Set();

        function collect(doc) {
            if (
                !doc ||
                visited.has(doc)
            ) {
                return;
            }

            visited.add(doc);
            documents.push(doc);

            let frames = [];

            try {
                frames = Array.from(
                    doc.querySelectorAll(
                        'iframe,frame'
                    )
                );
            } catch (error) {
                return;
            }

            frames.forEach(function (frame) {
                try {
                    const childDocument =
                        frame.contentDocument ||
                        frame.contentWindow.document;

                    if (childDocument) {
                        collect(childDocument);
                    }
                } catch (error) {
                    // 跨域iframe无法访问时跳过。
                }
            });
        }

        collect(document);

        return documents;
    }

    /******************************************************************
     * 根据页面文字寻找字段
     ******************************************************************/

    function findTextElements(
        doc,
        text,
        fuzzy
    ) {
        if (
            !doc ||
            !doc.body
        ) {
            return [];
        }

        const allowFuzzy =
            Boolean(fuzzy);

        const target =
            normalize(text);

        const exact = [];
        const partial = [];

        const walker =
            doc.createTreeWalker(
                doc.body,
                doc.defaultView
                    .NodeFilter
                    .SHOW_TEXT
            );

        let node;

        while (
            (node = walker.nextNode())
        ) {
            const value =
                normalize(node.nodeValue);

            const parent =
                node.parentElement;

            if (
                !value ||
                !parent ||
                !isVisible(parent)
            ) {
                continue;
            }

            if (value === target) {
                exact.push(parent);
            } else if (
                allowFuzzy &&
                value.includes(target)
            ) {
                partial.push(parent);
            }
        }

        const matches =
            exact.length
                ? exact
                : partial;

        matches.sort(function (a, b) {
            const rectA =
                a.getBoundingClientRect();

            const rectB =
                b.getBoundingClientRect();

            return (
                rectA.width *
                    rectA.height -
                rectB.width *
                    rectB.height
            );
        });

        return matches;
    }

    function findLabel(
        doc,
        text
    ) {
        return (
            findTextElements(
                doc,
                text,
                true
            )[0] ||
            null
        );
    }

    /******************************************************************
     * 根据坐标寻找字段右侧最近的控件
     ******************************************************************/

    function chooseNearestControl(
        label,
        controls,
        rectGetter
    ) {
        if (
            !label ||
            !controls ||
            !controls.length
        ) {
            return null;
        }

        const getRect =
            rectGetter ||
            function (element) {
                return element
                    .getBoundingClientRect();
            };

        const labelRect =
            label.getBoundingClientRect();

        const labelCenterY =
            labelRect.top +
            labelRect.height / 2;

        const candidates =
            controls.map(function (control) {
                const rect =
                    getRect(control);

                const centerY =
                    rect.top +
                    rect.height / 2;

                const verticalDistance =
                    Math.abs(
                        centerY -
                        labelCenterY
                    );

                const horizontalDistance =
                    rect.left >=
                    labelRect.left - 20
                        ? Math.max(
                            0,
                            rect.left -
                            labelRect.right
                        )
                        : 1500 +
                          Math.abs(
                              rect.left -
                              labelRect.left
                          );

                return {
                    control: control,
                    verticalDistance:
                        verticalDistance,
                    score:
                        verticalDistance * 40 +
                        horizontalDistance
                };
            });

        const sameRow =
            candidates.filter(
                function (item) {
                    return (
                        item.verticalDistance <=
                        36
                    );
                }
            );

        const usable =
            sameRow.length
                ? sameRow
                : candidates;

        usable.sort(function (a, b) {
            return a.score - b.score;
        });

        return usable[0]
            ? usable[0].control
            : null;
    }

    /******************************************************************
     * Select2原始select定位和填写
     ******************************************************************/

    function getSelectVisual(
        select
    ) {
        if (
            select.nextElementSibling &&
            select.nextElementSibling
                .classList &&
            select.nextElementSibling
                .classList
                .contains('select2')
        ) {
            return select.nextElementSibling;
        }

        if (select.parentElement) {
            const visual =
                select.parentElement
                    .querySelector(
                        '.select2-container'
                    );

            if (visual) {
                return visual;
            }
        }

        return select;
    }

    function getSelectRect(
        select
    ) {
        return getSelectVisual(
            select
        ).getBoundingClientRect();
    }

    function findSelectNearLabel(
        label
    ) {
        const selector =
            'select.select2-hidden-accessible,select';

        const cell =
            label.closest('td,th');

        if (cell) {
            const sameCell =
                cell.querySelector(
                    selector
                );

            if (sameCell) {
                return sameCell;
            }

            let sibling =
                cell.nextElementSibling;

            for (
                let index = 0;
                sibling &&
                index < 4;
                index++
            ) {
                const select =
                    sibling.querySelector(
                        selector
                    );

                if (select) {
                    return select;
                }

                sibling =
                    sibling.nextElementSibling;
            }

            const row =
                cell.closest('tr');

            if (row) {
                const nearest =
                    chooseNearestControl(
                        label,
                        Array.from(
                            row.querySelectorAll(
                                selector
                            )
                        ),
                        getSelectRect
                    );

                if (nearest) {
                    return nearest;
                }
            }
        }

        let container =
            label.parentElement;

        for (
            let level = 0;
            container &&
            level < 7;
            level++
        ) {
            const nearest =
                chooseNearestControl(
                    label,
                    Array.from(
                        container.querySelectorAll(
                            selector
                        )
                    ),
                    getSelectRect
                );

            if (nearest) {
                return nearest;
            }

            container =
                container.parentElement;
        }

        return chooseNearestControl(
            label,
            Array.from(
                label.ownerDocument
                    .querySelectorAll(
                        selector
                    )
            ),
            getSelectRect
        );
    }

    /*
     * 根据ID寻找select。
     * 若存在多个同ID控件，优先选择当前可见的Select2。
     */
    function findSelectById(
        id
    ) {
        const candidates = [];

        for (
            const doc of
            getAllDocuments()
        ) {
            const selects =
                Array.from(
                    doc.querySelectorAll(
                        'select'
                    )
                ).filter(
                    function (select) {
                        return select.id === id;
                    }
                );

            selects.forEach(
                function (select) {
                    candidates.push({
                        doc: doc,
                        select: select,
                        visible:
                            isVisible(
                                getSelectVisual(
                                    select
                                )
                            )
                    });
                }
            );
        }

        if (!candidates.length) {
            return null;
        }

        return (
            candidates.find(
                function (item) {
                    return item.visible;
                }
            ) ||
            candidates[0]
        );
    }

    function findSelectByLabelNames(
        names
    ) {
        for (
            const doc of
            getAllDocuments()
        ) {
            for (
                const name of names
            ) {
                const label =
                    findLabel(
                        doc,
                        name
                    );

                if (!label) {
                    continue;
                }

                const select =
                    findSelectNearLabel(
                        label
                    );

                if (select) {
                    return {
                        doc: doc,
                        select: select
                    };
                }
            }
        }

        return null;
    }

    function findTaskSelect(
        task
    ) {
        if (task.id) {
            const direct =
                findSelectById(
                    task.id
                );

            if (direct) {
                return direct;
            }
        }

        return findSelectByLabelNames(
            task.aliases ||
            [task.label]
        );
    }

    function findOption(
        select,
        text,
        fallbackValue
    ) {
        const target =
            normalize(text);

        const options =
            Array.from(
                select.options
            );

        const byText =
            options.find(
                function (option) {
                    return (
                        normalize(
                            option.textContent
                        ) === target
                    );
                }
            );

        if (byText) {
            return byText;
        }

        if (
            fallbackValue !== undefined &&
            fallbackValue !== null
        ) {
            return (
                options.find(
                    function (option) {
                        return (
                            String(
                                option.value
                            ) ===
                            String(
                                fallbackValue
                            )
                        );
                    }
                ) ||
                null
            );
        }

        return null;
    }

    async function waitForOption(
        select,
        text,
        fallbackValue,
        timeout
    ) {
        const deadline =
            Date.now() +
            (timeout || 4500);

        let option =
            findOption(
                select,
                text,
                fallbackValue
            );

        while (
            !option &&
            Date.now() < deadline
        ) {
            await sleep(120);

            option =
                findOption(
                    select,
                    text,
                    fallbackValue
                );
        }

        return option;
    }

    function triggerSelect(
        doc,
        select,
        option
    ) {
        select.value =
            option.value;

        option.selected =
            true;

        const win =
            doc.defaultView;

        if (win.jQuery) {
            const $select =
                win.jQuery(select);

            $select
                .val(option.value)
                .trigger({
                    type:
                        'select2:select',
                    params: {
                        data: {
                            id:
                                option.value,
                            text:
                                String(
                                    option.textContent ||
                                    ''
                                ).trim(),
                            element:
                                option
                        }
                    }
                })
                .trigger('change');
        }

        select.dispatchEvent(
            new win.Event(
                'input',
                {
                    bubbles: true
                }
            )
        );

        select.dispatchEvent(
            new win.Event(
                'change',
                {
                    bubbles: true
                }
            )
        );
    }

    async function chooseSelect2OptionByClick(
        doc,
        select,
        desiredText
    ) {
        const visual =
            getSelectVisual(
                select
            );

        if (!isVisible(visual)) {
            return false;
        }

        const clickTarget =
            visual.querySelector(
                '.select2-selection'
            ) ||
            visual;

        realClick(clickTarget);

        await sleep(180);

        const target =
            normalize(desiredText);

        const options =
            Array.from(
                doc.querySelectorAll(
                    '.select2-results__option,' +
                    '[role="option"]'
                )
            ).filter(
                function (option) {
                    return (
                        isVisible(option) &&
                        normalize(
                            option.innerText ||
                            option.textContent
                        ) === target
                    );
                }
            );

        if (!options.length) {
            return false;
        }

        const visualRect =
            visual.getBoundingClientRect();

        options.sort(function (a, b) {
            const rectA =
                a.getBoundingClientRect();

            const rectB =
                b.getBoundingClientRect();

            const scoreA =
                Math.abs(
                    rectA.left -
                    visualRect.left
                ) +
                Math.abs(
                    rectA.top -
                    visualRect.bottom
                );

            const scoreB =
                Math.abs(
                    rectB.left -
                    visualRect.left
                ) +
                Math.abs(
                    rectB.top -
                    visualRect.bottom
                );

            return scoreA - scoreB;
        });

        realClick(options[0]);

        await sleep(180);

        return true;
    }

    async function setSelectByText(
        doc,
        select,
        text
    ) {
        const option =
            findOption(
                select,
                text
            );

        if (!option) {
            const available =
                Array.from(
                    select.options
                )
                    .map(
                        function (item) {
                            return normalize(
                                item.textContent
                            );
                        }
                    )
                    .filter(Boolean)
                    .join('、');

            throw new Error(
                '没有“' +
                text +
                '”选项，可选项：' +
                (available || '空')
            );
        }

        triggerSelect(
            doc,
            select,
            option
        );

        await sleep(120);

        if (
            String(select.value) !==
            String(option.value)
        ) {
            await chooseSelect2OptionByClick(
                doc,
                select,
                text
            );
        }

        if (
            String(select.value) !==
            String(option.value)
        ) {
            throw new Error(
                '控件值写入后被页面还原'
            );
        }

        /*
         * 某些旧版Select2值已经写入，
         * 但显示文字没有自动更新。
         */
        const rendered =
            (
                select.id
                    ? doc.getElementById(
                        'select2-' +
                        select.id +
                        '-container'
                    )
                    : null
            ) ||
            getSelectVisual(select)
                .querySelector(
                    '.select2-selection__rendered'
                );

        if (
            rendered &&
            normalize(
                rendered.textContent
            ) !==
            normalize(text)
        ) {
            const displayText =
                String(
                    option.textContent ||
                    ''
                ).trim();

            rendered.textContent =
                displayText;

            rendered.title =
                displayText;
        }
    }

    /******************************************************************
     * 普通input、textarea定位和填写
     ******************************************************************/

    function findInputsNearLabel(
        label
    ) {
        const selector =
            'input:not([type="hidden"]):not([disabled]),' +
            'textarea:not([disabled])';

        const cell =
            label.closest('td,th');

        if (cell) {
            const sameCell =
                Array.from(
                    cell.querySelectorAll(
                        selector
                    )
                ).filter(isVisible);

            if (sameCell.length) {
                return sameCell;
            }

            let sibling =
                cell.nextElementSibling;

            for (
                let index = 0;
                sibling &&
                index < 4;
                index++
            ) {
                const controls =
                    Array.from(
                        sibling.querySelectorAll(
                            selector
                        )
                    ).filter(isVisible);

                if (controls.length) {
                    return controls;
                }

                sibling =
                    sibling.nextElementSibling;
            }

            const row =
                cell.closest('tr');

            if (row) {
                const controls =
                    Array.from(
                        row.querySelectorAll(
                            selector
                        )
                    ).filter(isVisible);

                if (controls.length) {
                    return controls;
                }
            }
        }

        return Array.from(
            label.ownerDocument
                .querySelectorAll(
                    selector
                )
        ).filter(isVisible);
    }

    function findInputNearLabel(
        label
    ) {
        return chooseNearestControl(
            label,
            findInputsNearLabel(
                label
            )
        );
    }

    function findInputByLabel(
        text,
        predicate
    ) {
        for (
            const doc of
            getAllDocuments()
        ) {
            const labels =
                findTextElements(
                    doc,
                    text,
                    false
                );

            for (
                const label of labels
            ) {
                if (
                    predicate &&
                    !predicate(label)
                ) {
                    continue;
                }

                const input =
                    findInputNearLabel(
                        label
                    );

                if (input) {
                    return {
                        doc: doc,
                        label: label,
                        input: input
                    };
                }
            }
        }

        return null;
    }

    function setInputValue(
        doc,
        input,
        value,
        blur
    ) {
        const shouldBlur =
            blur !== false;

        const win =
            doc.defaultView;

        const prototype =
            input instanceof
            win.HTMLTextAreaElement
                ? win
                    .HTMLTextAreaElement
                    .prototype
                : win
                    .HTMLInputElement
                    .prototype;

        const descriptor =
            Object.getOwnPropertyDescriptor(
                prototype,
                'value'
            );

        input.focus();

        if (
            descriptor &&
            descriptor.set
        ) {
            descriptor.set.call(
                input,
                String(value)
            );
        } else {
            input.value =
                String(value);
        }

        input.dispatchEvent(
            new win.Event(
                'input',
                {
                    bubbles: true
                }
            )
        );

        input.dispatchEvent(
            new win.Event(
                'change',
                {
                    bubbles: true
                }
            )
        );

        input.dispatchEvent(
            new win.KeyboardEvent(
                'keyup',
                {
                    bubbles: true,
                    key: ''
                }
            )
        );

        if (shouldBlur) {
            input.blur();
        }
    }

    function setInputValueWithoutFocus(
        doc,
        input,
        value
    ) {
        const win =
            doc.defaultView;

        const prototype =
            input instanceof
            win.HTMLTextAreaElement
                ? win
                    .HTMLTextAreaElement
                    .prototype
                : win
                    .HTMLInputElement
                    .prototype;

        const descriptor =
            Object.getOwnPropertyDescriptor(
                prototype,
                'value'
            );

        if (
            descriptor &&
            descriptor.set
        ) {
            descriptor.set.call(
                input,
                String(value)
            );
        } else {
            input.value =
                String(value);
        }

        input.setAttribute(
            'value',
            String(value)
        );

        if (win.jQuery) {
            win.jQuery(input)
                .val(String(value))
                .trigger('input')
                .trigger('change');
        }

        input.dispatchEvent(
            new win.Event(
                'input',
                {
                    bubbles: true
                }
            )
        );

        input.dispatchEvent(
            new win.Event(
                'change',
                {
                    bubbles: true
                }
            )
        );
    }

    /******************************************************************
     * 模拟鼠标、键盘操作
     ******************************************************************/

    function realClick(
        element
    ) {
        if (!element) {
            return;
        }

        const win =
            element.ownerDocument
                .defaultView;

        element.dispatchEvent(
            new win.MouseEvent(
                'mousedown',
                {
                    bubbles: true,
                    cancelable: true,
                    view: win
                }
            )
        );

        element.dispatchEvent(
            new win.MouseEvent(
                'mouseup',
                {
                    bubbles: true,
                    cancelable: true,
                    view: win
                }
            )
        );

        element.click();
    }

    function realDoubleClick(
        element
    ) {
        if (!element) {
            return;
        }

        const win =
            element.ownerDocument
                .defaultView;

        element.dispatchEvent(
            new win.MouseEvent(
                'dblclick',
                {
                    bubbles: true,
                    cancelable: true,
                    view: win,
                    detail: 2
                }
            )
        );
    }

    function pressKey(
        element,
        key,
        keyCode
    ) {
        const win =
            element.ownerDocument
                .defaultView;

        const options = {
            key: key,
            code: key,
            keyCode: keyCode,
            which: keyCode,
            bubbles: true,
            cancelable: true
        };

        element.dispatchEvent(
            new win.KeyboardEvent(
                'keydown',
                options
            )
        );

        element.dispatchEvent(
            new win.KeyboardEvent(
                'keyup',
                options
            )
        );
    }

    /******************************************************************
     * 地址复制
     ******************************************************************/

    function collectRowSelects(
        label
    ) {
        const selector =
            'select.select2-hidden-accessible,select';

        const labelRect =
            label.getBoundingClientRect();

        const labelCenterY =
            labelRect.top +
            labelRect.height / 2;

        const scopes = [];

        const row =
            label.closest('tr');

        if (row) {
            scopes.push(row);
        }

        let parent =
            label.parentElement;

        for (
            let index = 0;
            parent &&
            index < 6;
            index++
        ) {
            if (
                !scopes.includes(
                    parent
                )
            ) {
                scopes.push(parent);
            }

            parent =
                parent.parentElement;
        }

        scopes.push(
            label.ownerDocument
        );

        for (
            const scope of scopes
        ) {
            let selects = [];

            try {
                selects =
                    Array.from(
                        scope.querySelectorAll(
                            selector
                        )
                    );
            } catch (error) {
                continue;
            }

            const candidates =
                selects
                    .map(
                        function (select) {
                            return {
                                select: select,
                                rect:
                                    getSelectRect(
                                        select
                                    )
                            };
                        }
                    )
                    .filter(
                        function (item) {
                            const centerY =
                                item.rect.top +
                                item.rect.height /
                                    2;

                            return (
                                item.rect.width >
                                    0 &&
                                item.rect.height >
                                    0 &&
                                Math.abs(
                                    centerY -
                                    labelCenterY
                                ) <= 38 &&
                                item.rect.left >=
                                    labelRect.right -
                                    15
                            );
                        }
                    )
                    .sort(
                        function (a, b) {
                            return (
                                a.rect.left -
                                b.rect.left
                            );
                        }
                    );

            if (
                candidates.length
            ) {
                return candidates.map(
                    function (item) {
                        return item.select;
                    }
                );
            }
        }

        return [];
    }

    function findAddressGroup(
        labelText
    ) {
        for (
            const doc of
            getAllDocuments()
        ) {
            const labels =
                findTextElements(
                    doc,
                    labelText,
                    false
                );

            for (
                const label of labels
            ) {
                const selects =
                    collectRowSelects(
                        label
                    );

                if (selects.length) {
                    return {
                        doc: doc,
                        label: label,
                        selects: selects
                    };
                }
            }
        }

        return null;
    }

    function findContactAddressGroup() {
        for (
            const doc of
            getAllDocuments()
        ) {
            const labels =
                findTextElements(
                    doc,
                    '地址',
                    false
                );

            for (
                const label of labels
            ) {
                const row =
                    label.closest('tr') ||
                    label.parentElement;

                const rowText =
                    normalize(
                        row
                            ? row.innerText ||
                              row.textContent
                            : ''
                    );

                if (
                    !rowText.includes(
                        '联系人'
                    )
                ) {
                    continue;
                }

                const selects =
                    collectRowSelects(
                        label
                    );

                if (selects.length) {
                    return {
                        doc: doc,
                        label: label,
                        selects: selects
                    };
                }
            }
        }

        return null;
    }

    function selectedData(
        select
    ) {
        const option =
            select.options[
                select.selectedIndex
            ];

        if (!option) {
            return {
                text: '',
                value: ''
            };
        }

        return {
            text:
                String(
                    option.textContent ||
                    ''
                ).trim(),
            value:
                option.value
        };
    }

    function getBirthplaceRegion() {
        const group =
            findAddressGroup(
                '出生地'
            );

        if (
            !group ||
            group.selects.length < 3
        ) {
            throw new Error(
                '未找到出生地的省、市、区三个下拉框'
            );
        }

        const items =
            group.selects
                .slice(0, 3)
                .map(selectedData);

        if (
            items.some(
                function (item) {
                    return !normalize(
                        item.text
                    );
                }
            )
        ) {
            throw new Error(
                '出生地省、市、区存在空值'
            );
        }

        return {
            items: items,
            text:
                items
                    .map(
                        function (item) {
                            return item.text;
                        }
                    )
                    .join('')
        };
    }

    async function copyRegionToGroup(
        groupFinder,
        region,
        targetName
    ) {
        for (
            let index = 0;
            index < 3;
            index++
        ) {
            const group =
                groupFinder();

            if (
                !group ||
                group.selects.length <=
                    index
            ) {
                throw new Error(
                    targetName +
                    '缺少第' +
                    (index + 1) +
                    '级地址下拉框'
                );
            }

            const select =
                group.selects[index];

            const source =
                region.items[index];

            const option =
                await waitForOption(
                    select,
                    source.text,
                    source.value,
                    4500
                );

            if (!option) {
                throw new Error(
                    targetName +
                    '未找到地址选项“' +
                    source.text +
                    '”'
                );
            }

            triggerSelect(
                group.doc,
                select,
                option
            );

            /*
             * 地址是级联下拉框，
             * 上一级改变后等待下一级加载。
             */
            await sleep(500);
        }
    }

    async function fillAddressInformation() {
        const region =
            getBirthplaceRegion();

        const successes = [];
        const failures = [];

        async function attempt(
            name,
            fn
        ) {
            try {
                await fn();

                successes.push(name);
            } catch (error) {
                failures.push(
                    name +
                    '：' +
                    error.message
                );
            }
        }

        await attempt(
            '现住址',
            function () {
                return copyRegionToGroup(
                    function () {
                        return findAddressGroup(
                            '现住址'
                        );
                    },
                    region,
                    '现住址'
                );
            }
        );

        await attempt(
            '户口地址',
            function () {
                return copyRegionToGroup(
                    function () {
                        return findAddressGroup(
                            '户口地址'
                        );
                    },
                    region,
                    '户口地址'
                );
            }
        );

        await attempt(
            '工作单位及地址',
            async function () {
                const target =
                    findInputByLabel(
                        '工作单位及地址'
                    );

                if (!target) {
                    throw new Error(
                        '未找到输入框'
                    );
                }

                setInputValue(
                    target.doc,
                    target.input,
                    region.text
                );
            }
        );

        await attempt(
            '联系人地址',
            async function () {
                const group =
                    findContactAddressGroup();

                if (
                    group &&
                    group.selects.length >= 3
                ) {
                    await copyRegionToGroup(
                        findContactAddressGroup,
                        region,
                        '联系人地址'
                    );

                    return;
                }

                const target =
                    findInputByLabel(
                        '地址',
                        function (label) {
                            const row =
                                label.closest('tr') ||
                                label.parentElement;

                            const rowText =
                                normalize(
                                    row
                                        ? row.innerText ||
                                          row.textContent
                                        : ''
                                );

                            return rowText.includes(
                                '联系人'
                            );
                        }
                    );

                if (!target) {
                    throw new Error(
                        '未找到联系人地址控件'
                    );
                }

                setInputValue(
                    target.doc,
                    target.input,
                    region.text
                );
            }
        );

        if (failures.length) {
            throw new Error(
                '已完成' +
                successes.length +
                '项；' +
                failures.join('；')
            );
        }
    }

    /******************************************************************
     * 电话、邮编、籍贯
     ******************************************************************/

    function findPatientPhoneSource() {
        for (
            const doc of
            getAllDocuments()
        ) {
            const currentAddress =
                findLabel(
                    doc,
                    '现住址'
                );

            if (!currentAddress) {
                continue;
            }

            const addressRect =
                currentAddress
                    .getBoundingClientRect();

            const addressCenterY =
                addressRect.top +
                addressRect.height / 2;

            const candidates = [];

            const phoneLabels =
                findTextElements(
                    doc,
                    '电话',
                    false
                );

            for (
                const phoneLabel of
                phoneLabels
            ) {
                const input =
                    findInputNearLabel(
                        phoneLabel
                    );

                if (!input) {
                    continue;
                }

                const labelRect =
                    phoneLabel
                        .getBoundingClientRect();

                const value =
                    String(
                        input.value ||
                        ''
                    ).trim();

                candidates.push({
                    value: value,
                    validPhone:
                        /^1\d{10}$/.test(
                            value
                        ),
                    verticalDistance:
                        Math.abs(
                            (
                                labelRect.top +
                                labelRect.height /
                                    2
                            ) -
                            addressCenterY
                        )
                });
            }

            candidates.sort(
                function (a, b) {
                    if (
                        a.validPhone !==
                        b.validPhone
                    ) {
                        return a.validPhone
                            ? -1
                            : 1;
                    }

                    return (
                        a.verticalDistance -
                        b.verticalDistance
                    );
                }
            );

            if (
                candidates[0] &&
                candidates[0].value
            ) {
                return candidates[0]
                    .value;
            }
        }

        return '';
    }

    function fillUnitPhone() {
        const phone =
            findPatientPhoneSource();

        if (!phone) {
            throw new Error(
                '未找到患者电话或患者电话为空'
            );
        }

        const target =
            findInputByLabel(
                '单位电话'
            );

        if (!target) {
            throw new Error(
                '未找到单位电话输入框'
            );
        }

        setInputValue(
            target.doc,
            target.input,
            phone
        );

        return phone;
    }

    function fillPostalCodes() {
        const filled =
            new Set();

        for (
            const doc of
            getAllDocuments()
        ) {
            const labels =
                findTextElements(
                    doc,
                    '邮编',
                    false
                );

            for (
                const label of labels
            ) {
                const input =
                    findInputNearLabel(
                        label
                    );

                if (
                    !input ||
                    filled.has(input)
                ) {
                    continue;
                }

                setInputValue(
                    doc,
                    input,
                    POSTAL_CODE
                );

                filled.add(input);
            }
        }

        if (!filled.size) {
            throw new Error(
                '未找到邮编输入框'
            );
        }

        return filled.size;
    }


    /******************************************************************
     * DeepSeek按住址二次修正邮编
     *
     * 隐私原则：只发送地址文字，不发送患者姓名、电话、身份证号。
     * 安全原则：仅在返回6位邮编且置信度为high/medium时自动覆盖；
     * low置信度只提示，不覆盖原邮编。
     ******************************************************************/

    function getDeepSeekPostalSettings() {
        return {
            apiKey:
                String(
                    GM_getValue(
                        AI_STORAGE_KEYS.apiKey,
                        ''
                    ) || ''
                ).trim(),

            model:
                String(
                    GM_getValue(
                        AI_STORAGE_KEYS.model,
                        DEFAULT_DEEPSEEK_MODEL
                    ) ||
                    DEFAULT_DEEPSEEK_MODEL
                ).trim() ||
                DEFAULT_DEEPSEEK_MODEL
        };
    }

    function sanitizeAddressForAi(
        value
    ) {
        return String(value || '')
            .replace(
                /\b1\d{10}\b/g,
                ''
            )
            .replace(
                /\b\d{17}[\dXx]\b/g,
                ''
            )
            .replace(
                /\s+/g,
                ''
            )
            .trim();
    }

    function selectedRegionText(
        selects
    ) {
        return (
            Array.isArray(selects)
                ? selects
                : []
        )
            .slice(0, 3)
            .map(
                function (select) {
                    return selectedData(
                        select
                    ).text;
                }
            )
            .filter(Boolean)
            .join('');
    }

    function collectInputsOnAnchorRow(
        doc,
        anchor
    ) {
        if (
            !doc ||
            !anchor
        ) {
            return [];
        }

        const anchorRect =
            anchor.getBoundingClientRect();

        const centerY =
            anchorRect.top +
            anchorRect.height / 2;

        return Array.from(
            doc.querySelectorAll(
                'input:not([type="hidden"]):not([disabled]),' +
                'textarea:not([disabled])'
            )
        )
            .filter(isVisible)
            .filter(
                function (input) {
                    const rect =
                        input.getBoundingClientRect();

                    const inputCenterY =
                        rect.top +
                        rect.height / 2;

                    return (
                        Math.abs(
                            inputCenterY -
                            centerY
                        ) <= 35
                    );
                }
            )
            .sort(
                function (first, second) {
                    return (
                        first
                            .getBoundingClientRect()
                            .left -
                        second
                            .getBoundingClientRect()
                            .left
                    );
                }
            );
    }

    function findAddressDetailOnRow(
        doc,
        anchor,
        minimumLeft
    ) {
        const inputs =
            collectInputsOnAnchorRow(
                doc,
                anchor
            );

        const candidates =
            inputs
                .map(
                    function (input) {
                        return {
                            input: input,
                            value:
                                String(
                                    input.value ||
                                    ''
                                ).trim(),
                            rect:
                                input
                                    .getBoundingClientRect()
                        };
                    }
                )
                .filter(
                    function (item) {
                        if (!item.value) {
                            return false;
                        }

                        if (
                            Number.isFinite(
                                minimumLeft
                            ) &&
                            item.rect.left <
                                minimumLeft - 12
                        ) {
                            return false;
                        }

                        if (
                            /^1\d{10}$/.test(
                                item.value
                            ) ||
                            /^\d{6}$/.test(
                                item.value
                            ) ||
                            /^\d{4}-\d{1,2}-\d{1,2}/.test(
                                item.value
                            )
                        ) {
                            return false;
                        }

                        return true;
                    }
                );

        return candidates[0]
            ? candidates[0].value
            : '';
    }

    function buildAddressFromGroup(
        group
    ) {
        if (
            !group ||
            !group.doc ||
            !group.label
        ) {
            return '';
        }

        const regionText =
            selectedRegionText(
                group.selects
            );

        const lastSelect =
            group.selects &&
            group.selects.length
                ? group.selects[
                    Math.min(
                        group.selects.length,
                        3
                    ) - 1
                ]
                : null;

        const minimumLeft =
            lastSelect
                ? getSelectRect(
                    lastSelect
                ).right
                : group.label
                    .getBoundingClientRect()
                    .right;

        const detail =
            findAddressDetailOnRow(
                group.doc,
                group.label,
                minimumLeft
            );

        const cleanRegion =
            sanitizeAddressForAi(
                regionText
            );

        const cleanDetail =
            sanitizeAddressForAi(
                detail
            );

        if (
            cleanDetail &&
            !cleanRegion.includes(
                cleanDetail
            )
        ) {
            return (
                cleanRegion +
                cleanDetail
            );
        }

        return cleanRegion ||
            cleanDetail;
    }

    function findPostalInputNearAnchor(
        doc,
        anchor
    ) {
        if (
            !doc ||
            !anchor
        ) {
            return null;
        }

        const anchorRect =
            anchor.getBoundingClientRect();

        const anchorCenterY =
            anchorRect.top +
            anchorRect.height / 2;

        const candidates = [];

        findTextElements(
            doc,
            '邮编',
            false
        ).forEach(
            function (postalLabel) {
                const input =
                    findInputNearLabel(
                        postalLabel
                    );

                if (
                    !input ||
                    !isVisible(input)
                ) {
                    return;
                }

                const labelRect =
                    postalLabel
                        .getBoundingClientRect();

                const inputRect =
                    input
                        .getBoundingClientRect();

                const postalCenterY =
                    (
                        labelRect.top +
                        labelRect.height / 2 +
                        inputRect.top +
                        inputRect.height / 2
                    ) / 2;

                candidates.push({
                    input: input,
                    score:
                        Math.abs(
                            postalCenterY -
                            anchorCenterY
                        ) * 50 +
                        Math.abs(
                            inputRect.left -
                            anchorRect.right
                        )
                });
            }
        );

        candidates.sort(
            function (first, second) {
                return (
                    first.score -
                    second.score
                );
            }
        );

        return candidates[0]
            ? candidates[0].input
            : null;
    }

    function makeAddressPostalTarget(
        key,
        label,
        address,
        doc,
        anchor
    ) {
        const cleanAddress =
            sanitizeAddressForAi(
                address
            );

        if (!cleanAddress) {
            return null;
        }

        const postalInput =
            findPostalInputNearAnchor(
                doc,
                anchor
            );

        if (!postalInput) {
            return null;
        }

        return {
            key: key,
            label: label,
            address: cleanAddress,
            doc: doc,
            input: postalInput,
            originalPostalCode:
                String(
                    postalInput.value ||
                    ''
                ).trim()
        };
    }

    function collectAddressPostalTargets() {
        const targets = [];
        const usedInputs =
            new Set();

        function addTarget(
            target
        ) {
            if (
                !target ||
                usedInputs.has(
                    target.input
                )
            ) {
                return;
            }

            usedInputs.add(
                target.input
            );

            targets.push(
                target
            );
        }

        const currentAddress =
            findAddressGroup(
                '现住址'
            );

        if (currentAddress) {
            addTarget(
                makeAddressPostalTarget(
                    'currentAddress',
                    '现住址',
                    buildAddressFromGroup(
                        currentAddress
                    ),
                    currentAddress.doc,
                    currentAddress.label
                )
            );
        }

        const registeredAddress =
            findAddressGroup(
                '户口地址'
            );

        if (registeredAddress) {
            addTarget(
                makeAddressPostalTarget(
                    'registeredAddress',
                    '户口地址',
                    buildAddressFromGroup(
                        registeredAddress
                    ),
                    registeredAddress.doc,
                    registeredAddress.label
                )
            );
        }

        const workAddress =
            findInputByLabel(
                '工作单位及地址'
            );

        if (workAddress) {
            addTarget(
                makeAddressPostalTarget(
                    'workAddress',
                    '工作单位及地址',
                    workAddress.input.value,
                    workAddress.doc,
                    workAddress.label
                )
            );
        }

        const contactGroup =
            findContactAddressGroup();

        if (contactGroup) {
            addTarget(
                makeAddressPostalTarget(
                    'contactAddress',
                    '联系人地址',
                    buildAddressFromGroup(
                        contactGroup
                    ),
                    contactGroup.doc,
                    contactGroup.label
                )
            );
        } else {
            const contactAddress =
                findInputByLabel(
                    '地址',
                    function (labelElement) {
                        const row =
                            labelElement.closest(
                                'tr'
                            ) ||
                            labelElement
                                .parentElement;

                        return normalize(
                            row
                                ? row.innerText ||
                                  row.textContent
                                : ''
                        ).includes(
                            '联系人'
                        );
                    }
                );

            if (contactAddress) {
                addTarget(
                    makeAddressPostalTarget(
                        'contactAddress',
                        '联系人地址',
                        contactAddress
                            .input.value,
                        contactAddress.doc,
                        contactAddress.label
                    )
                );
            }
        }

        return targets;
    }

    function extractJsonFromAiText(
        value
    ) {
        const source =
            String(value || '')
                .trim();

        try {
            return JSON.parse(source);
        } catch (firstError) {
            const clean =
                source
                    .replace(
                        /^```(?:json)?\s*/i,
                        ''
                    )
                    .replace(
                        /\s*```$/i,
                        ''
                    )
                    .trim();

            try {
                return JSON.parse(clean);
            } catch (secondError) {
                const start =
                    clean.indexOf('{');

                const end =
                    clean.lastIndexOf('}');

                if (
                    start >= 0 &&
                    end > start
                ) {
                    return JSON.parse(
                        clean.slice(
                            start,
                            end + 1
                        )
                    );
                }

                throw secondError;
            }
        }
    }

    function requestPostalCodesFromDeepSeek(
        settings,
        targets
    ) {
        return new Promise(
            function (resolve, reject) {
                suiteGlobalAiXmlhttpRequest({
                    method: 'POST',
                    url:
                        DEEPSEEK_ENDPOINT,
                    headers: {
                        'Content-Type':
                            'application/json',

                        Authorization:
                            'Bearer ' +
                            settings.apiKey
                    },
                    data: JSON.stringify({
                        model:
                            settings.model,

                        messages: [
                            {
                                role: 'system',
                                content: [
                                    '你是中国大陆地址邮政编码核对工具。',
                                    '只返回JSON对象，不要输出Markdown或解释性前后缀。',
                                    '必须根据address独立判断邮编，不得照抄currentPostalCode；currentPostalCode只是医院表单中的占位值，可能属于别的城市。',
                                    '根据每条地址给出最可能的6位邮政编码。',
                                    '地址只精确到市、区县时，也必须返回该市或区县最常用的通用邮编，并将confidence设为medium。',
                                    '地址精确到街道、乡镇、道路或明确机构时，可根据确定程度返回medium或high。',
                                    '如果行政区与详细地址发生冲突，优先采用更完整、更具体、层级更高可信的地址片段，并在reason中说明。',
                                    '不得把电话、身份证号当作地址信息。',
                                    '只有完全无法判断时postalCode才返回空字符串；严禁返回非6位数字。',
                                    '例如：山东省青岛市市南区未给出具体门牌时，应返回该区域常用通用邮编，而不能沿用济南市占位邮编250000。',
                                    '返回结构固定为：',
                                    '{"results":[{"key":"currentAddress","postalCode":"266000","confidence":"high|medium|low","reason":"不超过40字"}]}'
                                ].join('\n')
                            },
                            {
                                role: 'user',
                                content:
                                    JSON.stringify({
                                        addresses:
                                            targets.map(
                                                function (target) {
                                                    return {
                                                        key:
                                                            target.key,
                                                        label:
                                                            target.label,
                                                        address:
                                                            target.address,

                                                        currentPostalCode:
                                                            target.originalPostalCode ||
                                                            POSTAL_CODE,

                                                        note:
                                                            'currentPostalCode仅为占位值，请按address独立判断'
                                                    };
                                                }
                                            )
                                    })
                            }
                        ],
                        response_format: {
                            type:
                                'json_object'
                        },
                        temperature: 0,
                        max_tokens: 1600,
                        stream: false
                    }),
                    timeout: 90000,
                    onload:
                        function (response) {
                            if (
                                response.status < 200 ||
                                response.status >= 300
                            ) {
                                reject(
                                    new Error(
                                        'DeepSeek接口返回HTTP ' +
                                        response.status +
                                        '：' +
                                        String(
                                            response.responseText ||
                                            ''
                                        ).slice(
                                            0,
                                            500
                                        )
                                    )
                                );
                                return;
                            }

                            try {
                                const outer =
                                    JSON.parse(
                                        response.responseText
                                    );

                                const content =
                                    outer &&
                                    outer.choices &&
                                    outer.choices[0] &&
                                    outer.choices[0]
                                        .message
                                        ? outer
                                            .choices[0]
                                            .message
                                            .content
                                        : '';

                                if (!content) {
                                    throw new Error(
                                        '接口未返回有效内容'
                                    );
                                }

                                resolve(
                                    extractJsonFromAiText(
                                        content
                                    )
                                );
                            } catch (error) {
                                reject(
                                    new Error(
                                        'DeepSeek邮编结果解析失败：' +
                                        error.message
                                    )
                                );
                            }
                        },
                    onerror:
                        function () {
                            reject(
                                new Error(
                                    'DeepSeek网络请求失败'
                                )
                            );
                        },
                    ontimeout:
                        function () {
                            reject(
                                new Error(
                                    'DeepSeek请求超时'
                                )
                            );
                        }
                });
            }
        );
    }

    function shouldReplaceLowConfidencePostal(
        target,
        postalCode
    ) {
        const original =
            String(
                target.originalPostalCode ||
                ''
            ).trim();

        /*
         * 默认邮编只是批量占位值。
         * 当AI返回另一个有效6位邮编时，即使置信度为low，
         * 也允许覆盖占位值，避免青岛地址仍保留济南250000。
         */
        return (
            /^\d{6}$/.test(
                postalCode
            ) &&
            postalCode !== original &&
            (
                !original ||
                original === POSTAL_CODE
            )
        );
    }

    async function writePostalCodeAndVerify(
        target,
        postalCode
    ) {
        setInputValue(
            target.doc,
            target.input,
            postalCode,
            false
        );

        setInputValueWithoutFocus(
            target.doc,
            target.input,
            postalCode
        );

        target.input.blur();

        await sleep(180);

        if (
            String(
                target.input.value ||
                ''
            ).trim() !== postalCode
        ) {
            setInputValueWithoutFocus(
                target.doc,
                target.input,
                postalCode
            );

            target.input.setAttribute(
                'value',
                postalCode
            );

            target.input.dispatchEvent(
                new target.doc.defaultView.Event(
                    'blur',
                    {
                        bubbles: true
                    }
                )
            );

            await sleep(220);
        }

        const finalValue =
            String(
                target.input.value ||
                ''
            ).trim();

        if (finalValue !== postalCode) {
            throw new Error(
                target.label +
                '邮编写入后被页面还原，当前值：' +
                finalValue
            );
        }
    }

    async function correctPostalCodesWithDeepSeek() {
        const settings =
            getDeepSeekPostalSettings();

        if (!suiteGlobalAiHasApiKey(settings.apiKey)) {
            throw new Error(
                '尚未配置当前AI服务所需API Key，请在“默认值设置－DeepSeek邮编修正”或悬浮框管理器中配置'
            );
        }

        const targets =
            collectAddressPostalTargets();

        if (!targets.length) {
            throw new Error(
                '未识别到可用于AI修正的地址及对应邮编输入框'
            );
        }

        showStatus(
            '正在将' +
            targets.length +
            '条地址发送给DeepSeek核对邮编……\n' +
            '仅发送地址文本，不发送姓名、电话和身份证号。'
        );

        const rawResult =
            await requestPostalCodesFromDeepSeek(
                settings,
                targets
            );

        const results =
            rawResult &&
            Array.isArray(
                rawResult.results
            )
                ? rawResult.results
                : [];

        const resultMap =
            new Map();

        results.forEach(
            function (item) {
                if (
                    item &&
                    item.key
                ) {
                    resultMap.set(
                        String(item.key),
                        item
                    );
                }
            }
        );

        const corrected = [];
        const retained = [];
        const failed = [];

        for (
            const target of targets
        ) {
            const item =
                resultMap.get(
                    target.key
                );

            if (!item) {
                failed.push(
                    target.label +
                    '：AI未返回结果'
                );
                continue;
            }

            const postalCode =
                String(
                    item.postalCode ||
                    ''
                ).trim();

            const confidence =
                String(
                    item.confidence ||
                    'low'
                )
                    .trim()
                    .toLowerCase();

            const reason =
                String(
                    item.reason ||
                    ''
                ).trim();

            if (
                !/^\d{6}$/.test(
                    postalCode
                )
            ) {
                failed.push(
                    target.label +
                    '：未得到有效6位邮编' +
                    (
                        reason
                            ? '（' +
                              reason +
                              '）'
                            : ''
                    )
                );
                continue;
            }

            const lowConfidenceOverride =
                confidence === 'low' &&
                shouldReplaceLowConfidencePostal(
                    target,
                    postalCode
                );

            if (
                confidence !== 'high' &&
                confidence !== 'medium' &&
                !lowConfidenceOverride
            ) {
                retained.push(
                    target.label +
                    '：保留' +
                    (
                        target.originalPostalCode ||
                        POSTAL_CODE
                    ) +
                    '，AI低置信度候选' +
                    postalCode +
                    (
                        reason
                            ? '（' +
                              reason +
                              '）'
                            : ''
                    )
                );
                continue;
            }

            try {
                await writePostalCodeAndVerify(
                    target,
                    postalCode
                );

                corrected.push(
                    target.label +
                    '：' +
                    (
                        target.originalPostalCode ||
                        '空'
                    ) +
                    ' → ' +
                    postalCode +
                    '（' +
                    (
                        lowConfidenceOverride
                            ? 'low，占位邮编允许覆盖'
                            : confidence
                    ) +
                    (
                        reason
                            ? '，' +
                              reason
                            : ''
                    ) +
                    '）'
                );
            } catch (error) {
                failed.push(
                    error.message ||
                    (
                        target.label +
                        '：邮编写入失败'
                    )
                );
            }
        }

        if (
            !corrected.length &&
            !retained.length
        ) {
            throw new Error(
                'DeepSeek未返回可用邮编：' +
                (
                    failed.join('；') ||
                    '结果为空'
                )
            );
        }

        return {
            targetCount:
                targets.length,
            corrected:
                corrected,
            retained:
                retained,
            failed:
                failed
        };
    }

    function fillNativePlace() {
        const target =
            findInputByLabel(
                '籍贯'
            );

        if (!target) {
            throw new Error(
                '未找到籍贯输入框'
            );
        }

        setInputValue(
            target.doc,
            target.input,
            USER_CONFIG.nativePlace
        );

        return USER_CONFIG.nativePlace;
    }

    /******************************************************************
     * 职业、入院科别、出院科别
     ******************************************************************/

    function findLookupInput(
        task
    ) {
        for (
            const doc of
            getAllDocuments()
        ) {
            const label =
                findLabel(
                    doc,
                    task.label
                );

            if (!label) {
                continue;
            }

            const controls =
                findInputsNearLabel(
                    label
                ).filter(
                    function (input) {
                        return !input.disabled;
                    }
                );

            const input =
                chooseNearestControl(
                    label,
                    controls
                );

            if (input) {
                return {
                    doc: doc,
                    input: input
                };
            }
        }

        return null;
    }

    function findLookupResult(
        doc,
        input,
        task
    ) {
        const code =
            normalizeLookup(
                task.code
            );

        const name =
            normalizeLookup(
                task.name
            );

        const inputRect =
            input.getBoundingClientRect();

        const rowSelector = [
            'tr',
            '[role="row"]',
            '.datagrid-row',
            '.jqgrow',
            '.layui-table-row',
            '.dropdown-menu li',
            '.autocomplete-suggestion'
        ].join(',');

        const rows =
            Array.from(
                doc.querySelectorAll(
                    rowSelector
                )
            )
                .filter(isVisible)
                .filter(
                    function (row) {
                        const text =
                            normalizeLookup(
                                row.innerText ||
                                row.textContent
                            );

                        return (
                            text.includes(
                                code
                            ) &&
                            text.includes(
                                name
                            )
                        );
                    }
                );

        if (!rows.length) {
            return null;
        }

        const candidates =
            rows.map(
                function (row) {
                    const rect =
                        row.getBoundingClientRect();

                    const belowPenalty =
                        rect.top >=
                        inputRect.bottom - 5
                            ? 0
                            : 2000;

                    return {
                        row: row,
                        score:
                            belowPenalty +
                            Math.abs(
                                rect.top -
                                inputRect.bottom
                            ) +
                            Math.abs(
                                rect.left -
                                inputRect.left
                            )
                    };
                }
            );

        candidates.sort(
            function (a, b) {
                return a.score - b.score;
            }
        );

        const row =
            candidates[0].row;

        const target =
            Array.from(
                row.querySelectorAll(
                    'td,div,span,' +
                    '[role="gridcell"]'
                )
            ).find(
                function (element) {
                    return (
                        isVisible(element) &&
                        normalizeLookup(
                            element.innerText ||
                            element.textContent
                        ) === name
                    );
                }
            ) ||
            row;

        return {
            row: row,
            target: target
        };
    }

    /*
     * 保存被脚本临时隐藏的检索弹层。
     */
    const FORCED_LOOKUP_PANELS = [];

    function restoreForcedLookupPanels(
        doc
    ) {
        for (
            let index =
                FORCED_LOOKUP_PANELS.length -
                1;
            index >= 0;
            index--
        ) {
            const record =
                FORCED_LOOKUP_PANELS[index];

            if (
                record.doc !== doc
            ) {
                continue;
            }

            const element =
                record.element;

            if (
                element &&
                element.isConnected
            ) {
                if (record.display) {
                    element.style.setProperty(
                        'display',
                        record.display,
                        record.displayPriority
                    );
                } else {
                    element.style.removeProperty(
                        'display'
                    );
                }

                if (record.visibility) {
                    element.style.setProperty(
                        'visibility',
                        record.visibility,
                        record.visibilityPriority
                    );
                } else {
                    element.style.removeProperty(
                        'visibility'
                    );
                }

                if (record.pointerEvents) {
                    element.style.setProperty(
                        'pointer-events',
                        record.pointerEvents,
                        record.pointerEventsPriority
                    );
                } else {
                    element.style.removeProperty(
                        'pointer-events'
                    );
                }

                if (
                    record.ariaHidden ===
                    null
                ) {
                    element.removeAttribute(
                        'aria-hidden'
                    );
                } else {
                    element.setAttribute(
                        'aria-hidden',
                        record.ariaHidden
                    );
                }
            }

            if (record.listener) {
                record.doc.removeEventListener(
                    'mousedown',
                    record.listener,
                    true
                );
            }

            FORCED_LOOKUP_PANELS.splice(
                index,
                1
            );
        }
    }

    function getLookupPopupRoot(
        element
    ) {
        if (!element) {
            return null;
        }

        let current =
            element;

        let fallback =
            element;

        for (
            let level = 0;
            current &&
            level < 8;
            level++
        ) {
            const win =
                current.ownerDocument
                    .defaultView;

            const style =
                win.getComputedStyle(
                    current
                );

            const rect =
                current
                    .getBoundingClientRect();

            const classText =
                String(
                    current.className ||
                    ''
                ).toLowerCase();

            const looksLikePopup =
                (
                    style.position ===
                        'absolute' ||
                    style.position ===
                        'fixed' ||
                    /popup|dropdown|suggest|autocomplete|grid|table|lookup|list/.test(
                        classText
                    )
                ) &&
                rect.width >= 180 &&
                rect.height >= 45 &&
                rect.width <= 900 &&
                rect.height <= 650;

            if (looksLikePopup) {
                fallback =
                    current;
            }

            if (
                (
                    style.position ===
                        'absolute' ||
                    style.position ===
                        'fixed'
                ) &&
                rect.width >= 180 &&
                rect.height >= 45 &&
                rect.width <= 900 &&
                rect.height <= 650
            ) {
                return current;
            }

            current =
                current.parentElement;
        }

        return fallback;
    }

    function findVisibleLookupPopup(
        doc,
        input,
        task
    ) {
        if (
            !doc ||
            !input
        ) {
            return null;
        }

        const inputRect =
            input.getBoundingClientRect();

        const targetCode =
            normalizeLookup(
                task.code
            );

        const targetName =
            normalizeLookup(
                task.name
            );

        const candidates = [];
        const visited =
            new Set();

        const elements =
            Array.from(
                doc.querySelectorAll(
                    'div,table,ul'
                )
            );

        for (
            const element of elements
        ) {
            if (
                !isVisible(element)
            ) {
                continue;
            }

            const text =
                normalizeLookup(
                    element.innerText ||
                    element.textContent
                );

            const hasGenericHeader =
                text.includes('编码') &&
                text.includes('名称');

            const hasDepartmentHeader =
                text.includes('科室代码') &&
                text.includes('科室名称');

            const hasTarget =
                text.includes(
                    targetCode
                ) ||
                text.includes(
                    targetName
                );

            if (
                !hasGenericHeader &&
                !hasDepartmentHeader &&
                !hasTarget
            ) {
                continue;
            }

            const root =
                getLookupPopupRoot(
                    element
                );

            if (
                !root ||
                visited.has(root) ||
                !isVisible(root)
            ) {
                continue;
            }

            visited.add(root);

            const rect =
                root.getBoundingClientRect();

            if (
                rect.width < 180 ||
                rect.height < 45 ||
                rect.width > 900 ||
                rect.height > 650
            ) {
                continue;
            }

            const verticalDistance =
                Math.min(
                    Math.abs(
                        rect.top -
                        inputRect.bottom
                    ),
                    Math.abs(
                        rect.bottom -
                        inputRect.top
                    )
                );

            const horizontalDistance =
                Math.abs(
                    rect.left -
                    inputRect.left
                );

            if (
                verticalDistance > 700 ||
                horizontalDistance > 1000
            ) {
                continue;
            }

            const headerBonus =
                hasGenericHeader ||
                hasDepartmentHeader
                    ? -500
                    : 0;

            candidates.push({
                element: root,
                score:
                    verticalDistance +
                    horizontalDistance +
                    rect.width / 20 +
                    rect.height / 20 +
                    headerBonus
            });
        }

        if (!candidates.length) {
            return null;
        }

        candidates.sort(
            function (a, b) {
                return a.score - b.score;
            }
        );

        return candidates[0]
            .element;
    }

    function temporarilyHideLookupPopup(
        doc,
        popup
    ) {
        if (
            !popup ||
            !popup.isConnected
        ) {
            return;
        }

        const displayValue =
            popup.style.getPropertyValue(
                'display'
            );

        const displayPriority =
            popup.style.getPropertyPriority(
                'display'
            );

        const visibilityValue =
            popup.style.getPropertyValue(
                'visibility'
            );

        const visibilityPriority =
            popup.style.getPropertyPriority(
                'visibility'
            );

        const pointerEventsValue =
            popup.style.getPropertyValue(
                'pointer-events'
            );

        const pointerEventsPriority =
            popup.style.getPropertyPriority(
                'pointer-events'
            );

        const ariaHidden =
            popup.getAttribute(
                'aria-hidden'
            );

        popup.style.setProperty(
            'display',
            'none',
            'important'
        );

        popup.style.setProperty(
            'visibility',
            'hidden',
            'important'
        );

        popup.style.setProperty(
            'pointer-events',
            'none',
            'important'
        );

        popup.setAttribute(
            'aria-hidden',
            'true'
        );

        const record = {
            doc: doc,
            element: popup,

            display:
                displayValue,

            displayPriority:
                displayPriority,

            visibility:
                visibilityValue,

            visibilityPriority:
                visibilityPriority,

            pointerEvents:
                pointerEventsValue,

            pointerEventsPriority:
                pointerEventsPriority,

            ariaHidden:
                ariaHidden,

            listener:
                null
        };

        /*
         * 用户以后再次点击输入框时恢复组件，
         * 仍可手工重新选择。
         */
        const restoreListener =
            function (event) {
                const target =
                    event.target;

                if (
                    !target ||
                    !target.matches ||
                    !target.matches(
                        'input,textarea'
                    )
                ) {
                    return;
                }

                restoreForcedLookupPanels(
                    doc
                );
            };

        record.listener =
            restoreListener;

        FORCED_LOOKUP_PANELS.push(
            record
        );

        setTimeout(
            function () {
                doc.addEventListener(
                    'mousedown',
                    restoreListener,
                    true
                );
            },
            350
        );
    }

    function clickLookupOutside(
        doc
    ) {
        if (
            !doc ||
            !doc.body
        ) {
            return;
        }

        const dummy =
            doc.createElement(
                'button'
            );

        dummy.type =
            'button';

        dummy.tabIndex =
            -1;

        dummy.setAttribute(
            'aria-hidden',
            'true'
        );

        Object.assign(
            dummy.style,
            {
                position:
                    'fixed',

                left:
                    '-10000px',

                top:
                    '-10000px',

                width:
                    '1px',

                height:
                    '1px',

                opacity:
                    '0',

                pointerEvents:
                    'auto'
            }
        );

        doc.body.appendChild(
            dummy
        );

        dummy.focus();

        realClick(dummy);

        dummy.blur();

        dummy.remove();
    }

    /*
     * 主动关闭职业、入院科别、出院科别结果面板。
     *
     * 如果组件自身无法关闭，则临时隐藏面板，
     * 但不再把“列表未关闭”判定为填写失败。
     */
    async function closeLookupPopup(
        doc,
        input,
        task
    ) {
        if (
            !doc ||
            !input
        ) {
            return;
        }

        const win =
            doc.defaultView;

        input.focus();

        pressKey(
            input,
            'Escape',
            27
        );

        await sleep(80);

        pressKey(
            input,
            'Tab',
            9
        );

        input.blur();

        if (win.jQuery) {
            win.jQuery(input)
                .trigger('change')
                .trigger('blur');
        }

        input.dispatchEvent(
            new win.Event(
                'change',
                {
                    bubbles: true
                }
            )
        );

        input.dispatchEvent(
            new win.Event(
                'blur',
                {
                    bubbles: true
                }
            )
        );

        clickLookupOutside(
            doc
        );

        await sleep(220);

        if (
            findVisibleLookupPopup(
                doc,
                input,
                task
            )
        ) {
            input.focus();

            pressKey(
                input,
                'Escape',
                27
            );

            input.blur();

            clickLookupOutside(
                doc
            );

            await sleep(180);
        }

        const remainingPopup =
            findVisibleLookupPopup(
                doc,
                input,
                task
            );

        if (remainingPopup) {
            temporarilyHideLookupPopup(
                doc,
                remainingPopup
            );

            await sleep(100);
        }
    }

    /*
     * 只要字段最终显示目标名称，就判定选择成功。
     * 结果列表若不自动关闭，会主动关闭或隐藏。
     */
    async function fillLookupTask(
        task
    ) {
        const found =
            findLookupInput(
                task
            );

        if (!found) {
            throw new Error(
                '未找到“' +
                task.label +
                '”输入框'
            );
        }

        const doc =
            found.doc;

        const input =
            found.input;

        /*
         * 开始新的检索前，
         * 恢复上一次被临时隐藏的结果面板。
         */
        restoreForcedLookupPanels(
            doc
        );

        const targetName =
            normalizeLookup(
                task.name
            );

        /*
         * 字段已经正确时，
         * 只关闭可能残留的结果列表。
         */
        if (
            normalizeLookup(
                input.value
            ) === targetName
        ) {
            await closeLookupPopup(
                doc,
                input,
                task
            );

            return task.name;
        }

        input.scrollIntoView({
            block: 'center',
            behavior: 'auto'
        });

        realClick(input);

        await sleep(180);

        /*
         * 先按编码检索：
         * 职业80，中医科020105。
         */
        setInputValue(
            doc,
            input,
            task.code,
            false
        );

        await sleep(750);

        let result =
            findLookupResult(
                doc,
                input,
                task
            );

        /*
         * 编码未检索到结果时，
         * 再使用名称检索。
         */
        if (!result) {
            setInputValue(
                doc,
                input,
                task.name,
                false
            );

            await sleep(700);

            result =
                findLookupResult(
                    doc,
                    input,
                    task
                );
        }

        /*
         * 未识别到标准结果行时，
         * 先尝试键盘向下并回车。
         */
        if (!result) {
            input.focus();

            pressKey(
                input,
                'ArrowDown',
                40
            );

            await sleep(120);

            pressKey(
                input,
                'Enter',
                13
            );

            await sleep(350);

            if (
                normalizeLookup(
                    input.value
                ) === targetName
            ) {
                await closeLookupPopup(
                    doc,
                    input,
                    task
                );

                return task.name;
            }

            result =
                findLookupResult(
                    doc,
                    input,
                    task
                );
        }

        if (!result) {
            throw new Error(
                '列表中未找到' +
                task.code +
                ' ' +
                task.name
            );
        }

        /*
         * 方法一：点击名称单元格。
         */
        realClick(
            result.target
        );

        await sleep(300);

        if (
            normalizeLookup(
                input.value
            ) === targetName
        ) {
            await closeLookupPopup(
                doc,
                input,
                task
            );

            return task.name;
        }

        /*
         * 方法二：点击整行。
         */
        result =
            findLookupResult(
                doc,
                input,
                task
            );

        if (result) {
            realClick(
                result.row
            );

            await sleep(300);
        }

        if (
            normalizeLookup(
                input.value
            ) === targetName
        ) {
            await closeLookupPopup(
                doc,
                input,
                task
            );

            return task.name;
        }

        /*
         * 方法三：双击名称。
         */
        result =
            findLookupResult(
                doc,
                input,
                task
            );

        if (result) {
            realDoubleClick(
                result.target
            );

            await sleep(280);
        }

        if (
            normalizeLookup(
                input.value
            ) === targetName
        ) {
            await closeLookupPopup(
                doc,
                input,
                task
            );

            return task.name;
        }

        /*
         * 方法四：键盘向下并回车。
         */
        input.focus();

        pressKey(
            input,
            'ArrowDown',
            40
        );

        await sleep(100);

        pressKey(
            input,
            'Enter',
            13
        );

        await sleep(350);

        const win =
            doc.defaultView;

        if (win.jQuery) {
            win.jQuery(input)
                .trigger('change')
                .trigger('blur');
        }

        input.dispatchEvent(
            new win.Event(
                'change',
                {
                    bubbles: true
                }
            )
        );

        input.blur();

        await sleep(180);

        /*
         * 最终只检查字段文字是否正确。
         */
        if (
            normalizeLookup(
                input.value
            ) !== targetName
        ) {
            throw new Error(
                '已找到结果，但未完成选中，当前值：' +
                input.value
            );
        }

        await closeLookupPopup(
            doc,
            input,
            task
        );

        return task.name;
    }

    /******************************************************************
     * 出院时间和实际住院天数
     ******************************************************************/

    function pad2(value) {
        return String(value)
            .padStart(2, '0');
    }

    /*
     * 使用运行脚本的电脑系统日期。
     */
    function formatTodayAt0930() {
        const now =
            new Date();

        return (
            now.getFullYear() +
            '-' +
            pad2(
                now.getMonth() + 1
            ) +
            '-' +
            pad2(
                now.getDate()
            ) +
            ' ' +
            USER_CONFIG.dischargeTime
        );
    }

    function parseDateTime(text) {
        const match =
            String(text || '')
                .match(
                    /(\d{4})-(\d{1,2})-(\d{1,2})(?:\s+(\d{1,2}):(\d{1,2}):(\d{1,2}))?/
                );

        if (!match) {
            return null;
        }

        return new Date(
            Number(match[1]),
            Number(match[2]) - 1,
            Number(match[3]),
            Number(match[4] || 0),
            Number(match[5] || 0),
            Number(match[6] || 0)
        );
    }

    /*
     * 按自然日期计算住院日差。
     * 例如7月15日至7月23日，结果为8天。
     */
    function calendarDayDifference(
        start,
        end
    ) {
        const startUtc =
            Date.UTC(
                start.getFullYear(),
                start.getMonth(),
                start.getDate()
            );

        const endUtc =
            Date.UTC(
                end.getFullYear(),
                end.getMonth(),
                end.getDate()
            );

        return Math.round(
            (
                endUtc -
                startUtc
            ) /
            86400000
        );
    }

    function findInputByAnyLabel(
        labels
    ) {
        for (
            const label of labels
        ) {
            const result =
                findInputByLabel(
                    label
                );

            if (result) {
                return result;
            }
        }

        return null;
    }

    function findVisibleDatePopup(
        doc,
        input
    ) {
        const inputRect =
            input.getBoundingClientRect();

        const selectors = [
            '.layui-laydate',
            '.laydate_box',
            '.laydate-box',
            '.datetimepicker',
            '.datepicker',
            '.ui-datepicker',
            'div'
        ].join(',');

        const candidates =
            Array.from(
                doc.querySelectorAll(
                    selectors
                )
            )
                .filter(
                    function (element) {
                        if (
                            !isVisible(element)
                        ) {
                            return false;
                        }

                        const text =
                            normalize(
                                element.innerText ||
                                element.textContent
                            );

                        const rect =
                            element
                                .getBoundingClientRect();

                        return (
                            rect.width >= 180 &&
                            rect.height >= 150 &&
                            (
                                text.includes(
                                    '清空今天确定'
                                ) ||
                                (
                                    text.includes(
                                        '今天'
                                    ) &&
                                    text.includes(
                                        '确定'
                                    )
                                )
                            )
                        );
                    }
                )
                .map(
                    function (element) {
                        const rect =
                            element
                                .getBoundingClientRect();

                        return {
                            element: element,
                            score:
                                Math.abs(
                                    rect.left -
                                    inputRect.left
                                ) +
                                Math.abs(
                                    rect.top -
                                    inputRect.bottom
                                ),
                            area:
                                rect.width *
                                rect.height
                        };
                    }
                );

        if (!candidates.length) {
            return null;
        }

        candidates.sort(
            function (a, b) {
                if (
                    a.score !== b.score
                ) {
                    return (
                        a.score -
                        b.score
                    );
                }

                return (
                    a.area -
                    b.area
                );
            }
        );

        return candidates[0]
            .element;
    }

    async function closeDatePicker(
        doc,
        input
    ) {
        const popup =
            findVisibleDatePopup(
                doc,
                input
            );

        if (!popup) {
            input.blur();
            return;
        }

        const confirmCandidates =
            Array.from(
                popup.querySelectorAll(
                    'button,a,span,div'
                )
            )
                .filter(
                    function (element) {
                        return (
                            isVisible(element) &&
                            normalize(
                                element.innerText ||
                                element.textContent
                            ) === '确定'
                        );
                    }
                )
                .sort(
                    function (a, b) {
                        const rectA =
                            a.getBoundingClientRect();

                        const rectB =
                            b.getBoundingClientRect();

                        return (
                            rectA.width *
                                rectA.height -
                            rectB.width *
                                rectB.height
                        );
                    }
                );

        if (
            confirmCandidates.length
        ) {
            realClick(
                confirmCandidates[0]
            );

            await sleep(250);
        }

        /*
         * 点击确定后仍未关闭时，
         * 使用Esc和失焦。
         */
        if (
            findVisibleDatePopup(
                doc,
                input
            )
        ) {
            input.focus();

            pressKey(
                input,
                'Escape',
                27
            );

            input.blur();

            await sleep(150);
        }

        /*
         * 日期值已正确时，
         * 若弹窗仍然存在则直接隐藏。
         */
        const remaining =
            findVisibleDatePopup(
                doc,
                input
            );

        if (remaining) {
            remaining.style.setProperty(
                'display',
                'none',
                'important'
            );

            remaining.style.setProperty(
                'visibility',
                'hidden',
                'important'
            );
        }
    }

    async function fillDischargeAndStayDays() {
        const admission =
            findInputByAnyLabel([
                '入院时间'
            ]);

        const discharge =
            findInputByAnyLabel([
                '出院时间'
            ]);

        const stayDays =
            findInputByAnyLabel([
                '实际住院',
                '实际住院天数'
            ]);

        if (!admission) {
            throw new Error(
                '未找到入院时间输入框'
            );
        }

        if (!discharge) {
            throw new Error(
                '未找到出院时间输入框'
            );
        }

        if (!stayDays) {
            throw new Error(
                '未找到实际住院天数输入框'
            );
        }

        const admissionDate =
            parseDateTime(
                admission.input.value
            );

        if (!admissionDate) {
            throw new Error(
                '入院时间格式无法识别：' +
                admission.input.value
            );
        }

        const dischargeText =
            formatTodayAt0930();

        const dischargeDate =
            parseDateTime(
                dischargeText
            );

        const difference =
            calendarDayDifference(
                admissionDate,
                dischargeDate
            );

        if (difference < 0) {
            throw new Error(
                '系统当天早于入院日期'
            );
        }

        /*
         * 同一天入院和出院时按1天填写。
         */
        const actualDays =
            Math.max(
                1,
                difference
            );

        /*
         * 不主动focus出院时间输入框，
         * 避免日期弹窗自动展开。
         */
        setInputValueWithoutFocus(
            discharge.doc,
            discharge.input,
            dischargeText
        );

        await sleep(150);

        await closeDatePicker(
            discharge.doc,
            discharge.input
        );

        /*
         * 关闭日期组件后再次写入，
         * 防止组件还原时间或删除秒数。
         */
        setInputValueWithoutFocus(
            discharge.doc,
            discharge.input,
            dischargeText
        );

        discharge.input.blur();

        await sleep(100);

        setInputValue(
            stayDays.doc,
            stayDays.input,
            String(actualDays)
        );

        if (
            normalize(
                discharge.input.value
            ) !==
            normalize(
                dischargeText
            )
        ) {
            throw new Error(
                '出院时间写入后被页面修改，当前值：' +
                discharge.input.value
            );
        }

        return {
            dischargeText:
                dischargeText,
            actualDays:
                actualDays
        };
    }

    /*
     * 仅根据页面“当前已有”的入院时间、出院时间重新计算实际住院天数。
     * 不修改出院时间，不依赖系统当天日期，也不会自动保存病案首页。
     */
    function correctStayDaysFromCurrentDischarge() {
        const admission =
            findInputByAnyLabel([
                '入院时间'
            ]);

        const discharge =
            findInputByAnyLabel([
                '出院时间'
            ]);

        const stayDays =
            findInputByAnyLabel([
                '实际住院',
                '实际住院天数'
            ]);

        if (!admission) {
            throw new Error(
                '未找到入院时间输入框'
            );
        }

        if (!discharge) {
            throw new Error(
                '未找到出院时间输入框'
            );
        }

        if (!stayDays) {
            throw new Error(
                '未找到实际住院天数输入框'
            );
        }

        const admissionText =
            String(
                admission.input.value ||
                ''
            ).trim();

        const dischargeText =
            String(
                discharge.input.value ||
                ''
            ).trim();

        const admissionDate =
            parseDateTime(
                admissionText
            );

        if (!admissionDate) {
            throw new Error(
                '入院时间格式无法识别：' +
                admissionText
            );
        }

        const dischargeDate =
            parseDateTime(
                dischargeText
            );

        if (!dischargeDate) {
            throw new Error(
                '出院时间为空或格式无法识别：' +
                dischargeText
            );
        }

        const difference =
            calendarDayDifference(
                admissionDate,
                dischargeDate
            );

        if (difference < 0) {
            throw new Error(
                '当前出院日期早于入院日期，无法矫正住院天数'
            );
        }

        /*
         * 与原自动填写逻辑保持一致：
         * 同一天入院和出院时按1天填写；其余按自然日期差填写。
         */
        const actualDays =
            Math.max(
                1,
                difference
            );

        setInputValue(
            stayDays.doc,
            stayDays.input,
            String(actualDays)
        );

        const finalValue =
            String(
                stayDays.input.value ||
                ''
            ).trim();

        if (
            finalValue !==
            String(actualDays)
        ) {
            throw new Error(
                '实际住院天数写入后被页面修改，当前值：' +
                finalValue
            );
        }

        return {
            admissionText:
                admissionText,
            dischargeText:
                dischargeText,
            actualDays:
                actualDays
        };
    }

    /******************************************************************
     * 右下角状态提示
     ******************************************************************/

    function showStatus(
        message,
        type
    ) {
        const messageType =
            type ||
            'normal';

        let box =
            document.getElementById(
                'medical-auto-fill-status'
            );

        if (!box) {
            box =
                document.createElement(
                    'div'
                );

            box.id =
                'medical-auto-fill-status';

            document.body.appendChild(
                box
            );
        }

        const colors = {
            normal: '#159bd3',
            success: '#20985b',
            error: '#dc4c40'
        };

        Object.assign(
            box.style,
            {
                position: 'fixed',
                right: '20px',
                bottom: '126px',
                zIndex: '2147483647',
                minWidth: '300px',
                maxWidth: '650px',
                padding: '12px 15px',
                borderRadius: '6px',
                background:
                    colors[messageType] ||
                    colors.normal,
                color: '#ffffff',
                fontSize: '13px',
                lineHeight: '1.7',
                whiteSpace: 'pre-line',
                boxShadow:
                    '0 4px 15px rgba(0,0,0,.28)'
            }
        );

        box.textContent =
            message;

        clearTimeout(
            box.hideTimer
        );

        box.hideTimer =
            setTimeout(
                function () {
                    box.remove();
                },
                messageType === 'error'
                    ? 15000
                    : 6500
            );
    }

    /******************************************************************
     * 前端默认值设置
     ******************************************************************/

    function escapeHtml(
        value
    ) {
        return String(value || '')
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;')
            .replace(/'/g, '&#39;');
    }

    function yesNoOptions(
        current
    ) {
        return (
            '<option value="是"' +
                (
                    current === '是'
                        ? ' selected'
                        : ''
                ) +
            '>是</option>' +
            '<option value="否"' +
                (
                    current === '否'
                        ? ' selected'
                        : ''
                ) +
            '>否</option>'
        );
    }

    function clinicalPathOptions(
        current
    ) {
        return (
            '<option value="中医"' +
                (
                    current === '中医'
                        ? ' selected'
                        : ''
                ) +
            '>中医</option>' +
            '<option value="西医"' +
                (
                    current === '西医'
                        ? ' selected'
                        : ''
                ) +
            '>西医</option>' +
            '<option value="否"' +
                (
                    current === '否'
                        ? ' selected'
                        : ''
                ) +
            '>否</option>'
        );
    }

