    function qcCloneConfigValue(value) {
        return JSON.parse(JSON.stringify(value));
    }

    function qcReadConfigStorage(storageKey) {
        try {
            if (typeof GM_getValue === 'function') {
                const gmValue = GM_getValue(storageKey, null);
                if (gmValue !== null && gmValue !== undefined) {
                    return typeof gmValue === 'string'
                        ? JSON.parse(gmValue)
                        : gmValue;
                }
            }
        } catch (error) {
            // 继续尝试同源localStorage。
        }
        try {
            const raw = localStorage.getItem(storageKey);
            return raw ? JSON.parse(raw) : null;
        } catch (error) {
            return null;
        }
    }

    function qcWriteConfigStorage(storageKey, value) {
        let saved = false;
        try {
            if (typeof GM_setValue === 'function') {
                GM_setValue(storageKey, qcCloneConfigValue(value));
                saved = true;
            }
        } catch (error) {
            // 继续尝试同源localStorage。
        }
        if (!saved) {
            localStorage.setItem(storageKey, JSON.stringify(value));
        }
    }

    function qcDefaultRuleConfig() {
        const rules = {};
        QUALITY_CONTROL_RULE_DEFINITIONS.forEach(function (definition) {
            const params = {};
            definition.params.forEach(function (parameter) {
                params[parameter.key] = parameter.defaultValue;
            });
            rules[definition.id] = {
                enabled: true,
                severity: definition.severity || 'default',
                effectiveDate: '',
                params: params
            };
        });
        return {
            schemaVersion: QUALITY_CONTROL_CONFIG_SCHEMA_VERSION,
            defaultVersion: QUALITY_CONTROL_DEFAULT_CONFIG_VERSION,
            customized: false,
            updatedAt: '',
            additionalPolicyText: '',
            rules: rules
        };
    }

    function qcDefaultAiPromptConfig() {
        return {
            schemaVersion: QUALITY_CONTROL_CONFIG_SCHEMA_VERSION,
            defaultVersion: QUALITY_CONTROL_DEFAULT_CONFIG_VERSION,
            customized: false,
            updatedAt: '',
            prompt: QUALITY_CONTROL_DEFAULT_AI_PROMPT
        };
    }

    function qcDefaultRepairPromptConfig() {
        const prompts = {};
        QUALITY_CONTROL_REPAIR_DEFINITIONS.forEach(
            function (definition) {
                prompts[definition.type] = definition.defaultPrompt;
            }
        );
        return {
            schemaVersion:
                QUALITY_CONTROL_REPAIR_PROMPT_SCHEMA_VERSION,
            defaultVersion:
                QUALITY_CONTROL_REPAIR_PROMPT_DEFAULT_VERSION,
            customized: false,
            updatedAt: '',
            prompts: prompts
        };
    }

    function qcNormalizeRuleConfig(value) {
        const defaults = qcDefaultRuleConfig();
        const raw = value && typeof value === 'object' ? value : null;
        if (!raw) return defaults;
        if (
            raw.customized === false &&
            Number(raw.defaultVersion || 0) <
                QUALITY_CONTROL_DEFAULT_CONFIG_VERSION
        ) {
            return defaults;
        }
        const normalized = qcCloneConfigValue(defaults);
        normalized.customized = raw.customized === undefined
            ? true
            : Boolean(raw.customized);
        normalized.updatedAt = String(raw.updatedAt || '');
        normalized.additionalPolicyText = String(
            raw.additionalPolicyText || ''
        ).slice(0, 12000);
        QUALITY_CONTROL_RULE_DEFINITIONS.forEach(function (definition) {
            const rawRule = raw.rules && raw.rules[definition.id];
            if (!rawRule || typeof rawRule !== 'object') return;
            const rule = normalized.rules[definition.id];
            rule.enabled = rawRule.enabled !== false;
            rule.severity = [
                'default', 'error', 'warn', 'info'
            ].includes(rawRule.severity)
                ? rawRule.severity
                : 'default';
            const effectiveDate = String(
                rawRule.effectiveDate || ''
            ).trim();
            rule.effectiveDate = /^\d{4}-\d{2}-\d{2}$/.test(
                effectiveDate
            ) ? effectiveDate : '';
            definition.params.forEach(function (parameter) {
                const rawNumber = Number(
                    rawRule.params && rawRule.params[parameter.key]
                );
                if (!Number.isFinite(rawNumber)) return;
                rule.params[parameter.key] = Math.min(
                    parameter.max,
                    Math.max(parameter.min, rawNumber)
                );
            });
        });
        return normalized;
    }

    function qcNormalizeAiPromptConfig(value) {
        const defaults = qcDefaultAiPromptConfig();
        const raw = value && typeof value === 'object' ? value : null;
        if (!raw) return defaults;
        if (
            raw.customized === false &&
            Number(raw.defaultVersion || 0) <
                QUALITY_CONTROL_DEFAULT_CONFIG_VERSION
        ) {
            return defaults;
        }
        const prompt = String(raw.prompt || '').trim();
        return {
            schemaVersion: QUALITY_CONTROL_CONFIG_SCHEMA_VERSION,
            defaultVersion: QUALITY_CONTROL_DEFAULT_CONFIG_VERSION,
            customized: raw.customized === undefined
                ? true
                : Boolean(raw.customized),
            updatedAt: String(raw.updatedAt || ''),
            prompt: prompt
                ? prompt.slice(0, 20000)
                : QUALITY_CONTROL_DEFAULT_AI_PROMPT
        };
    }

    function qcNormalizeRepairPromptConfig(value) {
        const defaults = qcDefaultRepairPromptConfig();
        const raw = value && typeof value === 'object'
            ? value
            : null;
        if (!raw) return defaults;
        if (
            raw.customized === false &&
            Number(raw.defaultVersion || 0) <
                QUALITY_CONTROL_REPAIR_PROMPT_DEFAULT_VERSION
        ) {
            return defaults;
        }
        const normalized = qcCloneConfigValue(defaults);
        normalized.customized = raw.customized === undefined
            ? true
            : Boolean(raw.customized);
        normalized.updatedAt = String(raw.updatedAt || '');
        QUALITY_CONTROL_REPAIR_DEFINITIONS.forEach(
            function (definition) {
                const prompt = String(
                    raw.prompts && raw.prompts[definition.type] || ''
                ).trim();
                if (prompt) {
                    normalized.prompts[definition.type] =
                        prompt.slice(0, 20000);
                }
            }
        );
        return normalized;
    }

    function qcLoadRuleConfig() {
        const raw = qcReadConfigStorage(
            QUALITY_CONTROL_RULE_CONFIG_STORAGE_KEY
        );
        const normalized = qcNormalizeRuleConfig(raw);
        if (raw) {
            qcWriteConfigStorage(
                QUALITY_CONTROL_RULE_CONFIG_STORAGE_KEY,
                normalized
            );
        }
        return normalized;
    }

    function qcLoadAiPromptConfig() {
        const raw = qcReadConfigStorage(
            QUALITY_CONTROL_AI_PROMPT_STORAGE_KEY
        );
        const normalized = qcNormalizeAiPromptConfig(raw);
        if (raw) {
            qcWriteConfigStorage(
                QUALITY_CONTROL_AI_PROMPT_STORAGE_KEY,
                normalized
            );
        }
        return normalized;
    }

    function qcLoadRepairPromptConfig() {
        const raw = qcReadConfigStorage(
            QUALITY_CONTROL_REPAIR_PROMPT_STORAGE_KEY
        );
        const normalized = qcNormalizeRepairPromptConfig(raw);
        if (raw) {
            qcWriteConfigStorage(
                QUALITY_CONTROL_REPAIR_PROMPT_STORAGE_KEY,
                normalized
            );
        }
        return normalized;
    }

    function qcSaveRuleConfig(config, customized) {
        const normalized = qcNormalizeRuleConfig(config);
        normalized.customized = customized !== false;
        normalized.updatedAt = new Date().toLocaleString();
        qcWriteConfigStorage(
            QUALITY_CONTROL_RULE_CONFIG_STORAGE_KEY,
            normalized
        );
        return normalized;
    }

    function qcSaveAiPromptConfig(config, customized) {
        const normalized = qcNormalizeAiPromptConfig(config);
        normalized.customized = customized !== false;
        normalized.updatedAt = new Date().toLocaleString();
        qcWriteConfigStorage(
            QUALITY_CONTROL_AI_PROMPT_STORAGE_KEY,
            normalized
        );
        return normalized;
    }

    function qcSaveRepairPromptConfig(config, customized) {
        const normalized = qcNormalizeRepairPromptConfig(config);
        normalized.customized = customized !== false;
        normalized.updatedAt = new Date().toLocaleString();
        qcWriteConfigStorage(
            QUALITY_CONTROL_REPAIR_PROMPT_STORAGE_KEY,
            normalized
        );
        return normalized;
    }

    function qcRuleDefinition(ruleId) {
        return QUALITY_CONTROL_RULE_DEFINITIONS.find(
            function (definition) {
                return definition.id === ruleId;
            }
        ) || null;
    }

    function qcRuleEnabled(config, ruleId) {
        const rule = config && config.rules
            ? config.rules[ruleId]
            : null;
        if (!rule || rule.enabled === false) return false;
        if (!rule.effectiveDate) return true;
        const now = new Date();
        const today =
            now.getFullYear() + '-' +
            pad2(now.getMonth() + 1) + '-' +
            pad2(now.getDate());
        return rule.effectiveDate <= today;
    }

    function qcRuleNumber(config, ruleId, key, fallback) {
        const value = Number(
            config && config.rules &&
            config.rules[ruleId] &&
            config.rules[ruleId].params &&
            config.rules[ruleId].params[key]
        );
        return Number.isFinite(value) ? value : fallback;
    }

    function qcAiRuleSummary(config) {
        const ruleConfig = config || qcDefaultRuleConfig();
        return {
            enabledRules: QUALITY_CONTROL_RULE_DEFINITIONS
                .filter(function (definition) {
                    return qcRuleEnabled(ruleConfig, definition.id);
                })
                .map(function (definition) {
                    const rule = ruleConfig.rules[definition.id];
                    return {
                        id: definition.id,
                        name: definition.name,
                        scope: definition.scope,
                        requirement: definition.requirement,
                        severity: rule.severity,
                        effectiveDate: rule.effectiveDate || '',
                        params: rule.params
                    };
                }),
            additionalPolicyText: String(
                ruleConfig.additionalPolicyText || ''
            ).trim()
        };
    }

    function qcNormalize(value) {
        return String(value || '').replace(/\s+/g, '').toLowerCase();
    }

    function qcCleanName(value) {
        return String(value || '')
            .replace(/^(?:患者姓名|病人姓名|姓名)\s*[：:]?\s*/, '')
            .replace(/[^\u3400-\u9fff·]/g, '')
            .slice(0, 10);
    }

    function qcCleanBedNumber(value) {
        const compact = String(value || '')
            .replace(/^(?:床号|病床)\s*[：:]?\s*/, '')
            .replace(/[-‐‑‒–—―－﹣]/g, '-')
            .replace(/\s+/g, '')
            .replace(/床(?:位)?$/, '');
        const match = compact.match(
            /^([A-Za-z0-9]{1,8}(?:-[A-Za-z0-9]{1,8}){0,3})$/
        );
        return match ? match[1] : '';
    }

    function qcPreferBedNumber(primaryValue, secondaryValue) {
        const primary = qcCleanBedNumber(primaryValue);
        const secondary = qcCleanBedNumber(secondaryValue);
        if (!primary) return secondary;
        if (!secondary) return primary;
        const primaryScore = primary.split('-').length * 100 + primary.length;
        const secondaryScore = secondary.split('-').length * 100 + secondary.length;
        return secondaryScore > primaryScore ? secondary : primary;
    }

    function qcIdentityKey(identity) {
        const item = identity || {};
        const inpatientNo = qcNormalize(item.inpatientNo);
        const name = qcNormalize(item.name);
        const bed = qcNormalize(item.bed);
        if (inpatientNo) return 'no:' + inpatientNo;
        if (name && bed) return 'namebed:' + name + ':' + bed;
        if (name) return 'name:' + name;
        return '';
    }

    function qcIdentityMatches(first, second) {
        const a = first || {};
        const b = second || {};
        const aNo = qcNormalize(a.inpatientNo);
        const bNo = qcNormalize(b.inpatientNo);
        const aName = qcNormalize(a.name);
        const bName = qcNormalize(b.name);
        const aBed = qcNormalize(a.bed);
        const bBed = qcNormalize(b.bed);
        if (aNo && bNo) return aNo === bNo;
        if (!aName || !bName || aName !== bName) return false;
        return !(aBed && bBed && aBed !== bBed);
    }

    function qcIdentityLabel(identity) {
        const item = identity || {};
        return [
            item.name || '',
            item.inpatientNo ? '住院号' + item.inpatientNo : '',
            item.bed ? item.bed + '床' : ''
        ].filter(Boolean).join(' / ') || '未识别患者';
    }

    function qcLoadJson(storageKey, fallback) {
        try {
            const raw = localStorage.getItem(storageKey);
            if (!raw) return fallback;
            const parsed = JSON.parse(raw);
            return parsed === null || parsed === undefined
                ? fallback
                : parsed;
        } catch (error) {
            return fallback;
        }
    }

    function qcExtractIdentityFromText(textValue) {
        const text = String(textValue || '').replace(/\r/g, '\n');
        const identity = {
            name: '',
            inpatientNo: '',
            bed: '',
            sex: '',
            age: ''
        };
        const namePatterns = [
            /(?:患者姓名|病人姓名|姓名)\s*[：:]\s*([\u3400-\u9fff·]{2,10})/,
            /患者信息\s*[：:]?\s*([\u3400-\u9fff·]{2,10})\s*\/\s*[男女]/,
            /([\u3400-\u9fff·]{2,10})\s*\/\s*[男女]\s*\/\s*\d{1,3}\s*岁/
        ];
        const noPatterns = [
            /住院号\s*[：:]\s*([A-Za-z0-9-]{4,24})/i,
            /患者信息\s*[：:][^\n]{0,180}\/\s*([0-9]{5,10})(?:\s*\/|\s|$)/,
            /\b([0-9]{5,8})-[0-9A-Za-z-]{3,20}\b/
        ];
        for (const pattern of namePatterns) {
            const match = text.match(pattern);
            if (match && match[1]) {
                identity.name = qcCleanName(match[1]);
                break;
            }
        }
        for (const pattern of noPatterns) {
            const match = text.match(pattern);
            if (match && match[1]) {
                identity.inpatientNo = String(match[1]).trim();
                break;
            }
        }
        const bedMatch =
            text.match(/(?:床号|病床)\s*[：:]?\s*([A-Za-z0-9]{1,8}(?:\s*[-‐‑‒–—―－﹣]\s*[A-Za-z0-9]{1,8}){0,3})(?=\s*(?:床(?:位)?)?(?:\s|[，,、；;]|住院号|性别|年龄|科别|科室|病区|姓名|$))/i) ||
            text.match(/(?:^|[\s/])([A-Za-z0-9]{1,8}(?:\s*[-‐‑‒–—―－﹣]\s*[A-Za-z0-9]{1,8}){0,3})\s*床(?:位)?(?=\s|[，,、；;/]|$)/im);
        if (bedMatch && bedMatch[1]) {
            identity.bed = qcCleanBedNumber(bedMatch[1]);
        }
        const sexMatch = text.match(/(?:性别\s*[：:]?\s*|\/\s*)(男|女)(?:\s*\/|$)/);
        if (sexMatch && sexMatch[1]) identity.sex = sexMatch[1];
        const ageMatch = text.match(/([0-9]{1,3})\s*岁/);
        if (ageMatch && ageMatch[1]) identity.age = ageMatch[1];
        return identity;
    }

    function qcDocumentIsVisible(doc) {
        if (!doc) return false;
        if (doc === document) return true;
        try {
            return Boolean(
                doc.defaultView &&
                doc.defaultView.frameElement &&
                isVisible(doc.defaultView.frameElement)
            );
        } catch (error) {
            return false;
        }
    }

    function qcVisibleDocumentText(doc, maximumLength) {
        if (!doc || !doc.body) return '';

        const excludedSelectors = [
            '#' + QUALITY_CONTROL_MODAL_ID,
            '#medical-patient-round-book-modal',
            '#medical-patient-exam-application-modal',
            '#medical-patient-exam-calibration-modal',
            '#' + PATIENT_PANEL_ID,
            '#medical-auto-fill-modal',
            '#medical-auto-fill-settings-modal',
            '#medical-auto-fill-status',
            '#medical-inpatient-auto-fill-panel',
            '#medical-inpatient-progress-ai-modal',
            '#medical-inpatient-first-course-ai-modal',
            '#medical-inpatient-discharge-record-ai-modal',
            '#medical-inpatient-condition-disclosure-ai-modal',
            '#medical-inpatient-admission-record-ai-modal'
        ];
        let excluded = [];

        try {
            excluded = Array.from(
                doc.querySelectorAll(
                    excludedSelectors.join(',')
                )
            );
        } catch (error) {
            excluded = [];
        }

        const displayStates = excluded.map(function (element) {
            return {
                element: element,
                value: element.style.getPropertyValue('display'),
                priority: element.style.getPropertyPriority('display')
            };
        });

        try {
            excluded.forEach(function (element) {
                element.style.setProperty(
                    'display',
                    'none',
                    'important'
                );
            });

            return String(doc.body.innerText || '')
                .slice(0, maximumLength || 120000);
        } catch (error) {
            return '';
        } finally {
            displayStates.forEach(function (state) {
                if (state.value) {
                    state.element.style.setProperty(
                        'display',
                        state.value,
                        state.priority
                    );
                } else {
                    state.element.style.removeProperty(
                        'display'
                    );
                }
            });
        }
    }

    function qcExtractCurrentIdentity() {
        const candidates = [];
        getAllDocuments().filter(qcDocumentIsVisible)
            .forEach(function (doc, docIndex) {
                let elements = [];
                try {
                    elements = Array.from(doc.querySelectorAll(
                        'span,div,a,p,label,strong,b,td'
                    ));
                } catch (error) {
                    elements = [];
                }
                elements.forEach(function (element) {
                    if (
                        element.closest('#' + QUALITY_CONTROL_MODAL_ID) ||
                        element.closest('#medical-patient-round-book-modal') ||
                        element.closest('#medical-patient-exam-application-modal') ||
                        element.closest('#medical-patient-exam-calibration-modal') ||
                        element.closest('#' + PATIENT_PANEL_ID)
                    ) return;
                    try {
                        if (!isVisible(element)) return;
                    } catch (error) {
                        return;
                    }
                    const text = String(
                        element.innerText || element.textContent || ''
                    ).trim();
                    if (
                        text.length < 8 ||
                        text.length > 220 ||
                        !(
                            /患者信息|住院号|患者姓名|病人姓名|姓名/.test(text) ||
                            /[\u3400-\u9fff·]{2,10}\s*\/\s*[男女]\s*\/\s*\d{1,3}\s*岁/.test(text)
                        )
                    ) return;
                    const identity = qcExtractIdentityFromText(text);
                    if (!identity.name && !identity.inpatientNo) return;
                    candidates.push({
                        identity: identity,
                        source: '当前可见患者栏',
                        score:
                            (identity.inpatientNo ? 300 : 0) +
                            (identity.name ? 160 : 0) +
                            (/患者信息/.test(text) ? 150 : 0) -
                            docIndex * 2
                    });
                });
                const pageText =
                    qcVisibleDocumentText(
                        doc,
                        60000
                    );
                if (pageText) {
                    const identity = qcExtractIdentityFromText(pageText);
                    if (identity.name || identity.inpatientNo) {
                        candidates.push({
                            identity: identity,
                            source: '当前可见页面',
                            score:
                                (identity.inpatientNo ? 160 : 0) +
                                (identity.name ? 80 : 0) -
                                docIndex * 2
                        });
                    }
                }
            });
        candidates.sort(function (a, b) {
            return b.score - a.score;
        });
        if (candidates.length) return candidates[0];

        const saved = qcLoadJson(
            QUALITY_CONTROL_TARGET_STORAGE_KEY,
            null
        );
        if (saved && (saved.name || saved.inpatientNo)) {
            return {
                identity: saved,
                source: '上次质控目标（请核对）',
                score: 20
            };
        }
        return {
            identity: { name: '', inpatientNo: '', bed: '', sex: '', age: '' },
            source: '未识别',
            score: 0
        };
    }

    function qcFindPatientCache(storageKey, identity) {
        const stored = qcLoadJson(storageKey, {});
        if (!stored || typeof stored !== 'object') return null;
        if (
            stored.identity &&
            qcIdentityMatches(stored.identity, identity)
        ) return stored;
        const directKey = qcIdentityKey(identity);
        if (directKey && stored[directKey]) return stored[directKey];
        const entries = Array.isArray(stored)
            ? stored
            : Object.keys(stored).map(function (key) {
                return stored[key];
            });
        return entries.find(function (entry) {
            return Boolean(
                entry &&
                typeof entry === 'object' &&
                entry.identity &&
                qcIdentityMatches(entry.identity, identity)
            );
        }) || null;
    }

    function qcEntryTexts(entry) {
        if (!entry || typeof entry !== 'object') return [];
        const values = [];
        [
            'text',
            'progressText',
            'dischargeRecordText',
            'orderText',
            'admissionRecordText',
            'resultText'
        ].forEach(function (key) {
            if (typeof entry[key] === 'string' && entry[key].trim()) {
                values.push(entry[key].trim());
            }
        });
        if (
            entry.source &&
            typeof entry.source.text === 'string' &&
            entry.source.text.trim()
        ) values.push(entry.source.text.trim());
        return Array.from(new Set(values));
    }

    function qcSourceDefinition(type) {
        return QUALITY_CONTROL_SOURCE_DEFINITIONS.find(
            function (definition) {
                return definition.type === type;
            }
        ) || null;
    }

    function qcSourceStore() {
        const stored =
            patientLargeCacheReadStore(
                QUALITY_CONTROL_SOURCE_STORAGE_KEY
            );

        return stored &&
            typeof stored === 'object' &&
            !Array.isArray(stored)
                ? stored
                : {};
    }

    function qcRequireSourceIdentity(identity) {
        const value = identity || {};
        if (!String(value.inpatientNo || '').trim()) {
            throw new Error(
                '为避免同名或再次住院串档，四类质控资料必须先填写住院号'
            );
        }
        return value;
    }

    function qcLoadSourceBundle(identity) {
        const key = qcIdentityKey(identity);
        const stored = key ? qcSourceStore()[key] : null;
        return Object.assign(
            {
                schemaVersion: 2,
                identity: Object.assign({}, identity || {}),
                sources: {},
                updatedAt: 0
            },
            stored && typeof stored === 'object'
                ? stored
                : {},
            {
                identity: Object.assign(
                    {},
                    stored && stored.identity || {},
                    identity || {}
                ),
                sources: Object.assign(
                    {},
                    stored && stored.sources || {}
                )
            }
        );
    }

    function qcSaveSourceBundle(identity, bundle) {
        qcRequireSourceIdentity(identity);
        const key = qcIdentityKey(identity);
        if (!key) {
            throw new Error('无法生成当前患者的质控资料键');
        }
        const store = qcSourceStore();
        const value = Object.assign({}, bundle || {}, {
            schemaVersion: 2,
            identity: Object.assign({}, identity),
            sources: Object.assign({}, bundle && bundle.sources || {}),
            updatedAt: Date.now()
        });
        store[key] = value;

        try {
            patientLargeCacheWriteStore(
                QUALITY_CONTROL_SOURCE_STORAGE_KEY,
                store
            );
        } catch (error) {
            throw new Error(
                '四类质控资料保存失败：' +
                String(
                    error &&
                    error.message ||
                    error
                )
            );
        }
        return value;
    }

    function qcSetPatientSource(identity, type, source, options) {
        const definition = qcSourceDefinition(type);
        if (!definition) throw new Error('未知质控资料类型');
        const skipIdentityCheck = Boolean(
            options && options.skipIdentityCheck
        );
        const bundle = qcLoadSourceBundle(
            qcRequireSourceIdentity(identity)
        );
        const text = String(source && source.text || '').trim();
        if (!text) throw new Error('资料内容不能为空');
        if (text.length > QUALITY_CONTROL_SOURCE_MAX_TEXT) {
            throw new Error(
                '单类质控资料超过60万字符，已停止保存以避免浏览器本地存储损坏；请缩小当前页范围或分段整理后再录入'
            );
        }
        const embeddedIdentity =
            qcExtractIdentityFromText(text);
        if (
            !skipIdentityCheck &&
            (embeddedIdentity.name ||
                embeddedIdentity.inpatientNo) &&
            !qcIdentityMatches(
                embeddedIdentity,
                identity
            )
        ) {
            throw new Error(
                '资料正文中识别到的患者与当前质控目标不一致，已阻止保存'
            );
        }
        if (
            !skipIdentityCheck &&
            source &&
            source.sourceIdentity &&
            (
                source.sourceIdentity.name ||
                source.sourceIdentity.inpatientNo
            ) &&
            !qcIdentityMatches(
                source.sourceIdentity,
                identity
            )
        ) {
            throw new Error(
                '资料来源患者与当前质控目标不一致，已阻止保存'
            );
        }
        const normalizedText = qcNormalize(text);
        const identityEvidence = skipIdentityCheck
            ? '人工解锁录入（患者一致性校验已关闭）'
            : (
                identity.inpatientNo &&
                normalizedText.includes(
                    qcNormalize(identity.inpatientNo)
                )
            )
                ? '正文含住院号'
                : (
                    embeddedIdentity.name &&
                    qcIdentityMatches(
                        embeddedIdentity,
                        identity
                    )
                )
                    ? (
                        embeddedIdentity.inpatientNo
                            ? '正文患者标识一致'
                            : '正文仅姓名一致'
                    )
                    : (
                        source &&
                        source.sourceIdentity &&
                        qcIdentityMatches(
                            source.sourceIdentity,
                            identity
                        )
                    )
                        ? (
                            source.sourceIdentity.inpatientNo
                                ? '资料来源住院号一致'
                                : '资料来源仅姓名一致（已人工确认）'
                        )
                        : '正文未识别患者标识';
        bundle.sources[type] = Object.assign({}, source, {
            type: type,
            label: definition.label,
            text: text,
            identity: Object.assign({}, identity),
            records: Array.isArray(source && source.records)
                ? source.records.slice(0, 500)
                : [],
            identityEvidence: identityEvidence,
            savedAt: new Date().toLocaleString()
        });
        return qcSaveSourceBundle(identity, bundle).sources[type];
    }

    function qcClearPatientSource(identity, type) {
        const bundle = qcLoadSourceBundle(
            qcRequireSourceIdentity(identity)
        );
        delete bundle.sources[type];
        qcSaveSourceBundle(identity, bundle);
    }

    function qcSourceOriginLabel(source) {
        if (!source) return '未提供';
        return String(
            source.originLabel ||
            (
                source.origin === 'current-page'
                    ? '当前页抓取'
                    : source.origin === 'inpatient-cache'
                        ? '住院缓存显式导入'
                        : '人工录入/编辑'
            )
        );
    }

    function qcSetSourceEditingMode(
        modal,
        editing,
        activeButton
    ) {
        if (!modal) return;
        modal.querySelectorAll(
            '.quality-source-actions button'
        ).forEach(function (button) {
            button.disabled =
                Boolean(editing && button !== activeButton);
        });
        [
            '.quality-patient-name',
            '.quality-patient-no',
            '.quality-detect-patient',
            '.quality-patient-lock-toggle',
            '.quality-scan',
            '.quality-ai-scan',
            '.quality-repair-run-all'
        ].forEach(function (selector) {
            const element = modal.querySelector(selector);
            if (element) element.disabled = Boolean(editing);
        });
        modal.querySelectorAll(
            '[data-qc-repair-action="run"]'
        ).forEach(function (button) {
            button.disabled = Boolean(editing);
        });
    }

    function qcRenderSourceCards(modal, identity) {
        if (!modal) return;
        const hasInpatientNo = Boolean(
            identity && String(identity.inpatientNo || '').trim()
        );
        const bundle = hasInpatientNo
            ? qcLoadSourceBundle(identity)
            : { sources: {} };
        QUALITY_CONTROL_SOURCE_DEFINITIONS.forEach(
            function (definition) {
                const card = modal.querySelector(
                    '.quality-source-card[data-source-type="' +
                        definition.type +
                    '"]'
                );
                if (!card) return;
                const source = bundle.sources[definition.type] || null;
                const status = card.querySelector('.quality-source-status');
                const textarea = card.querySelector('.quality-source-text');
                const editButton = card.querySelector(
                    '[data-qc-source-action="edit"]'
                );
                textarea.readOnly = true;
                textarea.classList.remove('editing');
                textarea.value = source ? source.text : '';
                editButton.textContent = '手工录入/编辑';
                editButton.dataset.editing = '0';
                if (!hasInpatientNo) {
                    status.textContent =
                        '请先填写住院号，再保存或读取本类独立资料。';
                    status.className =
                        'quality-status quality-source-status warn';
                    return;
                }
                if (!source) {
                    status.textContent =
                        '未提供；初筛和AI质控不会读取其他模块的同类历史缓存。';
                    status.className =
                        'quality-status quality-source-status warn';
                    return;
                }
                const recordText =
                    definition.type === 'order' &&
                    Array.isArray(source.records) &&
                    source.records.length
                        ? '；结构化医嘱' + source.records.length + '条'
                        : '';
                status.textContent =
                    qcSourceOriginLabel(source) +
                    '；' + source.text.length + '字符' +
                    recordText +
                    '；' +
                    (source.identityEvidence ||
                        '正文患者标识未核对') +
                    '；保存于' +
                    (source.savedAt || '时间未知') +
                    '。';
                status.className =
                    'quality-status quality-source-status ' +
                    (
                        source.identityEvidence ===
                            '正文未识别患者标识' ||
                        /仅姓名|人工解锁|一致性校验已关闭/.test(
                            source.identityEvidence || ''
                        )
                            ? 'warn'
                            : 'ok'
                    );
            }
        );
        qcSetSourceEditingMode(modal, false, null);
    }

    function qcMarkResultsStale(modal, message) {
        const summary = modal.querySelector('.quality-result-summary');
        if (summary) {
            summary.textContent =
                message || '资料已变更，请重新执行结构化初筛。';
            summary.className =
                'quality-status quality-result-summary warn';
        }
        const aiStatus = modal.querySelector('.quality-ai-status');
        if (aiStatus) {
            aiStatus.textContent =
                '资料已变更；如需AI复核，请重新点击“AI质控”。';
            aiStatus.className =
                'quality-status quality-ai-status warn';
        }
        const aiResults = modal.querySelector('.quality-ai-results');
        if (aiResults) aiResults.innerHTML = '';
        modal._qcAiPlainText = '';
        qcRepairMarkResultsStale(
            modal,
            '功能区一基线已变更；当前返修结果仅供对照，请重新执行对应版块。',
            false
        );
    }

    function qcPageTypeScore(definition, text) {
        const source = String(text || '');
        if (!definition || !definition.markers.test(source)) return 0;
        const counters = {
            admission: [
                /入院记录|入院病历/,
                /主\s*诉\s*[：:]/,
                /现\s*病\s*史\s*[：:]/,
                /既\s*往\s*史\s*[：:]/,
                /体格检查|专科检查/,
                /入院诊断|初步诊断/
            ],
            progress: [
                /首次病程记录/,
                /病程记录/,
                /医师查房记录|查房记录/,
                /病例特点|诊断依据|鉴别诊断|诊疗计划/,
                /20\d{2}[年\-\/.]\d{1,2}[月\-\/.]\d{1,2}/
            ],
            discharge: [
                /出院记录|出院小结/,
                /入院情况/,
                /诊疗经过|住院经过/,
                /出院诊断/,
                /出院医嘱/
            ],
            order: [
                /医嘱查询/,
                /长期医嘱/,
                /临时医嘱/,
                /医嘱名称|医嘱内容/,
                /开始时间|开嘱时间/,
                /停止时间|停嘱时间|结束时间/
            ]
        };
        return (counters[definition.type] || []).reduce(
            function (score, pattern) {
                return score + (pattern.test(source) ? 2 : 0);
            },
            definition.strongMarkers.test(source) ? 3 : 0
        );
    }

    function qcExtractVisibleOrderRecords(doc) {
        const records = [];
        if (!doc || !doc.querySelectorAll) return records;
        let tables = [];
        try {
            tables = Array.from(doc.querySelectorAll('table'));
        } catch (error) {
            tables = [];
        }
        tables.forEach(function (table) {
            let rows = [];
            try {
                rows = Array.from(table.querySelectorAll('tr'));
            } catch (error) {
                rows = [];
            }
            if (rows.length < 2) return;
            let headerIndex = -1;
            let indexes = null;
            rows.some(function (row, rowIndex) {
                const cells = Array.from(
                    row.querySelectorAll('th,td')
                ).map(function (cell) {
                    return String(
                        cell.innerText || cell.textContent || ''
                    ).replace(/\s+/g, ' ').trim();
                });
                const nameIndex = cells.findIndex(function (value) {
                    return /医嘱名称|医嘱内容|项目名称/.test(value);
                });
                if (nameIndex < 0) return false;
                headerIndex = rowIndex;
                indexes = {
                    name: nameIndex,
                    start: cells.findIndex(function (value) {
                        return /开始时间|开嘱时间|开始日期/.test(value);
                    }),
                    stop: cells.findIndex(function (value) {
                        return /停止时间|停嘱时间|结束时间|停止日期/.test(value);
                    }),
                    status: cells.findIndex(function (value) {
                        return /状态|医嘱状态/.test(value);
                    })
                };
                return true;
            });
            if (headerIndex < 0 || !indexes) return;
            rows.slice(headerIndex + 1).forEach(function (row) {
                const cells = Array.from(
                    row.querySelectorAll('th,td')
                ).map(function (cell) {
                    return String(
                        cell.innerText || cell.textContent || ''
                    ).replace(/\s+/g, ' ').trim();
                });
                const name = cells[indexes.name] || '';
                if (!name || /医嘱名称|医嘱内容/.test(name)) return;
                records.push({
                    name: name,
                    startTime:
                        indexes.start >= 0 ? cells[indexes.start] || '' : '',
                    stopTime:
                        indexes.stop >= 0 ? cells[indexes.stop] || '' : '',
                    status:
                        indexes.status >= 0 ? cells[indexes.status] || '' : ''
                });
            });
        });
        return records.slice(0, 500);
    }

    function qcCaptureCurrentPage(type, identity, options) {
        const definition = qcSourceDefinition(type);
        if (!definition) throw new Error('未知质控资料类型');
        const skipIdentityCheck = Boolean(
            options && options.skipIdentityCheck
        );
        qcRequireSourceIdentity(identity);
        const detected = qcExtractCurrentIdentity();
        if (
            !skipIdentityCheck &&
            (
                !/^当前/.test(String(detected.source || '')) ||
                (
                    !detected.identity ||
                    !detected.identity.inpatientNo ||
                    qcNormalize(detected.identity.inpatientNo) !==
                        qcNormalize(identity.inpatientNo)
                )
            )
        ) {
            throw new Error(
                '当前页面未识别到与目标完全一致的住院号，已阻止抓取。目标：' +
                qcIdentityLabel(identity) +
                '；当前页：' +
                qcIdentityLabel(detected.identity)
            );
        }

        const candidates = [];
        getAllDocuments().filter(qcDocumentIsVisible)
            .forEach(function (doc, docIndex) {
                const text = qcVisibleDocumentText(
                    doc,
                    QUALITY_CONTROL_SOURCE_MAX_TEXT
                ).trim();
                if (!text) return;
                const score = qcPageTypeScore(definition, text);
                if (!score) return;
                const embeddedIdentity = qcExtractIdentityFromText(text);
                if (
                    !skipIdentityCheck &&
                    (embeddedIdentity.name || embeddedIdentity.inpatientNo) &&
                    !qcIdentityMatches(embeddedIdentity, identity)
                ) return;
                const normalized = qcNormalize(text);
                const containsNo = normalized.includes(
                    qcNormalize(identity.inpatientNo)
                );
                const containsName = identity.name
                    ? normalized.includes(qcNormalize(identity.name))
                    : false;
                candidates.push({
                    doc: doc,
                    text: text,
                    score:
                        score * 100 +
                        (containsNo ? 80 : containsName ? 30 : 0) -
                        docIndex,
                    containsIdentity: containsNo || containsName
                });
            });
        candidates.sort(function (first, second) {
            return second.score - first.score;
        });
        if (!candidates.length || candidates[0].score < 700) {
            throw new Error(
                '当前可见页面未识别到完整“' + definition.label +
                '”。请先打开对应正文/查询页并等待加载完成'
            );
        }
        const selected = candidates[0];
        if (
            selected.text.length >=
            QUALITY_CONTROL_SOURCE_MAX_TEXT
        ) {
            throw new Error(
                '当前页内容达到60万字符抓取上限，为避免保存不完整资料已停止；请缩小预览范围或改用手工分段整理'
            );
        }
        const selectedText =
            type === 'order'
                ? selected.text
                : medicalRecordPreprocessApplyGlobalSync(
                    selected.text
                ).text;

        return {
            text: selectedText,
            records:
                type === 'order'
                    ? qcExtractVisibleOrderRecords(selected.doc)
                    : [],
            origin: 'current-page',
            originLabel:
                '当前页抓取' +
                (
                    type !== 'order' &&
                    medicalRecordPreprocessLoadSettings()
                        .globalEnabled
                        ? '＋全局格式预处理'
                        : ''
                ) +
                (skipIdentityCheck
                    ? '（人工解锁，未校验患者一致性）'
                    : selected.containsIdentity
                    ? '（正文含患者标识）'
                    : '（当前患者栏已核对）'),
            sourceIdentity: Object.assign({}, detected.identity),
            pageUrl: location.href,
            pageTitle:
                String(
                    selected.doc && selected.doc.title ||
                    document.title ||
                    ''
                ),
            capturedAt: new Date().toLocaleString()
        };
    }

    function qcCacheIdentity(entry) {
        if (!entry || typeof entry !== 'object') return {};
        return Object.assign(
            {},
            entry.identity || entry.sourceIdentity || {},
            {
                name:
                    entry.identity && entry.identity.name ||
                    entry.sourceIdentity && entry.sourceIdentity.name ||
                    entry.patientName ||
                    '',
                inpatientNo:
                    entry.identity && entry.identity.inpatientNo ||
                    entry.sourceIdentity && entry.sourceIdentity.inpatientNo ||
                    entry.inpatientNo ||
                    ''
            }
        );
    }

    function qcImportCandidates(type, identity) {
        const definition = qcSourceDefinition(type);
        if (!definition) return [];
        return definition.cacheDefinitions.map(
            function (cacheDefinition) {
                const entry = qcFindPatientCache(
                    cacheDefinition[0],
                    identity
                );
                if (!entry) return null;
                const texts = qcEntryTexts(entry).sort(
                    function (first, second) {
                        return second.length - first.length;
                    }
                );
                if (!texts.length) return null;
                const sourceIdentity = qcCacheIdentity(entry);
                if (
                    sourceIdentity.inpatientNo &&
                    qcNormalize(sourceIdentity.inpatientNo) !==
                        qcNormalize(identity.inpatientNo)
                ) return null;
                return {
                    cacheKey: cacheDefinition[0],
                    label: cacheDefinition[1],
                    entry: entry,
                    text: texts[0],
                    records: Array.isArray(entry.records)
                        ? entry.records
                        : [],
                    sourceIdentity: sourceIdentity,
                    weakMatch: !sourceIdentity.inpatientNo
                };
            }
        ).filter(Boolean);
    }

    function qcChooseImportCandidate(candidates) {
        if (candidates.length === 1) return candidates[0];
        const message = [
            '发现多个可导入的住院信息缓存，请输入序号：'
        ].concat(
            candidates.map(function (candidate, index) {
                return (
                    (index + 1) + '. ' +
                    candidate.label + '（' +
                    candidate.text.length + '字符' +
                    (candidate.weakMatch
                        ? '，缓存缺少住院号'
                        : '，住院号一致') +
                    '）'
                );
            })
        ).join('\n');
        const answer = window.prompt(message, '1');
        if (answer === null) return null;
        const index = Number(answer) - 1;
        if (
            !Number.isInteger(index) ||
            index < 0 ||
            index >= candidates.length
        ) {
            throw new Error('导入序号无效');
        }
        return candidates[index];
    }

    function qcImportInpatientSource(type, identity) {
        qcRequireSourceIdentity(identity);
        const candidates = qcImportCandidates(type, identity);
        if (!candidates.length) {
            throw new Error(
                '住院信息脚本中未找到与当前患者匹配的该类缓存'
            );
        }
        const selected = qcChooseImportCandidate(candidates);
        if (!selected) return null;
        if (
            selected.weakMatch &&
            !window.confirm(
                '所选缓存没有住院号，只能依据患者姓名弱匹配。\n' +
                '为避免串档，请人工核对缓存确属“' +
                qcIdentityLabel(identity) +
                '”本次住院。是否继续复制到质控模块？'
            )
        ) return null;
        return {
            text: selected.text,
            records: selected.records,
            admissionTime: selected.entry.admissionTime || '',
            recordTime: selected.entry.recordTime || '',
            recordDates: Array.isArray(selected.entry.recordDates)
                ? selected.entry.recordDates.slice(0, 500)
                : [],
            origin: 'inpatient-cache',
            originLabel: '显式导入：' + selected.label,
            cacheKey: selected.cacheKey,
            sourceIdentity: selected.sourceIdentity,
            originalCapturedAt:
                selected.entry.capturedAt ||
                selected.entry.savedAt ||
                '',
            capturedAt: new Date().toLocaleString()
        };
    }

    function qcCollectSources(identity) {
        const sources = {
            entries: [],
            groups: {
                admission: [],
                progress: [],
                discharge: [],
                order: [],
                visible: [],
                supplement: []
            },
            orderRecords: [],
            sourceBundle: qcLoadSourceBundle(identity)
        };
        QUALITY_CONTROL_SOURCE_DEFINITIONS.forEach(
            function (definition) {
                const source =
                    sources.sourceBundle.sources[definition.type];
                if (!source || !String(source.text || '').trim()) return;
                const entry = Object.assign({}, source, {
                    identity: Object.assign(
                        {},
                        source.identity || identity || {}
                    )
                });
                sources.entries.push({
                    key: 'quality-source:' + definition.type,
                    label:
                        definition.label + '｜' +
                        qcSourceOriginLabel(source),
                    group: definition.group,
                    type: definition.type,
                    entry: entry
                });
                sources.groups[definition.group].push(
                    String(source.text).trim()
                );
                if (
                    definition.type === 'order' &&
                    Array.isArray(source.records)
                ) {
                    source.records.forEach(function (record) {
                        if (record && typeof record === 'object') {
                            sources.orderRecords.push(record);
                        }
                    });
                }
            }
        );
        return sources;
    }

    function qcJoinGroups(sources, groups) {
        return groups.reduce(function (values, group) {
            return values.concat(sources.groups[group] || []);
        }, []).filter(Boolean).join('\n\n');
    }

    function qcParseDateTime(value) {
        const text = String(value || '')
            .replace(/[年\/.]/g, '-')
            .replace(/月/g, '-')
            .replace(/日/g, ' ')
            .replace(/T/g, ' ')
            .replace(/\s+/g, ' ')
            .trim();
        const match = text.match(
            /(20\d{2})-(\d{1,2})-(\d{1,2})(?:\s+(\d{1,2}):(\d{1,2})(?::(\d{1,2}))?)?/
        );
        if (!match) return null;
        const result = new Date(
            Number(match[1]),
            Number(match[2]) - 1,
            Number(match[3]),
            Number(match[4] || 0),
            Number(match[5] || 0),
            Number(match[6] || 0)
        );
        return Number.isNaN(result.getTime()) ? null : result;
    }

    function qcDateString(value) {
        const date = value instanceof Date ? value : qcParseDateTime(value);
        if (!date) return '';
        return date.getFullYear() + '-' +
            pad2(date.getMonth() + 1) + '-' +
            pad2(date.getDate());
    }

    function qcDateTimeLabel(value) {
        const date = value instanceof Date ? value : qcParseDateTime(value);
        if (!date) return '';
        return qcDateString(date) + ' ' +
            pad2(date.getHours()) + ':' +
            pad2(date.getMinutes());
    }

    function qcExtractLabeledDateTime(text, labels) {
        const source = String(text || '');
        for (const label of labels) {
            const match = source.match(new RegExp(
                String(label) +
                '\\s*[：:]?\\s*' +
                '(20\\d{2}[年\\-\\/.]\\d{1,2}[月\\-\\/.]\\d{1,2}日?' +
                '(?:[ T\\s]+\\d{1,2}:\\d{1,2}(?::\\d{1,2})?)?)'
            ));
            if (match && match[1]) return qcParseDateTime(match[1]);
        }
        return null;
    }

    function qcExtractFirstCourseTime(text) {
        const source = String(text || '');
        let match = source.match(
            /(20\d{2}[年\-\/.]\d{1,2}[月\-\/.]\d{1,2}日?(?:[ T\s]+\d{1,2}:\d{1,2}(?::\d{1,2})?))[^\n\r]{0,40}首次病程记录/
        );
        if (match && match[1]) return qcParseDateTime(match[1]);
        match = source.match(
            /首次病程记录[^\n\r]{0,40}(20\d{2}[年\-\/.]\d{1,2}[月\-\/.]\d{1,2}日?(?:[ T\s]+\d{1,2}:\d{1,2}(?::\d{1,2})?))/
        );
        return match && match[1] ? qcParseDateTime(match[1]) : null;
    }

    function qcAdmissionTimes(sources) {
        let admissionTime = null;
        let recordTime = null;
        sources.entries.forEach(function (item) {
            if (item.group !== 'admission') {
                return;
            }
            admissionTime = admissionTime ||
                qcParseDateTime(item.entry.admissionTime);
            recordTime = recordTime ||
                qcParseDateTime(item.entry.recordTime);
        });
        const text = qcJoinGroups(
            sources,
            ['admission']
        );
        admissionTime = admissionTime || qcExtractLabeledDateTime(
            text,
            ['入院日期及时间', '入院日期', '入院时间']
        );
        recordTime = recordTime || qcExtractLabeledDateTime(
            text,
            ['记录日期及时间', '记录日期', '记录时间']
        );
        return { admissionTime: admissionTime, recordTime: recordTime };
    }

    function qcProgressRecords(sources) {
        const records = [];
        const text = qcJoinGroups(
            sources,
            ['progress']
        );
        const pattern =
            /(20\d{2}[年\-\/.]\d{1,2}[月\-\/.]\d{1,2}日?(?:[ T\s]+\d{1,2}:\d{1,2}(?::\d{1,2})?)?)[^\n\r]{0,45}(首次病程记录|(?:主治|主任|副主任|上级|日常|一般|普通)?医师?查房记录|病程记录)/g;
        let match = null;
        while ((match = pattern.exec(text))) {
            const date = qcParseDateTime(match[1]);
            if (date) {
                records.push({
                    date: qcDateString(date),
                    dateTime: date,
                    title: match[2] || '病程记录'
                });
            }
        }
        sources.entries.forEach(function (item) {
            const values = item.entry && item.entry.recordDates;
            if (!Array.isArray(values)) return;
            values.forEach(function (dateValue) {
                const date = qcParseDateTime(dateValue);
                if (date) {
                    records.push({
                        date: qcDateString(date),
                        dateTime: date,
                        title: '已缓存病程记录'
                    });
                }
            });
        });
        const unique = {};
        records.forEach(function (record) {
            const key = record.date + '|' + record.title;
            if (!unique[key]) unique[key] = record;
        });
        return Object.keys(unique).map(function (key) {
            return unique[key];
        }).sort(function (a, b) {
            return a.dateTime.getTime() - b.dateTime.getTime();
        });
    }

    function qcChiefComplaint(text) {
        const match = String(text || '').match(
            /主\s*诉\s*[：:]?\s*([\s\S]{1,160})/
        );
        if (!match || !match[1]) return '';
        return match[1]
            .split(/(?:\n\s*)?(?:现病史|既往史|个人史|婚育史|病例特点|入院情况)\s*[：:]?/)[0]
            .split(/\r?\n/)[0]
            .replace(/\s+/g, '')
            .replace(/[。；;]+$/, '')
            .slice(0, 100);
    }

    function qcOrderChangeDates(sources, admissionDate) {
        const dates = new Set();
        const include =
            /片|胶囊|颗粒|丸|口服液|注射液|针剂|静脉|静滴|口服|肌注|治疗|针法|针刺|灸|推拿|贴敷|康复|理疗|输液|补液/i;
        const exclude =
            /领药|护理|饮食|床位|体位|陪护|检查|检验|化验|血常规|生化|肝功|肾功|血脂|血糖|电解质|凝血|CT|MR|磁共振|超声|心电图|出院|转科/i;
        sources.orderRecords.forEach(function (record) {
            const name = String(
                record.name || record.orderName || record.itemName || ''
            ).trim();
            if (!name || exclude.test(name) || !include.test(name)) return;
            [record.startTime, record.stopTime].forEach(function (value) {
                const date = qcParseDateTime(value);
                const dateString = qcDateString(date);
                if (dateString && dateString !== admissionDate) {
                    dates.add(dateString);
                }
            });
        });
        return Array.from(dates).sort();
    }

    function qcInferLabState(sources) {
        const orderText = [
            qcJoinGroups(sources, ['order']),
            sources.orderRecords.map(function (record) {
                return String(
                    record.name || record.orderName || record.itemName || ''
                );
            }).join('\n')
        ].join('\n');
        const clinicalText = qcJoinGroups(
            sources,
            ['admission', 'progress', 'discharge']
        );
        const orderPattern =
            /血常规|全血细胞|血细胞计数|生化|肝功能|肝功|肾功能|肾功|血脂|血糖|电解质|凝血|D-?二聚体|糖化血红蛋白|血沉|C反应蛋白|CRP|肌钙蛋白|心肌酶|甲状腺功能|甲功|肿瘤标志/i;
        const resultPattern =
            /(?:白细胞|WBC|血红蛋白|HGB|血小板|PLT|丙氨酸氨基转移酶|ALT|天门冬氨酸|AST|肌酐|CREA|葡萄糖|GLU|总胆固醇|甘油三酯|血钾|血钠|凝血酶原|D-?二聚体)\s*(?:计数|结果|测定)?\s*[：:=]?\s*(?:↑|↓|\+|-)?\s*\d+(?:\.\d+)?|(?:化验|检验|实验室检查)(?:结果|回报)\s*[：:]/i;
        const refusalPattern =
            /(?:拒绝|不愿|拒查).{0,30}(?:抽血|采血|化验|检验|血液检查)|(?:抽血|采血|化验|检验|血液检查).{0,30}(?:拒绝|不愿|拒查)/i;
        const hasOrder = orderPattern.test(orderText);
        const hasReport = resultPattern.test(clinicalText);
        const hasRefusalText = refusalPattern.test(clinicalText);
        let suggestedStatus = 'unknown';
        if (hasReport) suggestedStatus = 'completed';
        else if (hasOrder) suggestedStatus = 'pending';
        else if (orderText.trim() || sources.orderRecords.length) {
            suggestedStatus = 'not_ordered';
        }
        return {
            hasOrder: hasOrder,
            hasReport: hasReport,
            hasRefusalText: hasRefusalText,
            suggestedStatus: suggestedStatus,
            evidence:
                '检验医嘱=' + (hasOrder ? '已检出' : '未检出') +
                '；化验结果=' + (hasReport ? '已检出' : '未检出') +
                '；拒绝表述=' +
                (hasRefusalText ? '检出但仍需人工确认' : '未检出')
        };
    }

    function qcDischargeAdvice(text) {
        const match = String(text || '').match(
            /出院医嘱\s*[：:]?\s*([\s\S]{0,3000})/
        );
        if (!match || !match[1]) return '';
        return match[1]
            .split(/(?:出院诊断|医师签名|医生签名|记录医师|签名日期)\s*[：:]?/)[0]
            .trim();
    }

    function qcAddResult(results, level, title, detail, action) {
        const ruleId = QUALITY_CONTROL_RULE_TITLE_MAP[title] || '';
        const config = results._qcRuleConfig || null;
        if (ruleId && config && !qcRuleEnabled(config, ruleId)) {
            return;
        }
        let finalLevel = level;
        const rule = ruleId && config && config.rules
            ? config.rules[ruleId]
            : null;
        if (
            rule &&
            (level === 'error' || level === 'warn') &&
            ['error', 'warn', 'info'].includes(rule.severity)
        ) {
            finalLevel = rule.severity;
        }
        results.push({
            level: finalLevel,
            title: title,
            detail: detail,
            action: action || '',
            ruleId: ruleId
        });
    }

    function qcRunChecks(identity, sources, state, lab, ruleConfig) {
        const results = [];
        results._qcRuleConfig = ruleConfig || qcLoadRuleConfig();
        const config = results._qcRuleConfig;
        const admissionText = qcJoinGroups(
            sources,
            ['admission']
        );
        const progressText = qcJoinGroups(
            sources,
            ['progress']
        );
        const dischargeText = qcJoinGroups(
            sources,
            ['discharge']
        );
        const clinicalText = [
            admissionText,
            progressText,
            dischargeText
        ].join('\n');

        if (identity.inpatientNo) {
            qcAddResult(
                results,
                'pass',
                '患者身份',
                '已按住院号锁定：' + qcIdentityLabel(identity)
            );
        } else if (identity.name) {
            qcAddResult(
                results,
                'warn',
                '患者身份',
                '当前仅按姓名匹配，存在同名或再次住院串档风险。',
                '建议补录住院号后重新扫描。'
            );
        } else {
            qcAddResult(
                results,
                'error',
                '患者身份',
                '未识别患者姓名或住院号。',
                '请人工填写姓名及住院号。'
            );
        }

        if (sources.entries.length) {
            const presentTypes = sources.entries.map(function (source) {
                return source.type;
            });
            const presentLabels = sources.entries.map(function (source) {
                return source.label;
            });
            const missingLabels = QUALITY_CONTROL_SOURCE_DEFINITIONS
                .filter(function (definition) {
                    return !presentTypes.includes(definition.type);
                })
                .map(function (definition) {
                    return definition.label;
                });
            qcAddResult(
                results,
                missingLabels.length ? 'warn' : 'pass',
                '资料来源',
                '本次仅使用质控模块的独立资料副本：' +
                    presentLabels.join('；') +
                    (missingLabels.length
                        ? '。尚未提供：' + missingLabels.join('、') + '。'
                        : '。四类资料均已提供。'),
                missingLabels.length
                    ? '按实际质控范围补充缺失资料；未提供的类型不会从住院缓存自动补入。'
                    : ''
            );
        } else {
            qcAddResult(
                results,
                'error',
                '资料来源',
                '没有可供质控的病历资料。',
                '请分别使用“抓取当前页”“手工录入/编辑”或“导入住院缓存”。'
            );
        }

        const chiefComplaint = qcChiefComplaint(admissionText);
        if (chiefComplaint) {
            const count =
                (chiefComplaint.match(/[\u3400-\u9fff]/g) || []).length;
            const chiefComplaintLimit = qcRuleNumber(
                config,
                'chiefComplaint',
                'maxChineseChars',
                22
            );
            qcAddResult(
                results,
                count <= chiefComplaintLimit ? 'pass' : 'error',
                '主诉字数',
                '识别为“' + chiefComplaint + '”，共' + count +
                    '个汉字' +
                    (
                        count <= chiefComplaintLimit
                            ? '，未超过配置上限' +
                                chiefComplaintLimit + '字。'
                            : '，超过配置上限' +
                                chiefComplaintLimit + '字。'
                    ),
                count <= chiefComplaintLimit
                    ? ''
                    : '压缩主诉，同时保留可导出第一诊断的核心线索。'
            );
            qcAddResult(
                results,
                'info',
                '主诉→第一诊断',
                '字面规则不能可靠判断主诉能否导出第一诊断。',
                '请人工核对主诉、现病史与第一诊断的逻辑对应。'
            );
        } else {
            qcAddResult(
                results,
                'warn',
                '主诉字数',
                '未从现有资料识别到“主诉”。',
                '请补充完整入院记录后重扫。'
            );
        }

        const times = qcAdmissionTimes(sources);
        const firstTime = qcExtractFirstCourseTime(progressText);
        const timingMinimum = qcRuleNumber(
            config,
            'admissionFirstCourseTiming',
            'minMinutes',
            30
        );
        const timingMaximum = qcRuleNumber(
            config,
            'admissionFirstCourseTiming',
            'maxMinutes',
            240
        );
        if (times.recordTime && firstTime) {
            const minutes = Math.round(
                (times.recordTime.getTime() - firstTime.getTime()) / 60000
            );
            if (minutes < 0) {
                qcAddResult(
                    results,
                    'error',
                    '入院记录与首程时序',
                    '入院记录时间' + qcDateTimeLabel(times.recordTime) +
                        '早于首次病程时间' + qcDateTimeLabel(firstTime) + '。',
                    '确保入院记录时间不得早于首次病程。'
                );
            } else if (
                minutes < timingMinimum ||
                minutes > timingMaximum
            ) {
                qcAddResult(
                    results,
                    'warn',
                    '入院记录与首程时序',
                    '顺序正确，但间隔' + minutes +
                        '分钟，不在当前配置的' + timingMinimum +
                        '至' + timingMaximum + '分钟范围。',
                    '核对两个文书的实际完成时间。'
                );
            } else {
                qcAddResult(
                    results,
                    'pass',
                    '入院记录与首程时序',
                    '首程' + qcDateTimeLabel(firstTime) +
                        '；入院记录' + qcDateTimeLabel(times.recordTime) +
                        '；间隔' + minutes + '分钟。'
                );
            }
        } else {
            qcAddResult(
                results,
                'warn',
                '入院记录与首程时序',
                '缺少首次病程时间或入院记录时间，无法完成时序校验。',
                '请确保预览正文包含精确到分钟的记录时间。'
            );
        }

        const records = qcProgressRecords(sources);
        const progressDates = Array.from(new Set(
            records.map(function (record) { return record.date; })
        ));
        let maxGap = 0;
        let maxGapLabel = '';
        for (let index = 1; index < progressDates.length; index += 1) {
            const previous = qcParseDateTime(progressDates[index - 1]);
            const current = qcParseDateTime(progressDates[index]);
            const gap = calendarDayDifference(previous, current);
            if (gap > maxGap) {
                maxGap = gap;
                maxGapLabel =
                    progressDates[index - 1] + '至' + progressDates[index];
            }
        }
        const firstLevelNursing = /一级护理/.test(clinicalText);
        const normalAllowedGap = qcRuleNumber(
            config,
            'progressFrequency',
            'normalMaxGapDays',
            3
        );
        const firstLevelAllowedGap = qcRuleNumber(
            config,
            'progressFrequency',
            'firstLevelNursingMaxGapDays',
            1
        );
        const allowedGap = firstLevelNursing
            ? firstLevelAllowedGap
            : normalAllowedGap;
        if (progressDates.length >= 2) {
            qcAddResult(
                results,
                maxGap > allowedGap ? 'error' : 'pass',
                '病程记录频率',
                '识别到' + progressDates.length +
                    '个病程日期，最大间隔' + maxGap + '天' +
                    (maxGapLabel ? '（' + maxGapLabel + '）' : '') +
                    (firstLevelNursing ? '；检出一级护理。' : '。'),
                maxGap > allowedGap
                    ? (
                        firstLevelNursing
                            ? '一级护理期间最大间隔按当前配置为' +
                                firstLevelAllowedGap + '天。'
                            : '一般病程最大间隔按当前配置为' +
                                normalAllowedGap + '天，请核对漏记。'
                    )
                    : ''
            );
        } else {
            qcAddResult(
                results,
                'warn',
                '病程记录频率',
                '仅识别到' + progressDates.length +
                    '个病程日期，无法判断连续住院期间是否漏记。',
                '请提供完整病程记录预览。'
            );
        }

        if (times.admissionTime) {
            const admissionDate = qcDateString(times.admissionTime);
            const firstAttending = records.find(function (record) {
                return /主治医师查房记录/.test(record.title);
            });
            if (firstAttending) {
                const dayGap = calendarDayDifference(
                    qcParseDateTime(admissionDate),
                    qcParseDateTime(firstAttending.date)
                );
                const attendingMaximum = qcRuleNumber(
                    config,
                    'firstAttendingRound',
                    'maxDaysAfterAdmission',
                    0
                );
                qcAddResult(
                    results,
                    dayGap <= attendingMaximum ? 'pass' : 'warn',
                    '首次主治医师查房',
                    '首次主治医师查房日期' + firstAttending.date +
                        '；入院日期' + admissionDate +
                        '；相隔' + dayGap + '天；配置上限' +
                        attendingMaximum + '天。',
                    dayGap <= attendingMaximum
                        ? ''
                        : '按当前科室规则核对首次主治查房时限。'
                );
            } else {
                qcAddResult(
                    results,
                    'warn',
                    '首次主治医师查房',
                    '未识别到“主治医师查房记录”。',
                    '核对入院第一天是否已完成。'
                );
            }
        }
        qcAddResult(
            results,
            'info',
            '查房记录动态性',
            '脚本可检查日期和标题，但不能仅凭字面可靠判断病情是否较前一日有动态变化。',
            '人工核对症状、血压/查体变化及上级医师分析，避免原样复制。'
        );

        const admissionDate = times.admissionTime
            ? qcDateString(times.admissionTime)
            : '';
        const changeDates = qcOrderChangeDates(sources, admissionDate);
        const missingDates = changeDates.filter(function (date) {
            return !progressDates.includes(date);
        });
        if (sources.orderRecords.length && changeDates.length) {
            qcAddResult(
                results,
                missingDates.length ? 'warn' : 'pass',
                '医嘱变更当日病程',
                missingDates.length
                    ? '以下用药/治疗医嘱启停日期未匹配同日病程：' +
                        missingDates.slice(0, 8).join('、') +
                        (missingDates.length > 8 ? '等。' : '。')
                    : '识别到的' + changeDates.length +
                        '个用药/治疗医嘱启停日期均有同日病程。',
                missingDates.length
                    ? '逐日核对实际变更原因；本项只提示日期。'
                    : ''
            );
        } else {
            qcAddResult(
                results,
                'info',
                '医嘱变更当日病程',
                sources.orderRecords.length
                    ? '未识别到需单列核对的用药/治疗医嘱启停日期。'
                    : '当前医嘱资料没有结构化记录，无法自动映射。',
                sources.orderRecords.length
                    ? ''
                    : '在医嘱查询页使用“抓取当前页”，或显式导入带结构化记录的住院医嘱缓存后再扫。'
            );
        }

        const labStatus = state.labStatus || 'unknown';
        if (labStatus === 'refused') {
            if (!String(state.refusalItems || '').trim() ||
                !String(state.refusalTime || '').trim()) {
                qcAddResult(
                    results,
                    'error',
                    '未查血/拒绝检查闭环',
                    '已人工确认拒绝，但项目或告知时间不完整。',
                    '补全后再生成待签署文书。'
                );
            } else if (!String(state.refusalDraft || '').trim()) {
                qcAddResult(
                    results,
                    'warn',
                    '未查血/拒绝检查闭环',
                    '拒绝事实已人工确认，尚未生成待签署文书。',
                    '点击“生成待签署拒绝文书”。'
                );
            } else if (!state.signedConfirmed) {
                qcAddResult(
                    results,
                    'warn',
                    '未查血/拒绝检查闭环',
                    '已生成待签署文书，尚未登记已核对真实签署。',
                    '完成真实签署后再作本机登记；脚本不会代签。'
                );
            } else {
                qcAddResult(
                    results,
                    'info',
                    '未查血/拒绝检查闭环',
                    '本机已登记经办人核对签署完成：' +
                        (state.signedConfirmedAt || '未记录时间') + '。',
                    '最终以HIS电子签名或纸质原件为准。'
                );
            }
        } else if (labStatus === 'completed') {
            qcAddResult(
                results,
                lab.hasReport ? 'pass' : 'warn',
                '入院抽血/化验状态',
                lab.hasReport
                    ? '人工分类为“已完成”，并检出结果证据。'
                    : '人工分类为“已完成”，但当前资料未检出结果证据。',
                lab.hasReport ? '' : '补充报告正文或核对分类。'
            );
        } else if (labStatus !== 'unknown') {
            qcAddResult(
                results,
                'warn',
                '入院抽血/化验状态',
                '当前人工分类：' +
                    (QUALITY_CONTROL_LAB_STATUS_LABELS[labStatus] || labStatus) +
                    '。',
                labStatus === 'not_ordered'
                    ? '未开医嘱不等同于患者拒绝，请决定补开、说明或其他处置。'
                    : '按实际流程补全医嘱、报告、原因说明或签字材料。'
            );
        } else {
            qcAddResult(
                results,
                lab.hasReport ? 'pass' : 'warn',
                '入院抽血/化验状态',
                lab.evidence + '；尚未完成人工分类。',
                lab.hasRefusalText
                    ? '即使检出拒绝字样，仍须人工确认主体、项目、时间和签署。'
                    : '未发现报告不能自动认定患者拒绝。'
            );
        }

        if (state.progressRefusalConfirmed) {
            if (
                !String(
                    state.progressRefusalItems ||
                    ''
                ).trim() ||
                !String(
                    state.progressRefusalTime ||
                    ''
                ).trim()
            ) {
                qcAddResult(
                    results,
                    'error',
                    '病程拒绝相关描述',
                    '已勾选拒绝、风险告知及签署确认，但拒绝项目或沟通时间不完整。',
                    '补全信息后再生成病程描述。'
                );
            } else if (
                !String(
                    state.progressRefusalText ||
                    ''
                ).trim()
            ) {
                qcAddResult(
                    results,
                    'warn',
                    '病程拒绝相关描述',
                    '已确认存在拒绝事实，但尚未生成病程描述。',
                    '使用“生成病程描述”或“一键生成并复制”。'
                );
            } else if (
                !String(
                    state.progressRefusalText ||
                    ''
                ).includes(
                    '签署相关知情告知书'
                )
            ) {
                qcAddResult(
                    results,
                    'warn',
                    '病程拒绝相关描述',
                    '当前描述未包含知情告知书签署表述，可能是旧版缓存或人工编辑内容。',
                    '核对签署原件后重新生成，或补全表述再复制。'
                );
            } else {
                qcAddResult(
                    results,
                    'info',
                    '病程拒绝相关描述',
                    state.progressRefusalCopiedAt
                        ? '描述已生成并于' +
                            state.progressRefusalCopiedAt +
                            '复制。'
                        : '描述已生成，但尚未记录复制时间。',
                    '复制不等于已经写入病程；请粘贴、核对并在HIS中手动保存。'
                );
            }
        }

        const advice = qcDischargeAdvice(dischargeText);
        if (advice) {
            const numbering = advice.match(
                /(?:^|\n|\s)(?:\d{1,2}|[一二三四五六七八九十]+)\s*[.、．](?=\s*[\u3400-\u9fff])/g
            ) || [];
            const minimumNumberedItems = qcRuleNumber(
                config,
                'dischargeAdviceNumbering',
                'minimumNumberedItems',
                2
            );
            qcAddResult(
                results,
                numbering.length >= minimumNumberedItems
                    ? 'pass'
                    : 'error',
                '出院医嘱分条',
                numbering.length >= minimumNumberedItems
                    ? '识别到' + numbering.length +
                        '个编号条目，达到配置的至少' +
                        minimumNumberedItems + '条。'
                    : '识别到' + numbering.length +
                        '个编号条目，少于配置的' +
                        minimumNumberedItems + '条。',
                numbering.length >= minimumNumberedItems
                    ? ''
                    : '按“1.、2.、3.”逐条列项，禁止合成一段。'
            );
            const firstItem = advice
                .replace(/^\s*(?:1|一)\s*[.、．]\s*/, '')
                .split(/(?:\n|\s)(?:2|二)\s*[.、．]\s*/)[0];
            qcAddResult(
                results,
                /中医调护/.test(firstItem) ? 'pass' : 'warn',
                '出院医嘱首条',
                /中医调护/.test(firstItem)
                    ? '首条已识别到“中医调护”。'
                    : '首条未识别到“中医调护”。',
                /中医调护/.test(firstItem)
                    ? ''
                    : '按科室新规将中医调护置于首条。'
            );

            const mentionsLongTermMedication =
                /长期用药|继续(?:服用|口服)|出院带药/.test(
                    advice
                );
            const hasSpecificDrugName =
                /[\u3400-\u9fffA-Za-z0-9（）()]+(?:片|胶囊|颗粒|丸|滴丸|口服液|注射液)/.test(
                    advice
                );

            if (mentionsLongTermMedication) {
                qcAddResult(
                    results,
                    hasSpecificDrugName ? 'pass' : 'warn',
                    '出院长期用药',
                    hasSpecificDrugName
                        ? '长期/继续用药条目中识别到具体药品名称。'
                        : '提到长期或继续用药，但未识别到具体药品名称。',
                    hasSpecificDrugName
                        ? '仍需人工核对剂量、用法和疗程。'
                        : '列明药品全名，并核对剂量、用法和疗程。'
                );
            }
        } else {
            qcAddResult(
                results,
                'warn',
                '出院医嘱',
                '未识别到“出院医嘱”正文。',
                '出院前请提供完整出院记录复查。'
            );
        }

        if (lab.hasReport) {
            const hasHospital =
                /(?:本院|我院|外院|医院|卫生院|医学中心)/.test(clinicalText);
            qcAddResult(
                results,
                hasHospital ? 'pass' : 'warn',
                '辅助检查来源',
                hasHospital
                    ? '检出化验结果及医院来源表述。'
                    : '检出化验结果，但未识别检查医院名称或本院/外院标注。',
                hasHospital
                    ? ''
                    : '补充检查日期、关键结果及医院来源。'
            );
        }

        qcAddResult(
            results,
            'info',
            '医嘱单/收费单/报告单三单对齐',
            '当前模块只读取四类独立资料中的医嘱和报告文字，但没有可靠的收费单结构化数据。',
            '最终由经办人核对医嘱单、收费单、检查报告单的项目、时间和患者身份完全一致。'
        );

        qcAddResult(
            results,
            /出院诊断\s*[：:]/.test(dischargeText) ? 'info' : 'warn',
            '出院诊断闭环',
            /出院诊断\s*[：:]/.test(dischargeText)
                ? '已识别出院诊断栏目，仍需临床判断病程是否形成闭环。'
                : '未识别到出院诊断栏目。',
            '人工核对出院诊断是否已在病程中明确形成或调整依据。'
        );

        qcAddResult(
            results,
            'info',
            '病情告知书',
            '本版四类独立资料不包含完成版病情告知书，系统不会用首次病程或其他缓存替代告知书。',
            '请在实际告知书页面核对诊断、计划、风险、替代方案、告知对象、精确到分钟的时间及真实签名。'
        );
        if (String(config.additionalPolicyText || '').trim()) {
            results.push({
                level: 'info',
                title: '补充质控政策',
                detail: '已配置自由文本补充政策；结构化初筛不会把自由文本当作可执行代码。',
                action: '本项由AI质控结合原文复核，并由医师人工确认：' +
                    String(config.additionalPolicyText || '').trim(),
                ruleId: 'additionalPolicyText'
            });
        }
        return results;
    }

    function qcDefaultState() {
        const now = new Date();
        const defaultDateTime =
            now.getFullYear() + '-' +
            pad2(now.getMonth() + 1) + '-' +
            pad2(now.getDate()) + 'T' +
            pad2(now.getHours()) + ':' +
            pad2(now.getMinutes());

        return {
            labStatus: 'unknown',
            supplement: '',
            refusalItems: '',
            refusalTime: defaultDateTime,
            refusalParty: '患者本人',
            refusalRelation: '',
            refusalReason: '经充分沟通后仍拒绝接受上述检查',
            refusalDraft: '',
            signedConfirmed: false,
            signedConfirmedAt: '',
            progressRefusalType: 'lab',
            progressRefusalItems: '',
            progressRefusalTime: defaultDateTime,
            progressRefusalParty: '患者本人',
            progressRefusalRelation: '',
            progressRefusalReason: '',
            progressRefusalFollowUp: '',
            progressRefusalConsentVersion: 2,
            progressRefusalConfirmed: false,
            progressRefusalText: '',
            progressRefusalCopiedAt: ''
        };
    }

    function qcStateStore() {
        const stored =
            patientLargeCacheReadStore(
                QUALITY_CONTROL_STATE_STORAGE_KEY
            );

        return stored &&
            typeof stored === 'object' &&
            !Array.isArray(stored)
                ? stored
                : {};
    }

    function qcLoadPatientState(identity) {
        const key = qcIdentityKey(identity);
        const stored = key ? qcStateStore()[key] : null;
        const state = Object.assign(
            {},
            qcDefaultState(),
            stored && typeof stored === 'object' ? stored : {}
        );

        if (
            stored &&
            typeof stored === 'object' &&
            Number(
                stored.progressRefusalConsentVersion ||
                0
            ) < 2
        ) {
            state.progressRefusalConfirmed = false;
            state.progressRefusalCopiedAt = '';
        }

        state.progressRefusalConsentVersion = 2;
        return state;
    }

    function qcSaveTarget(identity) {
        if (!identity || (!identity.name && !identity.inpatientNo)) return;
        try {
            localStorage.setItem(
                QUALITY_CONTROL_TARGET_STORAGE_KEY,
                JSON.stringify(identity)
            );
        } catch (error) {
            // 本地保存失败不阻止本次质控。
        }
    }

    function qcModalIdentity(modal) {
        return {
            name: qcCleanName(
                modal.querySelector('.quality-patient-name').value
            ),
            inpatientNo: String(
                modal.querySelector('.quality-patient-no').value || ''
            ).trim(),
            bed: '',
            sex: '',
            age: ''
        };
    }

    function qcPatientUnlocked(modal) {
        return Boolean(modal && modal._qcPatientUnlocked);
    }

    function qcApplyPatientLockState(modal, unlocked, detected) {
        if (!modal) return;
        modal._qcPatientUnlocked = Boolean(unlocked);
        const nameInput = modal.querySelector('.quality-patient-name');
        const noInput = modal.querySelector('.quality-patient-no');
        const toggle = modal.querySelector('.quality-patient-lock-toggle');
        if (nameInput) nameInput.readOnly = !modal._qcPatientUnlocked;
        if (noInput) noInput.readOnly = !modal._qcPatientUnlocked;
        if (toggle) {
            toggle.textContent = modal._qcPatientUnlocked
                ? '重新锁定患者'
                : '解锁当前患者';
            toggle.title = modal._qcPatientUnlocked
                ? '重新开启患者一致性校验'
                : '人工关闭患者一致性校验并允许编辑';
        }
        qcSetPatientStatus(
            modal,
            detected || {
                identity: qcModalIdentity(modal),
                source: modal._qcPatientUnlocked
                    ? '人工解锁输入'
                    : '人工确认并锁定'
            }
        );
    }

    function qcSaveBoundModalPatient(modal) {
        if (!modal) return;
        const identity = Object.assign(
            {},
            modal._qcIdentity || qcModalIdentity(modal)
        );
        qcSavePatientState(identity, qcModalState(modal));
        qcRepairFlushResultSave(modal, identity);
    }

    function qcAdoptModalPatientIdentity(modal, identity, detected) {
        const nextIdentity = Object.assign({}, identity || {});
        const nextKey = qcIdentityKey(nextIdentity);
        const previousKey = String(modal._qcIdentityKey || '');
        if (nextKey !== previousKey) {
            if (previousKey) qcSaveBoundModalPatient(modal);
            qcPopulateState(
                modal,
                qcLoadPatientState(nextIdentity),
                nextIdentity
            );
        } else {
            modal._qcIdentity = Object.assign({}, nextIdentity);
            modal._qcIdentityKey = nextKey;
        }
        qcSaveTarget(nextIdentity);
        qcSetPatientStatus(
            modal,
            detected || {
                identity: nextIdentity,
                source: qcPatientUnlocked(modal)
                    ? '人工解锁输入'
                    : '人工确认并锁定'
            }
        );
        return nextIdentity;
    }

    function qcGuardModalPatientIdentity(
        modal
    ) {
        const identity =
            qcModalIdentity(modal);
        const identityKey =
            qcIdentityKey(identity);

        if (
            identityKey !==
                String(modal._qcIdentityKey || '')
        ) {
            qcAdoptModalPatientIdentity(
                modal,
                identity,
                {
                    identity: identity,
                    source: qcPatientUnlocked(modal)
                        ? '人工解锁输入'
                        : '异常身份变更（请核对）'
                }
            );

            if (!qcPatientUnlocked(modal)) {
                throw new Error(
                    '检测到锁定患者身份已改变，已切换到新患者的独立资料；请核对后重新操作'
                );
            }
            return identity;
        }

        modal._qcIdentity =
            Object.assign({}, identity);
        modal._qcIdentityKey =
            identityKey;

        return identity;
    }

    function qcModalState(modal) {
        const previous = modal._qcState || qcDefaultState();
        const signed = Boolean(
            modal.querySelector('.quality-signed-confirmed').checked
        );
        let signedAt = String(previous.signedConfirmedAt || '');
        if (signed && !previous.signedConfirmed) {
            signedAt = new Date().toLocaleString();
        }
        if (!signed) signedAt = '';
        return {
            labStatus:
                modal.querySelector('.quality-lab-status').value ||
                'unknown',
            supplement: '',
            refusalItems:
                modal.querySelector('.quality-refusal-items').value,
            refusalTime:
                modal.querySelector('.quality-refusal-time').value,
            refusalParty:
                modal.querySelector('.quality-refusal-party').value,
            refusalRelation:
                modal.querySelector('.quality-refusal-relation').value,
            refusalReason:
                modal.querySelector('.quality-refusal-reason').value,
            refusalDraft:
                modal.querySelector('.quality-refusal-draft').value,
            signedConfirmed: signed,
            signedConfirmedAt: signedAt,
            progressRefusalType:
                modal.querySelector(
                    '.quality-progress-refusal-type'
                ).value || 'lab',
            progressRefusalItems:
                modal.querySelector(
                    '.quality-progress-refusal-items'
                ).value,
            progressRefusalTime:
                modal.querySelector(
                    '.quality-progress-refusal-time'
                ).value,
            progressRefusalParty:
                modal.querySelector(
                    '.quality-progress-refusal-party'
                ).value,
            progressRefusalRelation:
                modal.querySelector(
                    '.quality-progress-refusal-relation'
                ).value,
            progressRefusalReason:
                modal.querySelector(
                    '.quality-progress-refusal-reason'
                ).value,
            progressRefusalFollowUp:
                modal.querySelector(
                    '.quality-progress-refusal-follow-up'
                ).value,
            progressRefusalConsentVersion: 2,
            progressRefusalConfirmed:
                Boolean(
                    modal.querySelector(
                        '.quality-progress-refusal-confirmed'
                    ).checked
                ),
            progressRefusalText:
                modal.querySelector(
                    '.quality-progress-refusal-text'
                ).value,
            progressRefusalCopiedAt:
                String(
                    previous.progressRefusalCopiedAt ||
                    ''
                )
        };
    }

    function qcSavePatientState(identity, state) {
        const key =
            qcIdentityKey(
                identity
            );

        if (!key) return;

        try {
            const store =
                qcStateStore();

            store[key] =
                Object.assign(
                    {},
                    state,
                    {
                        updatedAt:
                            new Date()
                                .toLocaleString()
                    }
                );

            patientLargeCacheWriteStore(
                QUALITY_CONTROL_STATE_STORAGE_KEY,
                store
            );
        } catch (error) {
            // 患者质控状态缓存失败不阻止本次质控。
        }
    }

    function qcToggleRefusalPanel(modal) {
        modal.querySelector('.quality-refusal-panel').hidden =
            modal.querySelector('.quality-lab-status').value !== 'refused';
    }

    function qcPopulateState(modal, state, identity) {
        const value = Object.assign({}, qcDefaultState(), state || {});
        modal._qcState = value;
        if (identity) {
            modal._qcIdentity = Object.assign({}, identity);
            modal._qcIdentityKey = qcIdentityKey(identity);
        }
        modal.querySelector('.quality-lab-status').value =
            value.labStatus;
        modal.querySelector('.quality-refusal-items').value =
            value.refusalItems;
        modal.querySelector('.quality-refusal-time').value =
            value.refusalTime;
        modal.querySelector('.quality-refusal-party').value =
            value.refusalParty;
        modal.querySelector('.quality-refusal-relation').value =
            value.refusalRelation;
        modal.querySelector('.quality-refusal-reason').value =
            value.refusalReason;
        modal.querySelector('.quality-refusal-draft').value =
            value.refusalDraft;
        modal.querySelector('.quality-signed-confirmed').checked =
            Boolean(value.signedConfirmed);
        modal.querySelector(
            '.quality-progress-refusal-type'
        ).value = value.progressRefusalType;
        modal.querySelector(
            '.quality-progress-refusal-items'
        ).value = value.progressRefusalItems;
        modal.querySelector(
            '.quality-progress-refusal-time'
        ).value = value.progressRefusalTime;
        modal.querySelector(
            '.quality-progress-refusal-party'
        ).value = value.progressRefusalParty;
        modal.querySelector(
            '.quality-progress-refusal-relation'
        ).value = value.progressRefusalRelation;
        modal.querySelector(
            '.quality-progress-refusal-reason'
        ).value = value.progressRefusalReason;
        modal.querySelector(
            '.quality-progress-refusal-follow-up'
        ).value = value.progressRefusalFollowUp;
        modal.querySelector(
            '.quality-progress-refusal-confirmed'
        ).checked = Boolean(
            value.progressRefusalConfirmed
        );
        modal.querySelector(
            '.quality-progress-refusal-text'
        ).value = value.progressRefusalText;
        qcRenderSourceCards(modal, identity || {});
        qcRepairPopulatePatientResults(modal, identity || {});
        qcToggleRefusalPanel(modal);
    }

    function qcRenderResults(modal, results) {
        const counts = { pass: 0, warn: 0, error: 0, info: 0 };
        const labels = {
            pass: '通过',
            warn: '提醒',
            error: '需整改',
            info: '人工核对'
        };
        results.forEach(function (result) {
            counts[result.level] += 1;
        });
        const summary = modal.querySelector('.quality-result-summary');
        summary.textContent =
            '需整改' + counts.error + '项；提醒' + counts.warn +
            '项；通过' + counts.pass + '项；人工核对' +
            counts.info + '项。';
        summary.className =
            'quality-status quality-result-summary ' +
            (counts.error ? 'error' : counts.warn ? 'warn' : 'ok');
        modal.querySelector('.quality-results').innerHTML =
            results.map(function (result) {
                return (
                    '<div class="quality-result-item ' +
                        result.level + '">' +
                        '<div class="quality-result-head">' +
                            '<span class="quality-badge">' +
                                escapeHtml(labels[result.level]) +
                            '</span>' +
                            '<strong>' +
                                escapeHtml(result.title) +
                            '</strong>' +
                        '</div>' +
                        '<div>' +
                            escapeHtml(result.detail) +
                        '</div>' +
                        (
                            result.action
                                ? '<div class="quality-result-action">建议：' +
                                    escapeHtml(result.action) +
                                  '</div>'
                                : ''
                        ) +
                    '</div>'
                );
            }).join('');
    }

    function qcExecuteScan(modal, notifyUser) {
        if (notifyUser !== false) {
            qcSetSectionCollapsedByKey(
                modal,
                'results',
                false,
                true
            );
        }

        const identity = qcModalIdentity(modal);
        if (!identity.name && !identity.inpatientNo) {
            qcRenderResults(modal, [{
                level: 'error',
                title: '患者身份',
                detail: '请先填写患者姓名或住院号。',
                action: '优先填写住院号，避免同名或再次住院串档。'
            }]);
            if (notifyUser !== false) {
                showStatus('质控扫描未执行：缺少患者身份。', 'error');
            }
            return;
        }

        const identityKey = qcIdentityKey(identity);
        if (
            identityKey !== String(modal._qcIdentityKey || '')
        ) {
            qcAdoptModalPatientIdentity(
                modal,
                identity,
                {
                    identity: identity,
                    source: qcPatientUnlocked(modal)
                        ? '人工解锁输入'
                        : '患者身份已切换'
                }
            );
        } else {
            modal._qcIdentity = Object.assign({}, identity);
            modal._qcIdentityKey = identityKey;
        }

        qcSaveTarget(identity);
        const state = qcModalState(modal);
        const sources = qcCollectSources(identity);
        const lab = qcInferLabState(sources);
        const ruleConfig = qcLoadRuleConfig();

        /*
         * 自动识别结果只作为建议，不覆盖人工选择。
         * 即使正文出现“拒绝”字样，也绝不自动切换为refused。
         */
        modal._qcState = state;
        modal._qcSources = sources;
        modal._qcLab = lab;
        modal.querySelector('.quality-lab-evidence').textContent =
            lab.evidence +
            (
                lab.suggestedStatus !== 'unknown'
                    ? '；系统建议=' +
                        QUALITY_CONTROL_LAB_STATUS_LABELS[
                            lab.suggestedStatus
                        ]
                    : ''
            ) +
            '。建议不会覆盖人工选择，且绝不会自动选择“患者拒绝”。';
        qcToggleRefusalPanel(modal);

        const results = qcRunChecks(
            identity,
            sources,
            state,
            lab,
            ruleConfig
        );
        qcRenderResults(modal, results);
        qcSavePatientState(identity, state);

        if (notifyUser !== false) {
            const errors = results.filter(function (item) {
                return item.level === 'error';
            }).length;
            const warnings = results.filter(function (item) {
                return item.level === 'warn';
            }).length;
            showStatus(
                '病案质控完成：需整改' + errors +
                    '项，提醒' + warnings +
                    '项。结果只作辅助核对，不会自动保存病历。',
                errors ? 'error' : 'success'
            );
        }
    }

    function qcEscapeRegExp(value) {
        return String(value || '').replace(
            /[-/\\^$*+?.()|[\]{}]/g,
            '\\$&'
        );
    }

    function qcDeidentifyText(value, identity) {
        let text = String(value || '');
        const item = identity || {};
        [item.name, item.inpatientNo].forEach(function (token) {
            const clean = String(token || '').trim();
            if (!clean) return;
            text = text.replace(
                new RegExp(qcEscapeRegExp(clean), 'gi'),
                clean === String(item.name || '').trim()
                    ? '[患者]'
                    : '[住院号已脱敏]'
            );
        });
        return text
            .replace(
                /((?:患者姓名|病人姓名|联系人姓名|联系人|姓名)\s*[：:])\s*[^\s，,；;\n\r]{1,20}/g,
                '$1[已脱敏]'
            )
            .replace(
                /((?:住院号|病案号|身份证号)\s*[：:])\s*[A-Za-z0-9Xx-]{4,24}/g,
                '$1[已脱敏]'
            )
            .replace(/\b1\d{10}\b/g, '[手机号已脱敏]')
            .replace(/\b\d{17}[\dXx]\b/g, '[身份证号已脱敏]')
            .replace(
                /((?:现住址|户口地址|家庭住址|联系地址|地址)\s*[：:])[^\n\r]{1,100}/g,
                '$1[已脱敏]'
            );
    }

    function qcAiExcerpt(value, maximumLength) {
        const text = String(value || '').trim();
        const limit = Math.max(1000, Number(maximumLength || 12000));
        if (text.length <= limit) return text;
        const headLength = Math.round(limit * 0.62);
        const tailLength = limit - headLength;
        return (
            text.slice(0, headLength) +
            '\n\n[中间内容因长度限制已截断]\n\n' +
            text.slice(-tailLength)
        );
    }

    function qcRequestDeepSeek(settings, messages, options) {
        const config = options || {};
        return new Promise(function (resolve, reject) {
            const payload = {
                model: settings.model,
                messages: messages,
                temperature:
                    Number.isFinite(config.temperature)
                        ? config.temperature
                        : 0.1,
                max_tokens: config.maxTokens || 3500,
                stream: false
            };
            if (config.json) {
                payload.response_format = {
                    type: 'json_object'
                };
            }
            const requestHandle = suiteGlobalAiXmlhttpRequest({
                method: 'POST',
                url: DEEPSEEK_ENDPOINT,
                headers: {
                    'Content-Type': 'application/json',
                    Authorization: 'Bearer ' + settings.apiKey
                },
                data: JSON.stringify(payload),
                timeout: 120000,
                onload: function (response) {
                    if (
                        response.status < 200 ||
                        response.status >= 300
                    ) {
                        reject(new Error(
                            'DeepSeek接口返回HTTP ' +
                            response.status + '：' +
                            String(response.responseText || '')
                                .slice(0, 500)
                        ));
                        return;
                    }
                    try {
                        const outer = JSON.parse(response.responseText);
                        const content =
                            outer &&
                            outer.choices &&
                            outer.choices[0] &&
                            outer.choices[0].message
                                ? String(
                                    outer.choices[0].message.content || ''
                                ).trim()
                                : '';
                        if (!content) {
                            throw new Error('接口未返回有效内容');
                        }
                        resolve(content);
                    } catch (error) {
                        reject(new Error(
                            'DeepSeek结果解析失败：' + error.message
                        ));
                    }
                },
                onerror: function () {
                    reject(new Error('DeepSeek网络请求失败'));
                },
                ontimeout: function () {
                    reject(new Error('DeepSeek请求超时'));
                },
                onabort: function () {
                    reject(new Error('AI请求已中止'));
                }
            });
            if (typeof config.onRequest === 'function') {
                try {
                    config.onRequest(requestHandle);
                } catch (error) {
                    // 请求句柄仅用于可选的窗口级中止，不影响正常AI调用。
                }
            }
        });
    }

    function qcAiLevel(value) {
        const level = String(value || '').toLowerCase();
        if (/high|critical|error|严重|高/.test(level)) return 'error';
        if (/medium|warn|中/.test(level)) return 'warn';
        if (/pass|通过/.test(level)) return 'pass';
        return 'info';
    }

    function qcRenderAiResults(modal, result) {
        const value = result && typeof result === 'object' ? result : {};
        const issues = Array.isArray(value.issues) ? value.issues : [];
        const manualReview = Array.isArray(value.manualReview)
            ? value.manualReview
            : Array.isArray(value.manual_review)
                ? value.manual_review
                : [];
        const conclusion = String(
            value.conclusion || value.summary || 'AI未提供总体结论'
        ).trim();
        const resultBox = modal.querySelector('.quality-ai-results');
        const status = modal.querySelector('.quality-ai-status');
        const plainLines = [
            'AI质控结论：' + conclusion
        ];
        const html = [
            '<div class="quality-result-item info">' +
                '<div class="quality-result-head">' +
                    '<span class="quality-badge">AI结论</span>' +
                    '<strong>' + escapeHtml(conclusion) + '</strong>' +
                '</div>' +
            '</div>'
        ];
        issues.forEach(function (issue, index) {
            const level = qcAiLevel(issue && issue.level);
            const documentName = String(
                issue && (
                    issue.document ||
                    issue.module ||
                    issue.source
                ) || '跨文书'
            ).trim();
            const item = String(
                issue && (
                    issue.item ||
                    issue.title ||
                    issue.problem
                ) || ('问题' + (index + 1))
            ).trim();
            const evidence = String(
                issue && issue.evidence || '未提供原文证据'
            ).trim();
            const suggestion = String(
                issue && (
                    issue.suggestion ||
                    issue.action
                ) || '请医师人工复核'
            ).trim();
            html.push(
                '<div class="quality-result-item ' + level + '">' +
                    '<div class="quality-result-head">' +
                        '<span class="quality-badge">' +
                            escapeHtml(
                                level === 'error'
                                    ? '高风险'
                                    : level === 'warn'
                                        ? '需复核'
                                        : '提示'
                            ) +
                        '</span>' +
                        '<strong>' +
                            escapeHtml(documentName + '｜' + item) +
                        '</strong>' +
                    '</div>' +
                    '<div>依据：' + escapeHtml(evidence) + '</div>' +
                    '<div class="quality-result-action">建议：' +
                        escapeHtml(suggestion) +
                    '</div>' +
                '</div>'
            );
            plainLines.push(
                (index + 1) + '. [' + documentName + '] ' + item,
                '依据：' + evidence,
                '建议：' + suggestion
            );
        });
        if (manualReview.length) {
            html.push(
                '<div class="quality-result-item info">' +
                    '<div class="quality-result-head">' +
                        '<span class="quality-badge">人工核对</span>' +
                        '<strong>AI无法可靠判定的项目</strong>' +
                    '</div>' +
                    '<div>' +
                        escapeHtml(manualReview.join('；')) +
                    '</div>' +
                '</div>'
            );
            plainLines.push(
                '人工核对：' + manualReview.join('；')
            );
        }
        if (!issues.length) {
            html.push(
                '<div class="quality-result-item warn">' +
                    '<div>AI未返回结构化问题项；仍需医师逐项人工复核。</div>' +
                '</div>'
            );
        }
        resultBox.innerHTML = html.join('');
        modal._qcAiPlainText = plainLines.join('\n');
        status.textContent =
            'AI复核完成：返回' + issues.length +
            '个问题项。结果仅供辅助，不代表病案通过。';
        status.className = 'quality-status quality-ai-status ok';
    }

    async function qcRunAiQualityControl(modal) {
        const identity = qcGuardModalPatientIdentity(modal);
        qcRequireSourceIdentity(identity);
        if (
            !modal.querySelector('.quality-ai-consent input').checked
        ) {
            throw new Error(
                '请先勾选本次DeepSeek发送确认；脚本会先尝试去除常见直接标识，但医学正文仍属于敏感信息'
            );
        }
        const settings = getDeepSeekPostalSettings();
        if (!suiteGlobalAiHasApiKey(settings.apiKey)) {
            throw new Error(
                '尚未配置当前AI服务所需API Key，请先在脚本设置或悬浮框管理器中配置'
            );
        }
        const sources = qcCollectSources(identity);
        if (!sources.entries.length) {
            throw new Error('请先提供至少一类独立质控资料');
        }
        const limits = {
            admission: 12000,
            progress: 20000,
            discharge: 12000,
            order: 14000
        };
        const documents = sources.entries.map(function (source) {
            return {
                type: source.type,
                label: source.label,
                text: qcAiExcerpt(
                    qcDeidentifyText(source.entry.text, identity),
                    limits[source.type] || 12000
                )
            };
        });
        const ruleConfig = qcLoadRuleConfig();
        const aiPromptConfig = qcLoadAiPromptConfig();
        const currentRuleSummary = qcAiRuleSummary(ruleConfig);
        const button = modal.querySelector('.quality-ai-scan');
        const status = modal.querySelector('.quality-ai-status');
        button.disabled = true;
        status.textContent =
            '正在调用DeepSeek进行语义复核，请勿关闭窗口……';
        status.className = 'quality-status quality-ai-status warn';
        qcSetSectionCollapsedByKey(modal, 'results', false, true);
        try {
            const content = await qcRequestDeepSeek(
                settings,
                [
                    {
                        role: 'system',
                        content: [
                            aiPromptConfig.prompt,
                            '【当前启用的质控规则与阈值】\n' +
                                JSON.stringify(currentRuleSummary),
                            QUALITY_CONTROL_AI_FIXED_SAFETY_PROMPT
                        ].join('\n')
                    },
                    {
                        role: 'user',
                        content: JSON.stringify({
                            note:
                                '仅依据documents审查；不得把未提供资料当作已发生事实。',
                            documents: documents
                        })
                    }
                ],
                {
                    json: true,
                    temperature: 0.1,
                    maxTokens: 4200
                }
            );
            qcRenderAiResults(
                modal,
                extractJsonFromAiText(content)
            );
            showStatus(
                'DeepSeek AI质控完成。请逐项回看原文，AI结论不能替代医师审核。',
                'success'
            );
        } catch (error) {
            status.textContent = 'AI质控失败：' + error.message;
            status.className = 'quality-status quality-ai-status error';
            throw error;
        } finally {
            button.disabled = false;
        }
    }

    /******************************************************************
     * v12.10.3 独立AI返修
     *
     * 基线只来自功能区一的四类独立资料槽。首程和普通病程从同一个
     * “病程记录”资料槽确定性分段；普通病程只额外读取资料槽中的
     * 入院/出院诊断作为诊断演变参考。结果只留在本地文本框。
     ******************************************************************/

    const QUALITY_CONTROL_REPAIR_FORMAT_STORAGE_KEYS = {
        admission: 'medicalInpatientAdmissionRecordAiFormatRulesV2',
        firstCourse: 'medicalInpatientFirstCourseFormatRulesV1',
        progress: 'medicalInpatientProgressFormatRulesV1',
        discharge: 'medicalInpatientDischargeRecordFormatRulesV1'
    };

    const QUALITY_CONTROL_REPAIR_DEFAULT_ADMISSION_FORMAT_RULES = {
        historyIndent: 2,
        examinationTitleIndent: 18,
        vitalSignsIndent: 10,
        examinationIndent: 2,
        specialtyIndent: 2,
        auxiliaryTitleIndent: 18,
        auxiliaryIndent: 2,
        initialDiagnosisIndent: 12,
        westernDiagnosisIndent: 17,
        westernContinuationIndent: 22,
        signatureIndent: 26,
        removeBlankLines: true,
        normalizeColons: true,
        normalizeSectionTitles: true
    };

    const QUALITY_CONTROL_REPAIR_DEFAULT_FIRST_FORMAT_RULES = {
        patientIndent: 2,
        initialDiagnosisIndent: 2,
        westernDiagnosisIndent: 7,
        westernContinuationIndent: 12,
        sectionNumberIndent: 2,
        signatureIndent: 26,
        planBlankLines: 1,
        removeBlankLines: true,
        normalizeWesternColon: true
    };

    const QUALITY_CONTROL_REPAIR_DEFAULT_PROGRESS_FORMAT_RULES = {
        bodyIndent: 2,
        signatureIndent: 26,
        removeBlankLines: true,
        dateHeaderPattern:
            '^20\\d{2}[-\\/.年]\\d{1,2}[-\\/.月]\\d{1,2}日?(?:\\s+\\d{1,2}:\\d{2}(?::\\d{2})?)?',
        recordTitlePattern:
            '(首次病程记录|主治医师查房记录|主任医师查房记录|病程记录)',
        standaloneRecordTitlePattern:
            '^(?:杨凡主治医师查房记录|徐敬才主任医师查房记录|主治医师查房记录|主任医师查房记录|首次病程记录|病程记录)$'
    };

    const QUALITY_CONTROL_REPAIR_DEFAULT_DISCHARGE_FORMAT_RULES = {
        sectionTitles: [
            '入院情况',
            '入院诊断',
            '诊疗经过',
            '出院诊断',
            '出院情况',
            '出院医嘱'
        ],
        sectionIndent: 2,
        numberedIndent: 2,
        signatureIndent: 26,
        removeBlankLines: true,
        normalizeSectionColon: true,
        numberedPattern: '^(\\d{1,2})\\s*([.、．。)）])\\s*'
    };

    function qcRepairDefinition(type) {
        return QUALITY_CONTROL_REPAIR_DEFINITIONS.find(
            function (definition) {
                return definition.type === type;
            }
        ) || null;
    }

    function qcRepairClampInteger(value, fallback, minimum, maximum) {
        const number = Number(value);
        if (!Number.isFinite(number)) return fallback;
        return Math.max(
            minimum,
            Math.min(maximum, Math.trunc(number))
        );
    }

    function qcRepairBoolean(value, fallback) {
        if (value === null || value === undefined) return fallback;
        return value !== false &&
            String(value).toLowerCase() !== 'false' &&
            String(value) !== '0';
    }

    function qcRepairValidRegex(value, fallback) {
        const pattern = String(value || '').trim();
        try {
            new RegExp(pattern);
            return pattern;
        } catch (error) {
            return fallback;
        }
    }

    function qcRepairLoadFormatRules(type, defaults, normalizer) {
        let saved = null;
        try {
            saved = JSON.parse(
                localStorage.getItem(
                    QUALITY_CONTROL_REPAIR_FORMAT_STORAGE_KEYS[type]
                ) || 'null'
            );
        } catch (error) {
            saved = null;
        }
        return normalizer(saved || qcCloneConfigValue(defaults));
    }

    function qcRepairNormalizeAdmissionRules(value) {
        const defaults = qcCloneConfigValue(
            QUALITY_CONTROL_REPAIR_DEFAULT_ADMISSION_FORMAT_RULES
        );
        const source = value && typeof value === 'object' ? value : {};
        const integerKeys = [
            'historyIndent',
            'examinationTitleIndent',
            'vitalSignsIndent',
            'examinationIndent',
            'specialtyIndent',
            'auxiliaryTitleIndent',
            'auxiliaryIndent',
            'initialDiagnosisIndent',
            'westernDiagnosisIndent',
            'westernContinuationIndent',
            'signatureIndent'
        ];
        const output = {};
        integerKeys.forEach(function (key) {
            output[key] = qcRepairClampInteger(
                source[key],
                defaults[key],
                0,
                key === 'signatureIndent' ? 80 : 60
            );
        });
        output.removeBlankLines = qcRepairBoolean(
            source.removeBlankLines,
            defaults.removeBlankLines
        );
        output.normalizeColons = qcRepairBoolean(
            source.normalizeColons,
            defaults.normalizeColons
        );
        output.normalizeSectionTitles = qcRepairBoolean(
            source.normalizeSectionTitles,
            defaults.normalizeSectionTitles
        );
        return output;
    }

    function qcRepairNormalizeFirstRules(value) {
        const defaults = qcCloneConfigValue(
            QUALITY_CONTROL_REPAIR_DEFAULT_FIRST_FORMAT_RULES
        );
        const source = value && typeof value === 'object' ? value : {};
        const output = {};
        [
            'patientIndent',
            'initialDiagnosisIndent',
            'westernDiagnosisIndent',
            'westernContinuationIndent',
            'sectionNumberIndent',
            'signatureIndent'
        ].forEach(function (key) {
            output[key] = qcRepairClampInteger(
                source[key],
                defaults[key],
                0,
                key === 'signatureIndent' ? 80 : 60
            );
        });
        output.planBlankLines = qcRepairClampInteger(
            source.planBlankLines,
            defaults.planBlankLines,
            0,
            5
        );
        output.removeBlankLines = qcRepairBoolean(
            source.removeBlankLines,
            defaults.removeBlankLines
        );
        output.normalizeWesternColon = qcRepairBoolean(
            source.normalizeWesternColon,
            defaults.normalizeWesternColon
        );
        return output;
    }

    function qcRepairNormalizeProgressRules(value) {
        const defaults = qcCloneConfigValue(
            QUALITY_CONTROL_REPAIR_DEFAULT_PROGRESS_FORMAT_RULES
        );
        const source = value && typeof value === 'object' ? value : {};
        return {
            bodyIndent: qcRepairClampInteger(
                source.bodyIndent,
                defaults.bodyIndent,
                0,
                60
            ),
            signatureIndent: qcRepairClampInteger(
                source.signatureIndent,
                defaults.signatureIndent,
                0,
                80
            ),
            removeBlankLines: qcRepairBoolean(
                source.removeBlankLines,
                defaults.removeBlankLines
            ),
            dateHeaderPattern: qcRepairValidRegex(
                source.dateHeaderPattern,
                defaults.dateHeaderPattern
            ),
            recordTitlePattern: qcRepairValidRegex(
                source.recordTitlePattern,
                defaults.recordTitlePattern
            ),
            standaloneRecordTitlePattern: qcRepairValidRegex(
                source.standaloneRecordTitlePattern,
                defaults.standaloneRecordTitlePattern
            )
        };
    }

    function qcRepairNormalizeDischargeRules(value) {
        const defaults = qcCloneConfigValue(
            QUALITY_CONTROL_REPAIR_DEFAULT_DISCHARGE_FORMAT_RULES
        );
        const source = value && typeof value === 'object' ? value : {};
        let sectionTitles = Array.isArray(source.sectionTitles)
            ? source.sectionTitles
            : String(source.sectionTitles || '').split(/\r?\n/);
        sectionTitles = sectionTitles.map(function (item) {
            return String(item || '').trim();
        }).filter(Boolean).filter(function (item, index, array) {
            return array.indexOf(item) === index;
        });
        if (!sectionTitles.length) {
            sectionTitles = defaults.sectionTitles.slice();
        }
        return {
            sectionTitles: sectionTitles,
            sectionIndent: qcRepairClampInteger(
                source.sectionIndent,
                defaults.sectionIndent,
                0,
                60
            ),
            numberedIndent: qcRepairClampInteger(
                source.numberedIndent,
                defaults.numberedIndent,
                0,
                60
            ),
            signatureIndent: qcRepairClampInteger(
                source.signatureIndent,
                defaults.signatureIndent,
                0,
                80
            ),
            removeBlankLines: qcRepairBoolean(
                source.removeBlankLines,
                defaults.removeBlankLines
            ),
            normalizeSectionColon: qcRepairBoolean(
                source.normalizeSectionColon,
                defaults.normalizeSectionColon
            ),
            numberedPattern: qcRepairValidRegex(
                source.numberedPattern,
                defaults.numberedPattern
            )
        };
    }

    function qcRepairCleanGeneratedText(value) {
        return String(value || '')
            .replace(/\r\n?/g, '\n')
            .replace(/^```(?:text|markdown|json)?\s*/i, '')
            .replace(/\s*```$/i, '')
            .replace(/^\s*(?:返修后(?:的)?(?:完整)?(?:病历|文书|正文)?|以下(?:为|是)返修后(?:的)?(?:完整)?(?:病历|文书|正文)?)\s*[：:]?\s*\n/i, '')
            .replace(/\*\*/g, '')
            .replace(/[ \t　]+$/gm, '')
            .replace(/^\n+|\n+$/g, '');
    }

    function qcRepairNormalizeAdmissionFormatting(value) {
        const rules = qcRepairLoadFormatRules(
            'admission',
            QUALITY_CONTROL_REPAIR_DEFAULT_ADMISSION_FORMAT_RULES,
            qcRepairNormalizeAdmissionRules
        );
        let text = qcRepairCleanGeneratedText(value);
        const signature = text.match(/(?:^|\n)[^\n]*医师签名\s*[：:]/);
        if (signature) {
            const start = signature.index +
                (signature[0].startsWith('\n') ? 1 : 0);
            const end = text.indexOf('\n', start);
            text = text.slice(0, end < 0 ? text.length : end);
        }
        let lines = text.split('\n').map(function (line) {
            return String(line || '').replace(/[ \t　]+$/g, '');
        });
        if (rules.removeBlankLines) {
            lines = lines.filter(function (line) {
                return String(line || '').trim() !== '';
            });
        }
        const indent = function (count) {
            return '　'.repeat(count);
        };
        let section = 'basic';
        let examinationBodyStarted = false;
        const output = [];
        lines.forEach(function (rawLine) {
            let line = String(rawLine || '').trim();
            if (!line) {
                if (!rules.removeBlankLines) output.push('');
                return;
            }
            if (rules.normalizeColons) {
                line = line.replace(
                    /^(姓名|出生地|性别|职业|年龄|入院日期|婚姻|记录日期|民族|病史陈述者|主诉|现病史|入院症见|既往史|个人史|月经史|婚育史|家族史|中医望闻切诊|专科查体|辅助检查|初步诊断|中医诊断|西医诊断|医师签名)\s*:/,
                    '$1：'
                );
            }
            if (/^体\s*格\s*检\s*查$/.test(line)) {
                section = 'examination';
                examinationBodyStarted = false;
                output.push(
                    indent(rules.examinationTitleIndent) +
                    (rules.normalizeSectionTitles
                        ? '体  格  检  查'
                        : line)
                );
                return;
            }
            if (/^辅\s*助\s*检\s*查$/.test(line)) {
                section = 'auxiliary';
                output.push(
                    indent(rules.auxiliaryTitleIndent) +
                    (rules.normalizeSectionTitles
                        ? '辅  助  检  查'
                        : line)
                );
                return;
            }
            if (/^初步诊断\s*[：:]/.test(line)) {
                section = 'diagnosis';
                output.push(indent(rules.initialDiagnosisIndent) + line);
                return;
            }
            if (/^医师签名\s*[：:]/.test(line)) {
                section = 'signature';
                output.push(
                    indent(rules.signatureIndent) +
                    line.replace(/^[ \t　]+/, '')
                );
                return;
            }
            if (
                /^(主诉|现病史|既往史|个人史|月经史|婚育史|家族史|中医望闻切诊)\s*[：:]/.test(
                    line
                )
            ) {
                section = 'history';
                output.push(indent(rules.historyIndent) + line);
                return;
            }
            if (section === 'examination') {
                if (/^[TＴ]\s*[：:]?\s*\d/i.test(line)) {
                    output.push(indent(rules.vitalSignsIndent) + line);
                    examinationBodyStarted = true;
                    return;
                }
                if (/^专科查体\s*[：:]/.test(line)) {
                    output.push(indent(rules.specialtyIndent) + line);
                    return;
                }
                output.push(
                    (examinationBodyStarted
                        ? indent(rules.examinationIndent)
                        : '') + line
                );
                examinationBodyStarted = true;
                return;
            }
            if (section === 'auxiliary') {
                output.push(indent(rules.auxiliaryIndent) + line);
                return;
            }
            if (section === 'diagnosis') {
                if (/^西医诊断\s*[：:]/.test(line)) {
                    output.push(
                        indent(rules.westernDiagnosisIndent) + line
                    );
                    return;
                }
                if (/^\d+[.、．]/.test(line)) {
                    output.push(
                        indent(rules.westernContinuationIndent) + line
                    );
                    return;
                }
            }
            output.push(line);
        });
        return output.join('\n').replace(/^\n+|\n+$/g, '');
    }

    function qcRepairNormalizeFirstFormatting(value) {
        const rules = qcRepairLoadFormatRules(
            'firstCourse',
            QUALITY_CONTROL_REPAIR_DEFAULT_FIRST_FORMAT_RULES,
            qcRepairNormalizeFirstRules
        );
        let lines = qcRepairCleanGeneratedText(value)
            .split('\n')
            .map(function (line) {
                return String(line || '').replace(/[ \t　]+$/g, '');
            });
        if (rules.removeBlankLines) {
            lines = lines.filter(function (line) {
                return String(line || '').trim() !== '';
            });
        }
        const indent = function (count) {
            return '　'.repeat(count);
        };
        const output = [];
        let section = '';
        lines.forEach(function (rawLine) {
            const line = String(rawLine || '')
                .replace(/^[ \t　]+/, '')
                .replace(/[ \t　]+$/g, '');
            if (!line) {
                if (!rules.removeBlankLines) output.push('');
                return;
            }
            if (
                /^20\d{2}[-\/.年]\d{1,2}[-\/.月]\d{1,2}日?(?:\s+\d{1,2}:\d{2}(?::\d{2})?)?/.test(
                    line
                ) ||
                /^首次病程记录$/.test(line)
            ) {
                output.push(line);
                return;
            }
            if (/^患者/.test(line)) {
                output.push(indent(rules.patientIndent) + line);
                return;
            }
            if (/^(?:病历|病例)特点\s*[：:]?/.test(line)) {
                section = 'features';
                output.push(line);
                return;
            }
            if (/^初步诊断\s*[：:]?/.test(line)) {
                section = 'initial-diagnosis';
                output.push(indent(rules.initialDiagnosisIndent) + line);
                return;
            }
            if (/^诊断依据\s*[：:]?/.test(line)) {
                section = 'diagnosis-basis';
                output.push(line);
                return;
            }
            if (/^鉴别诊断\s*[：:]?/.test(line)) {
                section = 'differential';
                output.push(line);
                return;
            }
            if (/^诊疗计划\s*[：:]?/.test(line)) {
                section = 'plan';
                output.push(line);
                for (let index = 0; index < rules.planBlankLines; index++) {
                    output.push('');
                }
                return;
            }
            if (/^医师签名\s*[：:]?/.test(line)) {
                section = 'signature';
                output.push(indent(rules.signatureIndent) + line);
                return;
            }
            if (section === 'features' && /^[1-9][.、．]/.test(line)) {
                output.push(indent(rules.sectionNumberIndent) + line);
                return;
            }
            if (section === 'initial-diagnosis') {
                if (/^中医诊断\s*[：:]?/.test(line)) {
                    output.push(indent(rules.initialDiagnosisIndent) + line);
                    return;
                }
                if (/^西医诊断\s*[：:]?/.test(line)) {
                    const body = line.replace(
                        /^西医诊断\s*[：:]?\s*/,
                        ''
                    );
                    output.push(
                        indent(rules.westernDiagnosisIndent) +
                        (rules.normalizeWesternColon
                            ? '西医诊断：'
                            : line.includes(':')
                                ? '西医诊断:'
                                : '西医诊断：') +
                        body
                    );
                    return;
                }
                if (/^\d+[.、．]/.test(line)) {
                    output.push(
                        indent(rules.westernContinuationIndent) + line
                    );
                    return;
                }
            }
            if (
                ['diagnosis-basis', 'differential', 'plan'].includes(section) &&
                /^\d+[.、．]/.test(line)
            ) {
                output.push(indent(rules.sectionNumberIndent) + line);
                return;
            }
            output.push(line);
        });
        return output.join('\n').replace(/^\n+|\n+$/g, '');
    }

    function qcRepairNormalizeProgressFormatting(value) {
        const rules = qcRepairLoadFormatRules(
            'progress',
            QUALITY_CONTROL_REPAIR_DEFAULT_PROGRESS_FORMAT_RULES,
            qcRepairNormalizeProgressRules
        );
        let lines = qcRepairCleanGeneratedText(value)
            .split('\n')
            .map(function (line) {
                return String(line || '').replace(/[ \t　]+$/g, '');
            });
        if (rules.removeBlankLines) {
            lines = lines.filter(function (line) {
                return String(line || '').trim() !== '';
            });
        }
        const datePattern = new RegExp(rules.dateHeaderPattern);
        const titlePattern = new RegExp(rules.recordTitlePattern);
        const standalonePattern = new RegExp(
            rules.standaloneRecordTitlePattern
        );
        const bodyIndent = '　'.repeat(rules.bodyIndent);
        const signatureIndent = '　'.repeat(rules.signatureIndent);
        const output = [];
        let waitingForBody = false;
        let waitingForTitle = false;
        lines.forEach(function (rawLine) {
            const original = String(rawLine || '');
            const line = original.trim();
            if (!line) {
                if (!rules.removeBlankLines) output.push('');
                return;
            }
            if (/医师签名\s*[：:]?/.test(line)) {
                output.push(
                    signatureIndent + line.replace(/^[ \t　]+/, '')
                );
                waitingForBody = false;
                waitingForTitle = false;
                return;
            }
            if (datePattern.test(line)) {
                output.push(line);
                waitingForBody = titlePattern.test(line);
                waitingForTitle = !waitingForBody;
                return;
            }
            if (waitingForTitle && standalonePattern.test(line)) {
                output.push(line);
                waitingForTitle = false;
                waitingForBody = true;
                return;
            }
            if (waitingForBody) {
                output.push(
                    bodyIndent + line.replace(/^[ \t　]+/, '')
                );
                waitingForBody = false;
                waitingForTitle = false;
                return;
            }
            output.push(original);
        });
        return output.join('\n').replace(/^\n+|\n+$/g, '');
    }

    function qcRepairNormalizeDischargeFormatting(value) {
        const rules = qcRepairLoadFormatRules(
            'discharge',
            QUALITY_CONTROL_REPAIR_DEFAULT_DISCHARGE_FORMAT_RULES,
            qcRepairNormalizeDischargeRules
        );
        let text = qcRepairCleanGeneratedText(value);
        if (rules.removeBlankLines) {
            text = text.split('\n').filter(function (line) {
                return String(line || '').replace(/[ \t　]/g, '') !== '';
            }).join('\n');
        }
        const escapePattern = function (item) {
            return String(item || '').replace(
                /[.*+?^${}()|[\]\\]/g,
                '\\$&'
            );
        };
        const sectionSource = rules.sectionTitles.map(escapePattern).join('|');
        const sectionPattern = sectionSource
            ? new RegExp('^(' + sectionSource + ')\\s*([：:])')
            : null;
        const numberedPattern = new RegExp(rules.numberedPattern);
        const sectionIndent = '　'.repeat(rules.sectionIndent);
        const numberedIndent = '　'.repeat(rules.numberedIndent);
        const signatureIndent = '　'.repeat(rules.signatureIndent);
        return text.split('\n').map(function (rawLine) {
            const original = String(rawLine || '');
            const clean = original.replace(/^[ \t　]+/, '');
            const signature = clean.match(/^医师签名\s*[：:]\s*(.*)$/);
            if (signature) {
                return signatureIndent + '医师签名：' +
                    String(signature[1] || '').trim();
            }
            if (sectionPattern) {
                const match = clean.match(sectionPattern);
                if (match) {
                    return sectionIndent + match[1] +
                        (rules.normalizeSectionColon ? '：' : match[2]) +
                        clean.slice(match[0].length);
                }
            }
            if (numberedPattern.test(clean)) {
                return numberedIndent + clean;
            }
            return original;
        }).join('\n').replace(/^\n+|\n+$/g, '');
    }

    function qcRepairNormalizeFormatting(type, value) {
        if (type === 'admission') {
            return qcRepairNormalizeAdmissionFormatting(value);
        }
        if (type === 'firstCourse') {
            return qcRepairNormalizeFirstFormatting(value);
        }
        if (type === 'progress') {
            return qcRepairNormalizeProgressFormatting(value);
        }
        if (type === 'discharge') {
            return qcRepairNormalizeDischargeFormatting(value);
        }
        throw new Error('未知返修版块');
    }

    function qcRepairProgressDateLine(value) {
        return /^20\d{2}[-\/.年]\d{1,2}[-\/.月]\d{1,2}日?(?:\s+\d{1,2}:\d{2}(?::\d{2})?)?/.test(
            String(value || '').trim()
        );
    }

    function qcRepairProgressTitle(value) {
        const line = String(value || '').trim();
        const match = line.match(
            /(首次病程记录|(?:[\u3400-\u9fff·]{0,16})?医师查房记录|(?:日常|一般|普通)?病程记录)\s*$/
        );
        return match ? match[1] : '';
    }

    function qcRepairSplitProgressSource(value) {
        const text = String(value || '').replace(/\r\n?/g, '\n').trim();
        const lines = text.split('\n');
        const starts = [];
        lines.forEach(function (line, index) {
            const title = qcRepairProgressTitle(line);
            if (!title) return;
            const inlineDate = qcRepairProgressDateLine(line);
            const previousDate = index > 0 &&
                qcRepairProgressDateLine(lines[index - 1]);
            if (!inlineDate && !previousDate && title !== '首次病程记录') {
                return;
            }
            const start = previousDate ? index - 1 : index;
            if (
                starts.length &&
                starts[starts.length - 1].start === start
            ) return;
            starts.push({
                start: start,
                title: title,
                firstCourse: title === '首次病程记录'
            });
        });
        const segments = starts.map(function (item, index) {
            const end = index + 1 < starts.length
                ? starts[index + 1].start
                : lines.length;
            return {
                firstCourse: item.firstCourse,
                title: item.title,
                text: lines.slice(item.start, end).join('\n').trim()
            };
        }).filter(function (item) {
            return item.text.length >= 20;
        });
        let firstCourse = segments.filter(function (item) {
            return item.firstCourse;
        }).sort(function (first, second) {
            return second.text.length - first.text.length;
        })[0];
        let progressSegments = segments.filter(function (item) {
            return !item.firstCourse;
        });
        if (!firstCourse && /首次病程记录/.test(text)) {
            const index = text.indexOf('首次病程记录');
            const lineStart = text.lastIndexOf('\n', index);
            firstCourse = {
                firstCourse: true,
                title: '首次病程记录',
                text: text.slice(lineStart < 0 ? 0 : lineStart + 1).trim()
            };
        }
        if (
            !progressSegments.length &&
            !/首次病程记录/.test(text) &&
            /病程记录|医师查房记录|查房记录/.test(text)
        ) {
            progressSegments = [{
                firstCourse: false,
                title: '病程记录',
                text: text
            }];
        }
        return {
            firstCourse: firstCourse ? firstCourse.text : '',
            progress: progressSegments.map(function (item) {
                return item.text;
            }).join('\n\n').trim(),
            segmentCount: segments.length
        };
    }

    function qcRepairExtractDiagnosisReference(value, type) {
        const text = String(value || '').replace(/\r\n?/g, '\n');
        const startPattern = type === 'admission'
            ? /(?:^|\n)[ \t　]*(?:初步诊断|入院诊断)\s*[：:]/
            : /(?:^|\n)[ \t　]*出院诊断\s*[：:]/;
        const match = text.match(startPattern);
        if (!match) return '';
        const start = match.index + (match[0].startsWith('\n') ? 1 : 0);
        const tail = text.slice(start);
        const endPattern = type === 'admission'
            ? /\n[ \t　]*(?:诊断依据|鉴别诊断|诊疗计划|医师签名)\s*[：:]?/
            : /\n[ \t　]*(?:出院情况|出院医嘱|医师签名)\s*[：:]?/;
        const end = tail.search(endPattern);
        return tail.slice(0, end < 0 ? 6000 : Math.min(end, 6000)).trim();
    }

    function qcRepairResolveMaterials(identity, type) {
        const definition = qcRepairDefinition(type);
        if (!definition) throw new Error('未知返修版块');
        const bundle = qcLoadSourceBundle(identity);
        const sources = bundle.sources || {};
        let target = '';
        const references = [];
        if (type === 'admission') {
            target = String(sources.admission && sources.admission.text || '')
                .trim();
            if (!target) {
                throw new Error(
                    '功能区一尚未保存“入院记录”基线资料'
                );
            }
        } else if (type === 'discharge') {
            target = String(sources.discharge && sources.discharge.text || '')
                .trim();
            if (!target) {
                throw new Error(
                    '功能区一尚未保存“出院记录”基线资料'
                );
            }
        } else {
            const progressText = String(
                sources.progress && sources.progress.text || ''
            ).trim();
            if (!progressText) {
                throw new Error(
                    '功能区一尚未保存“病程记录”基线资料'
                );
            }
            const split = qcRepairSplitProgressSource(progressText);
            if (type === 'firstCourse') {
                target = split.firstCourse;
                if (!target) {
                    throw new Error(
                        '病程记录资料槽中未识别到“首次病程记录”；请在功能区一核对或手工整理资料'
                    );
                }
            } else {
                target = split.progress;
                if (!target) {
                    throw new Error(
                        '病程记录资料槽中未识别到首次病程以外的普通病程或查房记录'
                    );
                }
                const admissionReference = qcRepairExtractDiagnosisReference(
                    sources.admission && sources.admission.text,
                    'admission'
                );
                const dischargeReference = qcRepairExtractDiagnosisReference(
                    sources.discharge && sources.discharge.text,
                    'discharge'
                );
                if (admissionReference) {
                    references.push({
                        label: '入院诊断参考',
                        text: admissionReference
                    });
                }
                if (dischargeReference) {
                    references.push({
                        label: '出院诊断参考',
                        text: dischargeReference
                    });
                }
            }
        }
        const combinedLength = target.length + references.reduce(
            function (total, item) {
                return total + String(item.text || '').length;
            },
            0
        );
        if (combinedLength > QUALITY_CONTROL_REPAIR_MAX_INPUT_TEXT) {
            throw new Error(
                '本版块返修资料共' + combinedLength +
                '字符，超过18万字符安全上限；请在功能区一手工缩小为本次需要返修的文书范围'
            );
        }
        return {
            target: target,
            references: references,
            sourceLabel: definition.sourceLabel
        };
    }

    function qcCreateRepairMasker(identity) {
        let sequence = 0;
        const items = [];
        const valueMap = {};
        function tokenFor(value) {
            const source = String(value || '');
            if (!source) return source;
            if (valueMap[source]) return valueMap[source];
            sequence += 1;
            const token = '[[QC_MASK_' +
                String(sequence).padStart(4, '0') + ']]';
            valueMap[source] = token;
            items.push({ token: token, value: source });
            return token;
        }
        function mask(value) {
            let text = String(value || '');
            text = text.replace(
                /((?:现住址|户口地址|家庭住址|联系地址|地址)\s*[：:])([^\n\r]{1,120})/g,
                function (whole, prefix, content) {
                    return prefix + tokenFor(content);
                }
            );
            text = text.replace(
                /\b\d{17}[\dXx]\b/g,
                function (item) {
                    return tokenFor(item);
                }
            );
            text = text.replace(/\b1\d{10}\b/g, function (item) {
                return tokenFor(item);
            });
            [identity && identity.name, identity && identity.inpatientNo]
                .map(function (item) {
                    return String(item || '').trim();
                })
                .filter(Boolean)
                .sort(function (first, second) {
                    return second.length - first.length;
                })
                .forEach(function (item) {
                    text = text.replace(
                        new RegExp(qcEscapeRegExp(item), 'g'),
                        tokenFor(item)
                    );
                });
            return text;
        }
        function restore(value) {
            let text = String(value || '');
            items.forEach(function (item) {
                text = text.split(item.token).join(item.value);
            });
            if (/\[\[\s*QC_MASK_/i.test(text)) {
                throw new Error(
                    'AI改变了脱敏占位符，无法安全恢复患者原始信息；结果未写入返修框'
                );
            }
            return text;
        }
        return { mask: mask, restore: restore };
    }

    function qcRepairSection(value, startPattern, endPattern) {
        const text = String(value || '').replace(/\r\n?/g, '\n');
        const match = text.match(startPattern);
        if (!match) return '';
        const start = match.index + (match[0].startsWith('\n') ? 1 : 0);
        const tail = text.slice(start);
        const end = tail.slice(match[0].length).search(endPattern);
        if (end < 0) return tail;
        return tail.slice(0, match[0].length + end);
    }

    function qcRepairValidateResult(type, value) {
        const text = String(value || '').trim();
        const warnings = [];
        if (text.length < 40) {
            throw new Error('AI返修结果过短，未覆盖完整目标文书');
        }
        if (type === 'admission') {
            if (
                !/现病史\s*[：:]/.test(text) ||
                !/既往史\s*[：:]/.test(text) ||
                !/初步诊断\s*[：:]/.test(text)
            ) {
                throw new Error(
                    'AI结果缺少现病史、既往史或初步诊断，已阻止覆盖结果框'
                );
            }
        }
        if (type === 'firstCourse') {
            if (
                !/首次病程记录/.test(text) ||
                !/(?:病历|病例)特点\s*[：:]?/.test(text) ||
                !/诊断依据\s*[：:]?/.test(text)
            ) {
                throw new Error(
                    'AI结果不是结构完整的首次病程记录，已阻止覆盖结果框'
                );
            }
            const features = qcRepairSection(
                text,
                /(?:^|\n)[ \t　]*(?:病历|病例)特点\s*[：:]?/,
                /\n[ \t　]*(?:初步诊断|诊断依据|鉴别诊断|诊疗计划)\s*[：:]?/
            );
            const basis = qcRepairSection(
                text,
                /(?:^|\n)[ \t　]*诊断依据\s*[：:]?/,
                /\n[ \t　]*(?:鉴别诊断|诊疗计划|医师签名)\s*[：:]?/
            );
            if (/(?:^|\n)[ \t　]*(?:\d+[.、．]\s*)?主诉\s*[：:]/.test(features)) {
                warnings.push('病历特点中仍疑似存在“主诉”条目');
            }
            if (/(?:^|\n)[ \t　]*(?:\d+[.、．]\s*)?现病史\s*[：:]/.test(basis)) {
                warnings.push('诊断依据中仍疑似存在“现病史”条目');
            }
        }
        if (type === 'progress') {
            if (!/病程记录|医师查房记录|查房记录/.test(text)) {
                throw new Error(
                    'AI结果未识别到普通病程或查房记录标题，已阻止覆盖结果框'
                );
            }
            if (/首次病程记录/.test(text)) {
                throw new Error(
                    '普通病程返修结果混入首次病程记录，已阻止覆盖结果框'
                );
            }
        }
        if (type === 'discharge') {
            if (
                !/入院情况\s*[：:]/.test(text) ||
                !/出院诊断\s*[：:]/.test(text)
            ) {
                throw new Error(
                    'AI结果缺少入院情况或出院诊断，已阻止覆盖结果框'
                );
            }
            const admissionSituation = qcRepairSection(
                text,
                /(?:^|\n)[ \t　]*入院情况\s*[：:]/,
                /\n[ \t　]*(?:入院诊断|诊疗经过|住院经过|出院诊断|出院情况|出院医嘱)\s*[：:]/
            );
            if (
                /辅助检查|血常规|尿常规|生化|CT|MRI|MR检查|X线|彩超|超声|心电图|检查提示|检查示|检验示|化验示/i.test(
                    admissionSituation
                )
            ) {
                warnings.push('入院情况段落仍疑似包含辅助检查内容');
            }
        }
        return warnings;
    }

    function qcRepairReadPromptEditors(modal) {
        const config = qcDefaultRepairPromptConfig();
        config.customized = true;
        QUALITY_CONTROL_REPAIR_DEFINITIONS.forEach(
            function (definition) {
                const editor = modal.querySelector(
                    '.quality-repair-card[data-repair-type="' +
                        definition.type +
                    '"] .quality-repair-prompt'
                );
                const prompt = String(editor && editor.value || '').trim();
                if (prompt.length < 20) {
                    throw new Error(
                        definition.label + '返修提示词过短，请至少填写20个字符'
                    );
                }
                if (prompt.length > 20000) {
                    throw new Error(
                        definition.label + '返修提示词不能超过20000字'
                    );
                }
                config.prompts[definition.type] = prompt;
            }
        );
        return config;
    }

    function qcRepairPopulatePromptEditors(modal, configValue) {
        const config = qcNormalizeRepairPromptConfig(
            configValue || qcLoadRepairPromptConfig()
        );
        QUALITY_CONTROL_REPAIR_DEFINITIONS.forEach(
            function (definition) {
                const editor = modal.querySelector(
                    '.quality-repair-card[data-repair-type="' +
                        definition.type +
                    '"] .quality-repair-prompt'
                );
                if (editor) editor.value = config.prompts[definition.type];
            }
        );
        const status = modal.querySelector(
            '.quality-repair-config-status'
        );
        if (status) {
            status.textContent =
                '返修提示词' +
                (config.customized ? '已自定义' : '使用脚本默认值') +
                (config.updatedAt ? '；保存于' + config.updatedAt : '') +
                '。格式规范化会读取住院信息脚本同名规则，未配置时使用一致的内置默认值。';
            status.className =
                'quality-status quality-repair-config-status ok';
        }
        modal._qcRepairPromptConfig = config;
    }

    function qcRepairSetBusy(modal, busy) {
        modal._qcRepairBusy = Boolean(busy);
        modal.querySelectorAll(
            '.quality-repair-run-all,[data-qc-repair-action="run"],.quality-save-repair-prompts,.quality-restore-repair-prompts,.quality-patient-lock-toggle,.quality-detect-patient,.quality-patient-name,.quality-patient-no,.quality-source-actions button'
        ).forEach(function (button) {
            button.disabled = Boolean(busy);
        });
    }

    function qcRepairResultStore() {
        const stored =
            patientLargeCacheReadStore(
                QUALITY_CONTROL_REPAIR_RESULT_STORAGE_KEY
            );

        return stored &&
            typeof stored === 'object' &&
            !Array.isArray(stored)
                ? stored
                : {};
    }

    function qcRepairNormalizeStoredResult(value) {
        const source = value && typeof value === 'object' ? value : {};
        const text = String(source.text || '').slice(
            0,
            QUALITY_CONTROL_REPAIR_RESULT_MAX_TEXT
        );
        const rawText = String(source.rawText || '').slice(
            0,
            QUALITY_CONTROL_REPAIR_RESULT_MAX_TEXT
        );
        return {
            text: text,
            rawText: rawText || (source.rawMatchesText ? text : ''),
            stale: Boolean(source.stale),
            statusText: String(source.statusText || ''),
            statusTone: /^(?:ok|warn|error)$/.test(
                String(source.statusTone || '')
            )
                ? String(source.statusTone)
                : 'warn',
            generatedAt: String(source.generatedAt || ''),
            updatedAt: String(source.updatedAt || '')
        };
    }

    function qcRepairLoadPatientResults(identity) {
        const key = qcIdentityKey(identity);
        const stored = key ? qcRepairResultStore()[key] : null;
        const results = {};
        QUALITY_CONTROL_REPAIR_DEFINITIONS.forEach(
            function (definition) {
                results[definition.type] = qcRepairNormalizeStoredResult(
                    stored && stored.results &&
                    stored.results[definition.type]
                );
            }
        );
        return {
            schemaVersion: QUALITY_CONTROL_REPAIR_RESULT_SCHEMA_VERSION,
            identity: Object.assign(
                {},
                stored && stored.identity || {},
                identity || {}
            ),
            results: results,
            updatedAt: String(stored && stored.updatedAt || '')
        };
    }

    function qcRepairStatusTone(status) {
        if (status && status.classList.contains('error')) return 'error';
        if (status && status.classList.contains('ok')) return 'ok';
        return 'warn';
    }

    function qcRepairSetResultMeta(modal, type, value) {
        modal._qcRepairResultMeta = modal._qcRepairResultMeta || {};
        modal._qcRepairResultMeta[type] = Object.assign(
            {},
            modal._qcRepairResultMeta[type] || {},
            value || {}
        );
    }

    function qcRepairCollectModalResults(modal) {
        const results = {};
        let hasContent = false;
        modal._qcRepairRawResults = modal._qcRepairRawResults || {};
        modal._qcRepairResultMeta = modal._qcRepairResultMeta || {};
        QUALITY_CONTROL_REPAIR_DEFINITIONS.forEach(
            function (definition) {
                const card = modal.querySelector(
                    '.quality-repair-card[data-repair-type="' +
                        definition.type + '"]'
                );
                if (!card) return;
                const result = card.querySelector('.quality-repair-result');
                const status = card.querySelector('.quality-repair-status');
                const text = String(result && result.value || '');
                const rawText = String(
                    modal._qcRepairRawResults[definition.type] || ''
                );
                if (
                    text.length > QUALITY_CONTROL_REPAIR_RESULT_MAX_TEXT ||
                    rawText.length > QUALITY_CONTROL_REPAIR_RESULT_MAX_TEXT
                ) {
                    throw new Error(
                        definition.label +
                        '返修文本超过18万字，无法安全保存'
                    );
                }
                const meta = modal._qcRepairResultMeta[definition.type] || {};
                const updatedAt = new Date().toLocaleString();
                results[definition.type] = {
                    text: text,
                    rawText:
                        rawText && rawText !== text ? rawText : '',
                    rawMatchesText:
                        Boolean(rawText) && rawText === text,
                    stale: Boolean(meta.stale),
                    statusText: String(
                        status && status.textContent || meta.statusText || ''
                    ),
                    statusTone: qcRepairStatusTone(status),
                    generatedAt: String(meta.generatedAt || ''),
                    updatedAt: updatedAt
                };
                if (text || rawText) hasContent = true;
            }
        );
        return { results: results, hasContent: hasContent };
    }

    function qcRepairSavePatientResults(modal, identity) {
        if (!modal) return null;
        const collected = qcRepairCollectModalResults(modal);
        const key = qcIdentityKey(identity);
        if (!key) {
            if (collected.hasContent) {
                throw new Error(
                    '返修结果未能保存：请先填写患者姓名或住院号'
                );
            }
            return null;
        }
        const store = qcRepairResultStore();
        if (collected.hasContent) {
            store[key] = {
                schemaVersion:
                    QUALITY_CONTROL_REPAIR_RESULT_SCHEMA_VERSION,
                identity: Object.assign({}, identity || {}),
                results: collected.results,
                updatedAt: new Date().toLocaleString()
            };
        } else {
            delete store[key];
        }
        try {
            patientLargeCacheWriteStore(
                QUALITY_CONTROL_REPAIR_RESULT_STORAGE_KEY,
                store
            );
        } catch (error) {
            throw new Error(
                '返修结果保存失败：' +
                String(
                    error &&
                    error.message ||
                    error
                )
            );
        }
        modal._qcRepairSavedIdentityKey = key;
        return store[key] || null;
    }

    function qcRepairScheduleResultSave(modal, identity) {
        if (!modal) return;
        if (modal._qcRepairSaveTimer) {
            clearTimeout(modal._qcRepairSaveTimer);
        }
        const targetIdentity = Object.assign(
            {},
            identity || modal._qcIdentity || qcModalIdentity(modal)
        );
        modal._qcRepairSaveTimer = setTimeout(function () {
            modal._qcRepairSaveTimer = null;
            try {
                qcRepairSavePatientResults(modal, targetIdentity);
            } catch (error) {
                QUALITY_CONTROL_REPAIR_DEFINITIONS.forEach(
                    function (definition) {
                        const card = modal.querySelector(
                            '.quality-repair-card[data-repair-type="' +
                                definition.type + '"]'
                        );
                        if (!card) return;
                        const result = card.querySelector(
                            '.quality-repair-result'
                        );
                        if (!String(result && result.value || '').trim()) {
                            return;
                        }
                        const status = card.querySelector(
                            '.quality-repair-status'
                        );
                        status.textContent = error.message;
                        status.className =
                            'quality-status quality-repair-status error';
                    }
                );
                showStatus(error.message, 'error');
            }
        }, 350);
    }

    function qcRepairFlushResultSave(modal, identity) {
        if (!modal) return null;
        if (modal._qcRepairSaveTimer) {
            clearTimeout(modal._qcRepairSaveTimer);
            modal._qcRepairSaveTimer = null;
        }
        return qcRepairSavePatientResults(
            modal,
            identity || modal._qcIdentity || qcModalIdentity(modal)
        );
    }

    function qcRepairPopulatePatientResults(modal, identity) {
        if (!modal) return;
        const bundle = qcRepairLoadPatientResults(identity);
        modal._qcRepairRawResults = {};
        modal._qcRepairResultMeta = {};
        QUALITY_CONTROL_REPAIR_DEFINITIONS.forEach(
            function (definition) {
                const card = modal.querySelector(
                    '.quality-repair-card[data-repair-type="' +
                        definition.type + '"]'
                );
                if (!card) return;
                const saved = bundle.results[definition.type];
                const result = card.querySelector('.quality-repair-result');
                const status = card.querySelector('.quality-repair-status');
                result.value = saved.text;
                if (saved.rawText) {
                    modal._qcRepairRawResults[definition.type] =
                        saved.rawText;
                }
                qcRepairSetResultMeta(modal, definition.type, {
                    stale: saved.stale,
                    generatedAt: saved.generatedAt,
                    updatedAt: saved.updatedAt,
                    statusText: saved.statusText,
                    statusTone: saved.statusTone
                });
                if (!saved.text) {
                    status.textContent = '尚未执行AI返修。';
                    status.className =
                        'quality-status quality-repair-status warn';
                    return;
                }
                status.textContent = saved.stale
                    ? '已恢复保留的返修文本；功能区一基线或提示词曾变更，当前结果仅供对照。'
                    : '已恢复' +
                        (saved.updatedAt ? '保存于' + saved.updatedAt + '的' : '保留的') +
                        '返修文本；可继续编辑、规范化或复制。';
                status.className =
                    'quality-status quality-repair-status ' +
                    (saved.stale ? 'warn' : saved.statusTone);
            }
        );
        modal._qcRepairSavedIdentityKey = qcIdentityKey(identity);
    }

    function qcRepairMarkResultsStale(modal, message, clear) {
        if (!modal) return;
        modal._qcRepairRawResults = modal._qcRepairRawResults || {};
        QUALITY_CONTROL_REPAIR_DEFINITIONS.forEach(
            function (definition) {
                const card = modal.querySelector(
                    '.quality-repair-card[data-repair-type="' +
                        definition.type + '"]'
                );
                if (!card) return;
                const status = card.querySelector('.quality-repair-status');
                const result = card.querySelector('.quality-repair-result');
                if (clear) {
                    roundBookSetMarkdownResult(result, '');
                    delete modal._qcRepairRawResults[definition.type];
                    qcRepairSetResultMeta(modal, definition.type, {
                        stale: false,
                        generatedAt: '',
                        updatedAt: ''
                    });
                    status.textContent = '尚未执行AI返修。';
                } else if (String(result.value || '').trim()) {
                    qcRepairSetResultMeta(modal, definition.type, {
                        stale: true,
                        updatedAt: new Date().toLocaleString()
                    });
                    status.textContent = message ||
                        '功能区一基线已变更；当前结果仅供对照，请重新返修。';
                }
                status.className =
                    'quality-status quality-repair-status warn';
            }
        );
        qcRepairScheduleResultSave(
            modal,
            modal._qcIdentity || qcModalIdentity(modal)
        );
    }

    async function qcRepairPerform(modal, type) {
        const definition = qcRepairDefinition(type);
        if (!definition) throw new Error('未知返修版块');
        const identity = qcGuardModalPatientIdentity(modal);
        qcRequireSourceIdentity(identity);
        if (
            !modal.querySelector('.quality-repair-consent input').checked
        ) {
            throw new Error(
                '请先勾选AI返修区的本次DeepSeek发送确认'
            );
        }
        const settings = getDeepSeekPostalSettings();
        if (!suiteGlobalAiHasApiKey(settings.apiKey)) {
            throw new Error(
                '尚未配置当前AI服务所需API Key，请先在脚本设置或悬浮框管理器中配置'
            );
        }
        const promptConfig = qcRepairReadPromptEditors(modal);
        const materials = qcRepairResolveMaterials(identity, type);
        const masker = qcCreateRepairMasker(identity);
        const maskedTarget = masker.mask(materials.target);
        const maskedReferences = materials.references.map(
            function (item) {
                return {
                    label: item.label,
                    text: masker.mask(item.text)
                };
            }
        );
        const card = modal.querySelector(
            '.quality-repair-card[data-repair-type="' + type + '"]'
        );
        const status = card.querySelector('.quality-repair-status');
        status.textContent =
            '正在调用DeepSeek返修“' + definition.label +
            '”，基线仅来自' + materials.sourceLabel + '……';
        status.className = 'quality-status quality-repair-status warn';
        const content = await qcRequestDeepSeek(
            settings,
            [
                {
                    role: 'system',
                    content: [
                        promptConfig.prompts[type],
                        QUALITY_CONTROL_REPAIR_FIXED_SAFETY_PROMPT
                    ].join('\n\n')
                },
                {
                    role: 'user',
                    content: JSON.stringify({
                        task: 'repair-complete-medical-document',
                        documentType: definition.label,
                        customRepairPrompt:
                            promptConfig.prompts[type],
                        targetDocumentText: maskedTarget,
                        referenceDocuments: maskedReferences
                    })
                }
            ],
            {
                json: false,
                temperature: 0.05,
                maxTokens: definition.maxTokens
            }
        );
        let result = qcRepairCleanGeneratedText(content);
        result = masker.restore(result);
        const warnings = qcRepairValidateResult(type, result);
        modal._qcRepairRawResults = modal._qcRepairRawResults || {};
        modal._qcRepairRawResults[type] = result;
        card.querySelector('.quality-repair-result').value = result;
        status.textContent = warnings.length
            ? 'AI返修完成，但需优先人工核对：' + warnings.join('；') + '。'
            : 'AI返修完成；尚未格式规范化，也未写入HIS。';
        status.className =
            'quality-status quality-repair-status ' +
            (warnings.length ? 'warn' : 'ok');
        const generatedAt = new Date().toLocaleString();
        qcRepairSetResultMeta(modal, type, {
            stale: false,
            generatedAt: generatedAt,
            updatedAt: generatedAt,
            statusText: status.textContent,
            statusTone: warnings.length ? 'warn' : 'ok'
        });
        qcRepairFlushResultSave(modal, identity);
        return { type: type, warnings: warnings };
    }

    async function qcRepairRunOne(modal, type) {
        if (modal._qcRepairBusy) {
            throw new Error('已有AI返修任务正在执行');
        }
        qcSetSectionCollapsedByKey(modal, 'repair', false, true);
        qcRepairSetBusy(modal, true);
        try {
            const result = await qcRepairPerform(modal, type);
            showStatus(
                qcRepairDefinition(type).label +
                'AI返修完成。请先人工核对，再按需格式规范化和复制。',
                result.warnings.length ? 'error' : 'success'
            );
        } finally {
            qcRepairSetBusy(modal, false);
        }
    }

    async function qcRepairRunAll(modal) {
        if (modal._qcRepairBusy) {
            throw new Error('已有AI返修任务正在执行');
        }
        if (!modal.querySelector('.quality-repair-consent input').checked) {
            throw new Error(
                '请先勾选AI返修区的本次DeepSeek发送确认'
            );
        }
        qcSetSectionCollapsedByKey(modal, 'repair', false, true);
        qcRepairSetBusy(modal, true);
        const succeeded = [];
        const failed = [];
        try {
            for (const definition of QUALITY_CONTROL_REPAIR_DEFINITIONS) {
                try {
                    const result = await qcRepairPerform(
                        modal,
                        definition.type
                    );
                    succeeded.push(
                        definition.label +
                        (result.warnings.length ? '（有核对提醒）' : '')
                    );
                } catch (error) {
                    failed.push(
                        definition.label + '：' + error.message
                    );
                    const card = modal.querySelector(
                        '.quality-repair-card[data-repair-type="' +
                            definition.type + '"]'
                    );
                    const status = card.querySelector(
                        '.quality-repair-status'
                    );
                    status.textContent = 'AI返修失败：' + error.message;
                    status.className =
                        'quality-status quality-repair-status error';
                }
            }
        } finally {
            qcRepairSetBusy(modal, false);
        }
        if (!succeeded.length) {
            throw new Error(
                '四版块均未完成：\n' + failed.join('\n')
            );
        }
        showStatus(
            '批量返修完成：' + succeeded.join('、') +
            (failed.length ? '；未完成：' + failed.join('；') : '') +
            '。所有结果均需人工核对。',
            failed.length ? 'error' : 'success'
        );
    }

    function qcRefusalNumberTokens(value) {
        return (String(value || '').match(/\d+(?:\.\d+)?/g) || [])
            .sort()
            .join('|');
    }

    async function qcPolishProgressRefusalText(modal) {
        const identity = qcGuardModalPatientIdentity(modal);
        const state = qcModalState(modal);
        if (!state.progressRefusalConfirmed) {
            throw new Error(
                '请先确认真实拒绝、风险告知及知情告知书真实签署'
            );
        }
        if (!modal.querySelector('.quality-ai-consent input').checked) {
            throw new Error('请先勾选本次DeepSeek发送确认');
        }
        const settings = getDeepSeekPostalSettings();
        if (!suiteGlobalAiHasApiKey(settings.apiKey)) {
            throw new Error(
                '尚未配置当前AI服务所需API Key，请先在脚本设置或悬浮框管理器中配置'
            );
        }
        const original = String(
            modal.querySelector(
                '.quality-progress-refusal-text'
            ).value || ''
        ).trim();
        if (!original) {
            throw new Error('请先生成病程拒绝相关描述');
        }
        if (!original.includes('签署相关知情告知书')) {
            throw new Error(
                '当前描述未包含知情告知书签署表述，请先核对或重新生成'
            );
        }
        const button = modal.querySelector(
            '.quality-polish-progress-refusal'
        );
        button.disabled = true;
        try {
            const content = await qcRequestDeepSeek(
                settings,
                [
                    {
                        role: 'system',
                        content: [
                            '你是病程记录文字润色工具。',
                            '只改善医学书面表达、语序和衔接，不得增加、删除、推断或改变任何拒绝项目、时间、沟通对象、与患者关系、拒绝原因、风险告知、后续处理及签署事实。',
                            '所有数字、日期时间、项目名称、人物关系和“签署相关知情告知书”必须原样保留。',
                            '不得增加诊断、检查结果、治疗措施、疗效或预后事实。',
                            '只返回润色后的单段正文，不要标题、Markdown、引号或修改说明。'
                        ].join('\n')
                    },
                    {
                        role: 'user',
                        content:
                            qcDeidentifyText(original, identity)
                    }
                ],
                {
                    json: false,
                    temperature: 0.15,
                    maxTokens: 1200
                }
            );
            const polished = String(content || '')
                .replace(/^\`\`\`(?:text)?\s*/i, '')
                .replace(/\s*\`\`\`$/i, '')
                .replace(
                    /\[患者\]/g,
                    String(identity.name || '[患者]')
                )
                .replace(
                    /\[住院号已脱敏\]/g,
                    String(
                        identity.inpatientNo ||
                        '[住院号已脱敏]'
                    )
                )
                .trim();
            if (!polished) throw new Error('AI未返回润色文本');

            const lockedDate = qcParseDateTime(
                state.progressRefusalTime
            );
            const lockedTime = lockedDate
                ? (
                    lockedDate.getFullYear() +
                    '年' +
                    pad2(lockedDate.getMonth() + 1) +
                    '月' +
                    pad2(lockedDate.getDate()) +
                    '日' +
                    pad2(lockedDate.getHours()) +
                    ':' +
                    pad2(lockedDate.getMinutes())
                )
                : '';
            const requiredFacts = [
                lockedTime,
                qcCleanSentence(state.progressRefusalItems),
                String(state.progressRefusalParty || '').trim(),
                qcCleanSentence(state.progressRefusalRelation),
                qcCleanSentence(state.progressRefusalReason),
                qcCleanSentence(state.progressRefusalFollowUp),
                '签署相关知情告知书'
            ].filter(Boolean);
            const missingFacts = requiredFacts.filter(function (fact) {
                return !polished.includes(fact);
            });
            const addedClinicalFacts = [
                /病情稳定/,
                /症状(?:明显)?好转/,
                /检查(?:结果)?提示/,
                /诊断为/,
                /给予.{0,20}(?:治疗|用药)/,
                /治疗后/,
                /疗效/,
                /预后良好/
            ].filter(function (pattern) {
                return pattern.test(polished) &&
                    !pattern.test(original);
            });
            if (
                missingFacts.length ||
                addedClinicalFacts.length ||
                polished.length >
                    Math.max(
                        original.length * 1.35,
                        original.length + 80
                    ) ||
                polished.length <
                    original.length * 0.65 ||
                qcRefusalNumberTokens(polished) !==
                    qcRefusalNumberTokens(original)
            ) {
                throw new Error(
                    'AI返回内容改变或遗漏了锁定事实，已拒绝覆盖原文'
                );
            }
            modal.querySelector(
                '.quality-progress-refusal-text'
            ).value = polished;
            const latestState = qcModalState(modal);
            latestState.progressRefusalText = polished;
            latestState.progressRefusalCopiedAt = '';
            modal._qcState = latestState;
            qcSavePatientState(identity, latestState);
            qcExecuteScan(modal, false);
            showStatus(
                'AI润色已完成并通过事实锁定校验；请医师继续逐字核对后再复制。',
                'success'
            );
            return polished;
        } finally {
            button.disabled = false;
        }
    }

    function qcGenerateRefusalDraft(modal) {
        const identity =
            qcGuardModalPatientIdentity(
                modal
            );
        const state = qcModalState(modal);
        if (state.labStatus !== 'refused') {
            throw new Error(
                '只有人工确认“患者或家属明确拒绝”后，才能生成拒绝文书'
            );
        }
        if (!identity.name) throw new Error('请先填写患者姓名');
        if (!String(state.refusalItems || '').trim()) {
            throw new Error('请填写被拒绝的具体检查/检验项目');
        }
        const refusalTime = qcParseDateTime(state.refusalTime);
        if (!refusalTime) {
            throw new Error('请填写精确到分钟的实际告知时间');
        }
        const timeLabel =
            refusalTime.getFullYear() + '年' +
            pad2(refusalTime.getMonth() + 1) + '月' +
            pad2(refusalTime.getDate()) + '日 ' +
            pad2(refusalTime.getHours()) + ':' +
            pad2(refusalTime.getMinutes());
        const party = String(state.refusalParty || '患者本人').trim();
        const relation = String(state.refusalRelation || '').trim();
        const reason = String(
            state.refusalReason ||
            '经充分沟通后仍拒绝接受上述检查'
        ).trim();
        const items = String(state.refusalItems).trim();
        const draft = [
            '拒绝检查（检验）知情告知书（待签署草稿）',
            '患者姓名：' + identity.name +
                '    住院号：' + (identity.inpatientNo || '待补'),
            '告知时间：' + timeLabel,
            '告知对象：' + party +
                (relation ? '（与患者关系：' + relation + '）' : ''),
            '拟行但被拒绝的检查（检验）项目：' + items + '。',
            '告知内容：医师已说明上述检查（检验）的目的、必要性、实施方式、可能获益以及不进行检查可能造成的影响。拒绝上述检查可能导致病情评估不充分、相关异常不能及时发现、诊断或治疗延误，并可能影响后续诊疗方案及预后判断。',
            '替代或后续方案：可在患者或家属重新同意后尽快完善相关检查；医师将结合现有临床资料继续观察病情，并根据病情变化再次沟通、评估和调整诊疗方案。替代方案不能完全取代上述检查的诊断价值。',
            '患者/家属意见：已听取医师说明并有机会提问，对上述风险表示理解。' +
                reason + '，相关后果已知悉。',
            '患者/家属/法定监护人/授权委托人签名：________________',
            '与患者关系：________________    签署时间：______年____月____日____时____分',
            '告知医师签名：________________    签署时间：______年____月____日____时____分',
            '备注：本稿由脚本根据人工确认的信息生成，必须由医师核对并由相关人员真实签署后方可生效；不得以本稿或本机登记代替HIS电子签名或纸质原件。'
        ].join('\n');

        modal.querySelector('.quality-refusal-draft').value = draft;
        modal.querySelector('.quality-signed-confirmed').checked = false;
        state.refusalDraft = draft;
        state.signedConfirmed = false;
        state.signedConfirmedAt = '';
        modal._qcState = state;
        qcSavePatientState(identity, state);
        qcExecuteScan(modal, false);
        return draft;
    }

    function qcProgressRefusalTypeInfo(value) {
        const definitions = {
            lab: {
                label: '化验/检验',
                action: '完善',
                risk:
                    '相关客观指标缺失，不能及时发现血液、生化或其他检验异常，进而造成病情评估不充分、诊断及治疗延误'
            },
            imaging: {
                label: '影像学检查',
                action: '完善',
                risk:
                    '不能进一步明确病变的部位、性质及程度，可能影响诊断、病情评估和后续治疗方案制定'
            },
            functional: {
                label: '功能检查',
                action: '完善',
                risk:
                    '不能客观评估相应器官或系统功能，可能遗漏异常并影响病情判断和后续诊疗'
            },
            treatment: {
                label: '治疗/处置',
                action: '接受',
                risk:
                    '病情控制或治疗效果受到影响，并可能增加症状持续、病情进展及调整治疗方案困难的风险'
            },
            other: {
                label: '相关检查或处置',
                action: '接受',
                risk:
                    '现有资料不足，不能及时、完整地评估病情，可能导致诊断、治疗或后续处置延误'
            }
        };

        return definitions[value] ||
            definitions.other;
    }

    function qcCleanSentence(value) {
        return String(value || '')
            .replace(/\s+/g, ' ')
            .replace(/[。；;，,]+$/, '')
            .trim();
    }

    function qcGenerateProgressRefusalText(modal) {
        const identity =
            qcGuardModalPatientIdentity(
                modal
            );
        const state = qcModalState(modal);

        if (
            !state.progressRefusalConfirmed
        ) {
            throw new Error(
                '请先勾选“已确认真实拒绝、完成风险告知且知情告知书已真实签署”'
            );
        }

        if (
            !identity.name &&
            !identity.inpatientNo
        ) {
            throw new Error(
                '请先识别或填写当前患者身份'
            );
        }

        const items =
            qcCleanSentence(
                state.progressRefusalItems
            );

        if (!items) {
            throw new Error(
                '请填写患者或家属拒绝的具体项目'
            );
        }

        const refusalTime =
            qcParseDateTime(
                state.progressRefusalTime
            );

        if (!refusalTime) {
            throw new Error(
                '请填写精确到分钟的实际沟通时间'
            );
        }

        const timeLabel =
            refusalTime.getFullYear() +
            '年' +
            pad2(
                refusalTime.getMonth() + 1
            ) +
            '月' +
            pad2(
                refusalTime.getDate()
            ) +
            '日' +
            pad2(
                refusalTime.getHours()
            ) +
            ':' +
            pad2(
                refusalTime.getMinutes()
            );

        const party =
            String(
                state.progressRefusalParty ||
                '患者本人'
            ).trim();
        const relation =
            qcCleanSentence(
                state.progressRefusalRelation
            );
        const reason =
            qcCleanSentence(
                state.progressRefusalReason
            );
        const followUp =
            qcCleanSentence(
                state.progressRefusalFollowUp
            );
        const typeInfo =
            qcProgressRefusalTypeInfo(
                state.progressRefusalType
            );
        const partyLabel =
            party +
            (
                relation
                    ? '（与患者关系：' +
                        relation +
                      '）'
                    : ''
            );
        const sentences = [
            '于' +
                timeLabel +
                '，' +
                partyLabel +
                '明确表示拒绝' +
                typeInfo.action +
                items +
                '。',
            '已向其说明上述' +
                typeInfo.label +
                '的目的、必要性及可能获益，并告知拒绝可能导致' +
                typeInfo.risk +
                '等后果。'
        ];

        if (reason) {
            sentences.push(
                '其表示拒绝原因为：' +
                reason +
                '。'
            );
        }

        sentences.push(
            '其表示已理解上述告知，仍坚持拒绝，并签署相关知情告知书。'
        );

        sentences.push(
            followUp
                ? '后续处理：' +
                    followUp +
                    '。'
                : '嘱密切观察病情变化，将继续沟通，必要时再次建议完善相关项目。'
        );

        const text =
            sentences.join('');

        modal.querySelector(
            '.quality-progress-refusal-text'
        ).value = text;

        state.progressRefusalText = text;
        state.progressRefusalCopiedAt = '';
        modal._qcState = state;

        qcSavePatientState(
            identity,
            state
        );

        qcExecuteScan(
            modal,
            false
        );

        return text;
    }

    function qcSyncProgressRefusalFromNotice(
        modal
    ) {
        qcGuardModalPatientIdentity(
            modal
        );

        const sourceItems =
            modal.querySelector(
                '.quality-refusal-items'
            ).value;
        const sourceTime =
            modal.querySelector(
                '.quality-refusal-time'
            ).value;
        const sourceParty =
            modal.querySelector(
                '.quality-refusal-party'
            ).value;
        const sourceRelation =
            modal.querySelector(
                '.quality-refusal-relation'
            ).value;
        const sourceReason =
            modal.querySelector(
                '.quality-refusal-reason'
            ).value;

        if (
            !String(sourceItems || '').trim()
        ) {
            throw new Error(
                '上方拒绝文书区尚未填写具体项目'
            );
        }

        modal.querySelector(
            '.quality-progress-refusal-type'
        ).value = 'lab';
        modal.querySelector(
            '.quality-progress-refusal-items'
        ).value = sourceItems;
        modal.querySelector(
            '.quality-progress-refusal-time'
        ).value = sourceTime;
        modal.querySelector(
            '.quality-progress-refusal-party'
        ).value = sourceParty;
        modal.querySelector(
            '.quality-progress-refusal-relation'
        ).value = sourceRelation;
        modal.querySelector(
            '.quality-progress-refusal-reason'
        ).value =
            String(sourceReason || '').trim() ===
                '经充分沟通后仍拒绝接受上述检查'
                ? ''
                : sourceReason;

        const identity =
            qcModalIdentity(modal);
        const state =
            qcModalState(modal);

        modal._qcState = state;
        qcSavePatientState(
            identity,
            state
        );
    }

    async function qcCopyProgressRefusalText(
        modal,
        generateFirst
    ) {
        qcGuardModalPatientIdentity(
            modal
        );

        const currentState =
            qcModalState(modal);

        if (
            !currentState.progressRefusalConfirmed
        ) {
            throw new Error(
                '请先确认真实拒绝、风险告知及相关知情告知书均已完成'
            );
        }

        let text = '';

        if (generateFirst) {
            text =
                qcGenerateProgressRefusalText(
                    modal
                );
        } else {
            text =
                modal.querySelector(
                    '.quality-progress-refusal-text'
                ).value;
        }

        if (!String(text || '').trim()) {
            throw new Error(
                '尚无可复制的病程拒绝描述'
            );
        }

        if (
            !String(text).includes(
                '签署相关知情告知书'
            )
        ) {
            throw new Error(
                '当前描述未包含“签署相关知情告知书”，请重新生成或核对后补充'
            );
        }

        const copied =
            await qcCopyText(text);

        if (!copied) {
            return false;
        }

        const identity =
            qcModalIdentity(modal);
        const state =
            qcModalState(modal);

        state.progressRefusalText = text;
        state.progressRefusalCopiedAt =
            new Date().toLocaleString();
        modal._qcState = state;

        qcSavePatientState(
            identity,
            state
        );

        qcExecuteScan(
            modal,
            false
        );

        return true;
    }

    async function qcCopyText(value) {
        const text = String(value || '');
        if (!text) return false;
        try {
            if (navigator.clipboard && navigator.clipboard.writeText) {
                await navigator.clipboard.writeText(text);
                return true;
            }
        } catch (error) {
            // HTTP内网页面可能禁用Clipboard API，继续旧式复制。
        }
        const textarea = document.createElement('textarea');
        textarea.value = text;
        textarea.setAttribute('readonly', 'readonly');
        Object.assign(textarea.style, {
            position: 'fixed',
            left: '-9999px',
            top: '0',
            opacity: '0'
        });
        document.body.appendChild(textarea);
        textarea.focus();
        textarea.select();
        textarea.setSelectionRange(0, textarea.value.length);
        let copied = false;
        try {
            copied = Boolean(document.execCommand('copy'));
        } catch (error) {
            copied = false;
        }
        textarea.remove();
        return copied;
    }

    /******************************************************************
     * 病案质控功能区折叠
     *
     * 沿用药品录入脚本的交互：标题栏右侧显示“折叠/展开”，
     * 每个功能区独立记忆状态，并同步aria-expanded。
     ******************************************************************/

    function qcGetSectionCollapsedMap() {
        let saved = {};

        try {
            saved = GM_getValue(
                QUALITY_CONTROL_SECTION_COLLAPSED_KEY,
                {}
            );
        } catch (error) {
            saved = qcLoadJson(
                QUALITY_CONTROL_SECTION_COLLAPSED_KEY,
                {}
            );
        }

        return saved &&
            typeof saved === 'object' &&
            !Array.isArray(saved)
            ? saved
            : {};
    }

    function qcSaveSectionCollapsedMap(map) {
        const value = map &&
            typeof map === 'object' &&
            !Array.isArray(map)
            ? map
            : {};

        try {
            GM_setValue(
                QUALITY_CONTROL_SECTION_COLLAPSED_KEY,
                value
            );
            return;
        } catch (error) {
            // 油猴存储不可用时回退到同源localStorage。
        }

        try {
            localStorage.setItem(
                QUALITY_CONTROL_SECTION_COLLAPSED_KEY,
                JSON.stringify(value)
            );
        } catch (error) {
            // 状态记忆失败不影响本次折叠操作。
        }
    }

    function qcSetSectionCollapsed(
        section,
        collapsed,
        save
    ) {
        if (!section) {
            return;
        }

        const value = Boolean(collapsed);
        const toggle = section.querySelector(
            '.quality-section-toggle'
        );

        section.dataset.collapsed =
            value ? 'true' : 'false';

        if (toggle) {
            toggle.textContent =
                value ? '展开' : '折叠';
            toggle.setAttribute(
                'aria-expanded',
                value ? 'false' : 'true'
            );
        }

        if (save !== false) {
            const key =
                section.dataset.sectionKey;

            if (key) {
                const map =
                    qcGetSectionCollapsedMap();
                map[key] = value;
                qcSaveSectionCollapsedMap(map);
            }
        }
    }

    function qcSetSectionCollapsedByKey(
        modal,
        key,
        collapsed,
        save
    ) {
        if (!modal || !key) {
            return;
        }

        qcSetSectionCollapsed(
            modal.querySelector(
                '.quality-section[data-section-key="' +
                    key +
                    '"]'
            ),
            collapsed,
            save
        );
    }

    function qcInitializeSectionControls(modal) {
        const collapsedMap =
            qcGetSectionCollapsedMap();
        const sections = Array.from(
            modal.querySelectorAll(
                '.quality-section[data-section-key]'
            )
        );

        sections.forEach(function (section) {
            const key =
                section.dataset.sectionKey;
            const defaultCollapsed =
                section.dataset.defaultCollapsed ===
                'true';
            const collapsed =
                Object.prototype.hasOwnProperty.call(
                    collapsedMap,
                    key
                )
                    ? Boolean(collapsedMap[key])
                    : defaultCollapsed;

            qcSetSectionCollapsed(
                section,
                collapsed,
                false
            );
        });

        modal.querySelectorAll(
            '.quality-section-toggle'
        ).forEach(function (toggle) {
            toggle.addEventListener(
                'click',
                function (event) {
                    event.preventDefault();
                    event.stopPropagation();

                    const section =
                        toggle.closest(
                            '.quality-section[data-section-key]'
                        );
                    const collapsed =
                        section &&
                        section.dataset.collapsed !==
                            'true';

                    qcSetSectionCollapsed(
                        section,
                        collapsed,
                        true
                    );
                }
            );
        });
    }

    function qcRuleSeverityOptionsHtml(selected) {
        return [
            ['default', '沿用程序判定'],
            ['error', '统一为需整改'],
            ['warn', '统一为提醒'],
            ['info', '统一为人工核对']
        ].map(function (option) {
            return (
                '<option value="' + option[0] + '"' +
                    (option[0] === selected ? ' selected' : '') +
                '>' + escapeHtml(option[1]) + '</option>'
            );
        }).join('');
    }

    function qcRuleManagementRowsHtml(config) {
        const ruleConfig = config || qcLoadRuleConfig();
        return QUALITY_CONTROL_RULE_DEFINITIONS.map(
            function (definition) {
                const rule = ruleConfig.rules[definition.id];
                const parameters = definition.params.map(
                    function (parameter) {
                        return (
                            '<label class="quality-rule-param">' +
                                escapeHtml(parameter.label) +
                                '<input type="number" data-rule-param="' +
                                    escapeHtml(parameter.key) + '" min="' +
                                    parameter.min + '" max="' +
                                    parameter.max + '" step="' +
                                    parameter.step + '" value="' +
                                    escapeHtml(
                                        rule.params[parameter.key]
                                    ) + '">' +
                                '<span>' + escapeHtml(parameter.unit) + '</span>' +
                            '</label>'
                        );
                    }
                ).join('');
                return (
                    '<div class="quality-rule-row" data-rule-id="' +
                        escapeHtml(definition.id) + '">' +
                        '<div class="quality-rule-main">' +
                            '<label class="quality-rule-switch">' +
                                '<input type="checkbox" class="quality-rule-enabled"' +
                                    (rule.enabled ? ' checked' : '') + '>' +
                                '<strong>' + escapeHtml(definition.name) + '</strong>' +
                            '</label>' +
                            '<span class="quality-rule-scope">' +
                                escapeHtml(definition.scope) +
                            '</span>' +
                        '</div>' +
                        '<div class="quality-rule-controls">' +
                            '<label>失败等级<select class="quality-rule-severity">' +
                                qcRuleSeverityOptionsHtml(rule.severity) +
                            '</select></label>' +
                            '<label>生效日期<input type="date" class="quality-rule-effective-date" value="' +
                                escapeHtml(rule.effectiveDate || '') + '"></label>' +
                            parameters +
                        '</div>' +
                        '<div class="quality-rule-detail">' +
                            '触发：' + escapeHtml(definition.trigger) +
                            '；检查：' + escapeHtml(definition.requirement) +
                            '；处理：' + escapeHtml(definition.action) +
                        '</div>' +
                    '</div>'
                );
            }
        ).join('');
    }

    function qcUpdateConfigStatus(
        modal,
        ruleConfig,
        promptConfig,
        repairPromptConfig
    ) {
        const config = ruleConfig || qcLoadRuleConfig();
        const aiConfig = promptConfig || qcLoadAiPromptConfig();
        const repairConfig = qcNormalizeRepairPromptConfig(
            repairPromptConfig || qcLoadRepairPromptConfig()
        );
        const enabledCount = QUALITY_CONTROL_RULE_DEFINITIONS.filter(
            function (definition) {
                return qcRuleEnabled(config, definition.id);
            }
        ).length;
        const status = modal.querySelector('.quality-config-status');
        if (!status) return;
        status.textContent =
            '规则默认版本 v' + QUALITY_CONTROL_DEFAULT_CONFIG_VERSION +
            '；当前生效' + enabledCount + '/' +
            QUALITY_CONTROL_RULE_DEFINITIONS.length + '项；规则' +
            (config.customized ? '已自定义' : '使用脚本默认值') +
            '；AI提示词' +
            (aiConfig.customized ? '已自定义' : '使用脚本默认值') +
            '；AI返修提示词' +
            (repairConfig.customized
                ? '已自定义'
                : '使用脚本默认值') +
            (
                config.updatedAt ||
                aiConfig.updatedAt ||
                repairConfig.updatedAt
                    ? '；最近保存：' +
                        (
                            config.updatedAt ||
                            aiConfig.updatedAt ||
                            repairConfig.updatedAt
                        )
                    : ''
            ) + '。';
        status.className = 'quality-status quality-config-status ok';
    }

    function qcPopulateConfigEditor(
        modal,
        ruleConfig,
        promptConfig,
        repairPromptConfig
    ) {
        const config = qcNormalizeRuleConfig(
            ruleConfig || qcLoadRuleConfig()
        );
        const aiConfig = qcNormalizeAiPromptConfig(
            promptConfig || qcLoadAiPromptConfig()
        );
        QUALITY_CONTROL_RULE_DEFINITIONS.forEach(function (definition) {
            const row = modal.querySelector(
                '.quality-rule-row[data-rule-id="' +
                    definition.id + '"]'
            );
            if (!row) return;
            const rule = config.rules[definition.id];
            row.querySelector('.quality-rule-enabled').checked =
                rule.enabled;
            row.querySelector('.quality-rule-severity').value =
                rule.severity;
            row.querySelector('.quality-rule-effective-date').value =
                rule.effectiveDate || '';
            definition.params.forEach(function (parameter) {
                const input = row.querySelector(
                    '[data-rule-param="' + parameter.key + '"]'
                );
                if (input) input.value = rule.params[parameter.key];
            });
        });
        modal.querySelector('.quality-additional-policy').value =
            config.additionalPolicyText || '';
        modal.querySelector('.quality-ai-prompt-editor').value =
            aiConfig.prompt;
        modal._qcRuleConfigEditor = config;
        modal._qcAiPromptEditor = aiConfig;
        const repairConfig = qcNormalizeRepairPromptConfig(
            repairPromptConfig || qcLoadRepairPromptConfig()
        );
        const hasRepairEditorContent = Array.from(
            modal.querySelectorAll('.quality-repair-prompt')
        ).some(function (editor) {
            return String(editor.value || '').trim();
        });
        if (repairPromptConfig || !hasRepairEditorContent) {
            qcRepairPopulatePromptEditors(modal, repairConfig);
        }
        qcUpdateConfigStatus(
            modal,
            config,
            aiConfig,
            repairConfig
        );
    }

    function qcReadRuleConfigEditor(modal) {
        const config = qcDefaultRuleConfig();
        config.customized = true;
        const additionalPolicy = String(
            modal.querySelector('.quality-additional-policy').value || ''
        ).trim();
        if (additionalPolicy.length > 12000) {
            throw new Error('补充质控政策不能超过12000字');
        }
        config.additionalPolicyText = additionalPolicy;
        QUALITY_CONTROL_RULE_DEFINITIONS.forEach(function (definition) {
            const row = modal.querySelector(
                '.quality-rule-row[data-rule-id="' +
                    definition.id + '"]'
            );
            const rule = config.rules[definition.id];
            rule.enabled = row.querySelector(
                '.quality-rule-enabled'
            ).checked;
            rule.severity = row.querySelector(
                '.quality-rule-severity'
            ).value;
            rule.effectiveDate = String(
                row.querySelector(
                    '.quality-rule-effective-date'
                ).value || ''
            );
            definition.params.forEach(function (parameter) {
                const input = row.querySelector(
                    '[data-rule-param="' + parameter.key + '"]'
                );
                const numberValue = Number(input.value);
                if (
                    !Number.isFinite(numberValue) ||
                    numberValue < parameter.min ||
                    numberValue > parameter.max ||
                    (parameter.step === 1 &&
                        !Number.isInteger(numberValue))
                ) {
                    throw new Error(
                        '规则“' + definition.name + '”的“' +
                        parameter.label + '”应为' +
                        parameter.min + '至' + parameter.max +
                        '之间的整数'
                    );
                }
                rule.params[parameter.key] = numberValue;
            });
        });
        const timing = config.rules.admissionFirstCourseTiming.params;
        if (timing.minMinutes > timing.maxMinutes) {
            throw new Error('入院记录与首程的最短间隔不能大于最长间隔');
        }
        return config;
    }

    function qcReadAiPromptEditor(modal) {
        const prompt = String(
            modal.querySelector('.quality-ai-prompt-editor').value || ''
        ).trim();
        if (prompt.length < 20) {
            throw new Error('AI质控提示词过短，请至少填写20个字符');
        }
        if (prompt.length > 20000) {
            throw new Error('AI质控提示词不能超过20000字');
        }
        return {
            schemaVersion: QUALITY_CONTROL_CONFIG_SCHEMA_VERSION,
            defaultVersion: QUALITY_CONTROL_DEFAULT_CONFIG_VERSION,
            customized: true,
            updatedAt: '',
            prompt: prompt
        };
    }

    function qcValidateImportedConfiguration(packageValue) {
        if (
            !packageValue ||
            typeof packageValue !== 'object' ||
            packageValue.kind !== QUALITY_CONTROL_CONFIG_EXPORT_KIND
        ) {
            throw new Error('配置文件类型不正确，请导入本模块导出的完整JSON');
        }
        const rawRules = packageValue.ruleConfig;
        const rawPrompt = packageValue.aiPrompt;
        const rawRepairPrompts = packageValue.repairPrompts ||
            qcDefaultRepairPromptConfig();
        if (!rawRules || !rawRules.rules || !rawPrompt) {
            throw new Error('配置JSON缺少ruleConfig或aiPrompt');
        }
        QUALITY_CONTROL_RULE_DEFINITIONS.forEach(function (definition) {
            const rule = rawRules.rules[definition.id];
            if (!rule) return;
            if (
                rule.severity !== undefined &&
                !['default', 'error', 'warn', 'info'].includes(
                    rule.severity
                )
            ) {
                throw new Error('规则“' + definition.name + '”失败等级无效');
            }
            if (
                rule.effectiveDate &&
                !/^\d{4}-\d{2}-\d{2}$/.test(rule.effectiveDate)
            ) {
                throw new Error('规则“' + definition.name + '”生效日期无效');
            }
            definition.params.forEach(function (parameter) {
                if (
                    !rule.params ||
                    rule.params[parameter.key] === undefined
                ) return;
                const value = Number(rule.params[parameter.key]);
                if (
                    !Number.isFinite(value) ||
                    value < parameter.min ||
                    value > parameter.max
                ) {
                    throw new Error(
                        '规则“' + definition.name + '”的“' +
                        parameter.label + '”超出允许范围'
                    );
                }
            });
        });
        const prompt = String(rawPrompt.prompt || '').trim();
        if (prompt.length < 20 || prompt.length > 20000) {
            throw new Error('导入的AI质控提示词长度无效');
        }
        QUALITY_CONTROL_REPAIR_DEFINITIONS.forEach(
            function (definition) {
                const repairPrompt = String(
                    rawRepairPrompts.prompts &&
                    rawRepairPrompts.prompts[definition.type] || ''
                ).trim();
                if (
                    repairPrompt.length < 20 ||
                    repairPrompt.length > 20000
                ) {
                    throw new Error(
                        '导入的“' + definition.label +
                        '”返修提示词长度无效'
                    );
                }
            }
        );
        const normalizedRules = qcNormalizeRuleConfig(rawRules);
        const timing =
            normalizedRules.rules.admissionFirstCourseTiming.params;
        if (timing.minMinutes > timing.maxMinutes) {
            throw new Error('导入配置中首程最短间隔大于最长间隔');
        }
        normalizedRules.customized = true;
        const normalizedPrompt = qcNormalizeAiPromptConfig(rawPrompt);
        normalizedPrompt.customized = true;
        const normalizedRepairPrompts =
            qcNormalizeRepairPromptConfig(rawRepairPrompts);
        normalizedRepairPrompts.customized =
            Boolean(packageValue.repairPrompts);
        return {
            ruleConfig: normalizedRules,
            aiPrompt: normalizedPrompt,
            repairPrompts: normalizedRepairPrompts
        };
    }

    function qcMarkAiResultStale(modal, message) {
        modal._qcAiPlainText = '';
        modal.querySelector('.quality-ai-results').innerHTML = '';
        const status = modal.querySelector('.quality-ai-status');
        status.textContent = message ||
            '规则或AI提示词已变化，请重新执行AI质控。';
        status.className = 'quality-status quality-ai-status warn';
    }

