    function examFormTypeForPage(type) {
        const definition = EXAM_APPLICATION_PAGE_DEFINITIONS.find(function (item) {
            return item.type === type;
        });
        return definition ? definition.formType : type;
    }

    function examOutputPageDefinitions(selected) {
        return selected.reduce(function (pages, definition) {
            return pages.concat(EXAM_APPLICATION_PAGE_DEFINITIONS.filter(function (page) {
                return page.formType === definition.type;
            }));
        }, []);
    }

