    const examApplicationImageCache = {};

    function examReadJson(storageKey, fallback) {
        if (
            storageKey ===
                EXAM_APPLICATION_STATE_STORAGE_KEY
        ) {
            const value =
                patientLargeCacheReadStore(
                    storageKey
                );

            return value === null ||
                value === undefined
                    ? fallback
                    : value;
        }

        try {
            const raw =
                localStorage.getItem(
                    storageKey
                );

            if (!raw) {
                return fallback;
            }

            const value =
                JSON.parse(
                    raw
                );

            return value === null ||
                value === undefined
                    ? fallback
                    : value;
        } catch (error) {
            return fallback;
        }
    }

    function examWriteJson(storageKey, value) {
        if (
            storageKey ===
                EXAM_APPLICATION_STATE_STORAGE_KEY
        ) {
            patientLargeCacheWriteStore(
                storageKey,
                value
            );
            return;
        }

        localStorage.setItem(
            storageKey,
            JSON.stringify(
                value
            )
        );
    }

    function examToday() {
        const now = new Date();
        return now.getFullYear() + '-' +
            String(now.getMonth() + 1).padStart(2, '0') + '-' +
            String(now.getDate()).padStart(2, '0');
    }

    function examCurrentTime() {
        const now = new Date();
        return String(now.getHours()).padStart(2, '0') + ':' +
            String(now.getMinutes()).padStart(2, '0');
    }

    function examPatientKey(inpatientNo) {
        const value = String(inpatientNo || '')
            .trim()
            .replace(/[^A-Za-z0-9-]/g, '')
            .toLowerCase();
        return value ? 'no:' + value : '';
    }

    function examDefaultFixed() {
        return {
            hospital: '济南健佳中医医院',
            department: '中医科',
            ward: '',
            doctor: '',
            doctorPhone: ''
        };
    }

    function examLoadFixed() {
        const stored = examReadJson(
            EXAM_APPLICATION_FIXED_STORAGE_KEY,
            {}
        );
        return Object.assign(
            examDefaultFixed(),
            stored && typeof stored === 'object' ? stored : {},
            {
                applicationDate: examToday(),
                applicationTime: examCurrentTime()
            }
        );
    }

