    function examSingleMapping(
        id,
        label,
        source,
        x,
        centerY,
        width,
        fontSize,
        align
    ) {
        const lineHeight = Math.max(24, Math.round(fontSize * 1.28));
        return {
            id: id,
            label: label,
            source: source,
            x: x / EXAM_APPLICATION_PAGE_WIDTH,
            y: (centerY - lineHeight / 2) / EXAM_APPLICATION_PAGE_HEIGHT,
            width: width / EXAM_APPLICATION_PAGE_WIDTH,
            fontSize: fontSize,
            lineHeight: lineHeight,
            maxLines: 1,
            align: align || 'left',
            mode: 'single',
            when: '',
            enabled: true,
            custom: false
        };
    }

    function examWrappedMapping(
        id,
        label,
        source,
        x,
        y,
        width,
        lineHeight,
        maxLines,
        fontSize
    ) {
        return {
            id: id,
            label: label,
            source: source,
            x: x / EXAM_APPLICATION_PAGE_WIDTH,
            y: y / EXAM_APPLICATION_PAGE_HEIGHT,
            width: width / EXAM_APPLICATION_PAGE_WIDTH,
            fontSize: fontSize,
            lineHeight: lineHeight,
            maxLines: maxLines,
            align: 'left',
            mode: 'wrapped',
            when: '',
            enabled: true,
            custom: false
        };
    }

    function examCheckMapping(
        id,
        label,
        source,
        whenValue,
        centerX,
        centerY
    ) {
        const size = 34;
        return {
            id: id,
            label: label,
            source: source,
            x: (centerX - size / 2) / EXAM_APPLICATION_PAGE_WIDTH,
            y: (centerY - size / 2) / EXAM_APPLICATION_PAGE_HEIGHT,
            width: size / EXAM_APPLICATION_PAGE_WIDTH,
            fontSize: 24,
            lineHeight: size,
            maxLines: 1,
            align: 'center',
            mode: 'check',
            when: whenValue,
            enabled: true,
            custom: false
        };
    }

