    function examReverseTemplateMappings(templateStyle) {
        const style = examNormalizeTemplateStyle(templateStyle);
        const positions = style === 'traditional'
            ? {"options":[["safetyQ1",514,1190,1272],["safetyQ2",594,1190,1272],["safetyQ3",676,1190,1272],["safetyQ4",757,1190,1272],["safetyQ5",840,1190,1272],["safetyQ6",922,1190,1272],["safetyQ7",1004,1190,1272],["safetyQ8",1085,1190,1272],["safetyQ9",1246,1190,1272],["safetyQ10",1569,1190,1272]],"filler":[589,1242,163],"consent":[282,1730,126],"consentDates":[[883,1730,86],[1015,1730,71],[1132,1730,52]],"contrastConsent":[415,2040,186],"contrastDates":[[979,2040,84],[1127,2040,76],[1253,2040,76]]}
            : {"options":[["safetyQ1",482,1222,1328],["safetyQ2",560,1222,1328],["safetyQ3",638,1222,1328],["safetyQ4",716,1222,1328],["safetyQ5",822,1222,1328],["safetyQ6",900,1222,1328],["safetyQ7",978,1222,1328],["safetyQ8",1056,1222,1328],["safetyQ9",1134,1222,1328],["safetyQ10",1366,1222,1328]],"filler":[576.0,1196,175],"consent":[285,1592,140],"consentDates":[[952,1591,100],[1102,1591,40],[1180,1591,40]],"contrastConsent":[411,1971,156],"contrastDates":[[952,1970,100],[1102,1970,40],[1180,1970,40]]};
        const elements = [];
        positions.options.forEach(function (item, index) {
            ['yes', 'no'].forEach(function (choice, choiceIndex) {
                elements.push(examCheckMapping(
                    'mr-reverse-q' + (index + 1) + '-' + choice,
                    'MR反面第' + (index + 1) + '项-' + (choice === 'yes' ? '是' : '否'),
                    'form.' + item[0], choice, item[2 + choiceIndex], item[1]
                ));
            });
        });
        function addText(id, label, source, position, size, align) {
            elements.push(examSingleMapping(
                id, label, source,
                position[0], position[1], position[2], size || 24, align
            ));
        }
        addText('mr-reverse-filler', '第9项填充物性质', 'form.safetyFiller', positions.filler);
        addText('mr-reverse-consent', 'MR检查是否同意', 'computed.mrConsentText', positions.consent, 24, 'center');
        addText('mr-reverse-contrast-consent', '增强扫描是否同意', 'computed.contrastConsentText', positions.contrastConsent, 24, 'center');
        ['Year', 'Month', 'Day'].forEach(function (part, index) {
            const label = ['年', '月', '日'][index];
            addText('mr-reverse-consent-' + part.toLowerCase(), 'MR检查填写日期-' + label,
                'computed.mrConsent' + part, positions.consentDates[index], 24, 'center');
            addText('mr-reverse-contrast-' + part.toLowerCase(), '增强扫描填写日期-' + label,
                'computed.contrastConsent' + part, positions.contrastDates[index], 24, 'center');
        });
        return { ctReverse: [], mrReverse: elements };
    }

    function examMappingStyleVersions(templateStyle) {
        const style = examNormalizeTemplateStyle(templateStyle);
        return style === 'traditional'
            ? {
                defaultVersion: EXAM_APPLICATION_TRADITIONAL_DEFAULT_VERSION,
                templateVersion: EXAM_APPLICATION_TRADITIONAL_TEMPLATE_VERSION
            }
            : {
                defaultVersion: EXAM_APPLICATION_MAPPING_DEFAULT_VERSION,
                templateVersion: EXAM_APPLICATION_TEMPLATE_VERSION
            };
    }

    function examDefaultMappingConfig(templateStyle) {
        const style = examNormalizeTemplateStyle(templateStyle);
        const versions = examMappingStyleVersions(style);
        const templates = style === 'traditional'
            ? examTraditionalTemplateMappings()
            : examDefaultTemplateMappings();
        Object.assign(templates, examReverseTemplateMappings(style));
        const result = {
            schemaVersion: EXAM_APPLICATION_MAPPING_SCHEMA_VERSION,
            defaultVersion: versions.defaultVersion,
            templateVersion: versions.templateVersion,
            templateStyle: style,
            customized: false,
            updatedAt: 0,
            templates: {}
        };
        EXAM_APPLICATION_PAGE_DEFINITIONS.forEach(function (definition) {
            result.templates[definition.type] = {
                elements: templates[definition.type]
            };
        });
        return result;
    }

    function examCloneValue(value) {
        return JSON.parse(JSON.stringify(value));
    }

    function examClamp(value, minimum, maximum, fallback) {
        const number = Number(value);
        if (!Number.isFinite(number)) return fallback;
        return Math.min(maximum, Math.max(minimum, number));
    }

    function examMappingSourceKeys() {
        const keys = [];
        examMappingSourceGroups().forEach(function (group) {
            group.options.forEach(function (option) {
                keys.push(option[0]);
            });
        });
        return keys;
    }

    function examNormalizeMappingElement(rawValue, fallbackValue) {
        const hasDefaultElement = Boolean(fallbackValue);
        const fallback = fallbackValue || {
            id: 'custom-' + Date.now(),
            label: '自定义文本框',
            source: 'patient.name',
            x: 0.1,
            y: 0.1,
            width: 0.22,
            fontSize: 24,
            lineHeight: 32,
            maxLines: 1,
            align: 'left',
            mode: 'single',
            when: '',
            enabled: true,
            custom: true
        };
        const raw = rawValue && typeof rawValue === 'object' ? rawValue : {};
        const modes = ['single', 'wrapped', 'check'];
        const aligns = ['left', 'center', 'right'];
        const sourceKeys = examMappingSourceKeys();
        const source = sourceKeys.includes(String(raw.source || ''))
            ? String(raw.source)
            : fallback.source;
        const x = examClamp(raw.x, 0, 0.995, fallback.x);
        const width = examClamp(
            raw.width,
            0.008,
            Math.max(0.008, 1 - x),
            Math.min(fallback.width, 1 - x)
        );
        return examConstrainMappingBounds({
            id: String(raw.id || fallback.id).slice(0, 100),
            label: String(raw.label || fallback.label).trim().slice(0, 60),
            source: source,
            x: x,
            y: examClamp(raw.y, 0, 0.995, fallback.y),
            width: width,
            fontSize: Math.round(examClamp(
                raw.fontSize, 8, 96, fallback.fontSize
            )),
            lineHeight: Math.round(examClamp(
                raw.lineHeight, 10, 160, fallback.lineHeight
            )),
            maxLines: Math.round(examClamp(
                raw.maxLines, 1, 20, fallback.maxLines
            )),
            align: aligns.includes(raw.align) ? raw.align : fallback.align,
            mode: modes.includes(raw.mode) ? raw.mode : fallback.mode,
            when: String(
                raw.when === undefined ? fallback.when || '' : raw.when
            ).slice(0, 40),
            enabled: raw.enabled === undefined
                ? fallback.enabled !== false
                : Boolean(raw.enabled),
            custom: hasDefaultElement ? false : true
        });
    }

    function examNormalizeMappingConfig(rawValue, templateStyle) {
        const raw = rawValue && typeof rawValue === 'object'
            ? rawValue
            : {};
        const style = examNormalizeTemplateStyle(
            templateStyle || raw.templateStyle
        );
        const defaults = examDefaultMappingConfig(style);
        const versions = examMappingStyleVersions(style);
        const normalized = {
            schemaVersion: EXAM_APPLICATION_MAPPING_SCHEMA_VERSION,
            defaultVersion: versions.defaultVersion,
            templateVersion: versions.templateVersion,
            templateStyle: style,
            customized: Boolean(raw.customized),
            updatedAt: Number(raw.updatedAt) || 0,
            migrationFromDefaultVersion:
                Number(raw.migrationFromDefaultVersion) || 0,
            migrationFromTemplateVersion:
                Number(raw.migrationFromTemplateVersion) || 0,
            migrationAt: Number(raw.migrationAt) || 0,
            templates: {}
        };
        EXAM_APPLICATION_PAGE_DEFINITIONS.forEach(function (definition) {
            const type = definition.type;
            const defaultElements = defaults.templates[type].elements;
            const rawTemplate = raw.templates && raw.templates[type];
            const rawElements = Array.isArray(rawTemplate)
                ? rawTemplate
                : rawTemplate && Array.isArray(rawTemplate.elements)
                    ? rawTemplate.elements
                    : [];
            const rawById = {};
            rawElements.slice(0, 200).forEach(function (element) {
                if (!element || !element.id || rawById[element.id]) return;
                rawById[element.id] = element;
            });
            const elements = defaultElements.map(function (defaultElement) {
                return examNormalizeMappingElement(
                    Object.assign({}, defaultElement, rawById[defaultElement.id] || {}),
                    defaultElement
                );
            });
            rawElements.forEach(function (element) {
                if (
                    !element || !element.id ||
                    defaultElements.some(function (item) {
                        return item.id === element.id;
                    }) ||
                    elements.some(function (item) {
                        return item.id === element.id;
                    }) ||
                    !element.custom || elements.length >= 200
                ) return;
                elements.push(examNormalizeMappingElement(element, null));
            });
            normalized.templates[type] = { elements: elements };
        });
        return normalized;
    }

    function examMappingStorageKey(templateStyle) {
        return examNormalizeTemplateStyle(templateStyle) === 'traditional'
            ? EXAM_APPLICATION_TRADITIONAL_MAPPING_STORAGE_KEY
            : EXAM_APPLICATION_MAPPING_STORAGE_KEY;
    }

    function examMappingRollbackStorageKey(templateStyle) {
        return examNormalizeTemplateStyle(templateStyle) === 'traditional'
            ? EXAM_APPLICATION_TRADITIONAL_MAPPING_ROLLBACK_KEY
            : EXAM_APPLICATION_MAPPING_ROLLBACK_KEY;
    }

    function examLoadMappingConfig(templateStyle) {
        const style = examNormalizeTemplateStyle(templateStyle);
        const storageKey = examMappingStorageKey(style);
        const raw = examReadJson(storageKey, null);
        if (!raw || typeof raw !== 'object') {
            return examDefaultMappingConfig(style);
        }
        const versions = examMappingStyleVersions(style);
        const previousDefaultVersion = Number(raw.defaultVersion) || 1;
        const previousTemplateVersion = Number(raw.templateVersion) || 1;
        const requiresMigration =
            previousDefaultVersion < versions.defaultVersion ||
            previousTemplateVersion < versions.templateVersion;
        const normalized = examNormalizeMappingConfig(raw, style);
        if (!requiresMigration) return normalized;

        if (
            style === 'modern' &&
            !examReadJson(EXAM_APPLICATION_MAPPING_MIGRATION_BACKUP_KEY, null)
        ) {
            examWriteJson(
                EXAM_APPLICATION_MAPPING_MIGRATION_BACKUP_KEY,
                raw
            );
        }
        normalized.migrationFromDefaultVersion = previousDefaultVersion;
        normalized.migrationFromTemplateVersion = previousTemplateVersion;
        normalized.migrationAt = Date.now();
        examWriteJson(storageKey, normalized);
        return normalized;
    }

    function examSaveMappingConfig(config, templateStyle) {
        const style = examNormalizeTemplateStyle(
            templateStyle || config && config.templateStyle
        );
        const storageKey = examMappingStorageKey(style);
        const rollbackKey = examMappingRollbackStorageKey(style);
        const normalized = examNormalizeMappingConfig(config, style);
        const previous = examReadJson(storageKey, null);
        examWriteJson(
            rollbackKey,
            previous
                ? examNormalizeMappingConfig(previous, style)
                : examDefaultMappingConfig(style)
        );
        normalized.customized = true;
        normalized.updatedAt = Date.now();
        examWriteJson(storageKey, normalized);
        return normalized;
    }

    function examResolveObjectPath(objectValue, pathValue) {
        return String(pathValue || '').split('.').reduce(
            function (current, key) {
                return current && current[key] !== undefined
                    ? current[key]
                    : '';
            },
            objectValue
        );
    }

    function examResolveMappingSource(source, state, fixed, type) {
        const value = String(source || '');
        if (value.startsWith('patient.')) {
            return examResolveObjectPath(state.patient, value.slice(8));
        }
        if (value.startsWith('clinical.')) {
            return examResolveObjectPath(state.clinical, value.slice(9));
        }
        if (value.startsWith('fixed.')) {
            return examResolveObjectPath(fixed, value.slice(6));
        }
        if (value.startsWith('form.')) {
            return examResolveObjectPath(
                state.forms[examFormTypeForPage(type)] || {},
                value.slice(5)
            );
        }
        if (value === 'computed.department') {
            return examPreferredDepartment(state.patient, fixed);
        }
        if (value === 'computed.ward') {
            return examPreferredWard(state.patient, fixed);
        }
        if (value === 'computed.history') {
            return examHistoryText(state.clinical);
        }
        if (value === 'computed.hospitalDepartment') {
            return [
                fixed.hospital,
                examPreferredDepartment(state.patient, fixed)
            ].filter(Boolean).join(' ');
        }
        if (value === 'computed.applicationDateTime') {
            return [fixed.applicationDate, fixed.applicationTime]
                .filter(Boolean).join(' ');
        }
        if (value === 'computed.applicationDateSpaced') {
            return String(fixed.applicationDate || '').replace(/-/g, '  ');
        }
        if (value === 'computed.applicationDateZh') {
            const dateText = String(fixed.applicationDate || '');
            const matched = dateText.match(/^(\d{4})-(\d{2})-(\d{2})$/);
            return matched
                ? matched[1] + '年' + matched[2] + '月' + matched[3] + '日'
                : dateText;
        }
        if (value === 'computed.mrConsentText' || value === 'computed.contrastConsentText') {
            const form = state.forms.mr || {};
            const choice = form[value === 'computed.mrConsentText' ? 'safetyConsent' : 'contrastConsent'];
            return choice === 'yes' ? '同意' : choice === 'no' ? '不同意' : '';
        }
        const consentDatePart = value.match(/^computed\.(mr|contrast)Consent(Year|Month|Day)$/);
        if (consentDatePart) {
            const form = state.forms.mr || {};
            const dateText = String(form[
                consentDatePart[1] === 'mr' ? 'safetyConsentDate' : 'contrastConsentDate'
            ] || '');
            const date = dateText.match(/^(\d{4})-(\d{2})-(\d{2})$/);
            if (!date) return '';
            const index = { Year: 1, Month: 2, Day: 3 }[consentDatePart[2]];
            return index === 1 ? date[index] : String(Number(date[index]));
        }
        if (value === 'computed.examinationProjection') {
            const form = state.forms[type] || {};
            return [form.examination, form.projection]
                .filter(Boolean).join('；');
        }
        return '';
    }

    function examMappingPixelBox(element) {
        return {
            x: element.x * EXAM_APPLICATION_PAGE_WIDTH,
            y: element.y * EXAM_APPLICATION_PAGE_HEIGHT,
            width: element.width * EXAM_APPLICATION_PAGE_WIDTH,
            height: Math.max(
                18,
                element.lineHeight *
                    (element.mode === 'wrapped' ? element.maxLines : 1)
            )
        };
    }

    function examConstrainMappingBounds(element) {
        element.x = examClamp(element.x, 0, 1 - 0.008, 0);
        element.width = examClamp(
            element.width,
            0.008,
            Math.max(0.008, 1 - element.x),
            Math.min(0.22, 1 - element.x)
        );
        if (element.mode === 'wrapped') {
            element.maxLines = Math.min(
                element.maxLines,
                Math.max(
                    1,
                    Math.floor(
                        EXAM_APPLICATION_PAGE_HEIGHT / element.lineHeight
                    )
                )
            );
        }
        const height = Math.max(
            18,
            element.lineHeight *
                (element.mode === 'wrapped' ? element.maxLines : 1)
        );
        element.y = examClamp(
            element.y,
            0,
            Math.max(0, 1 - height / EXAM_APPLICATION_PAGE_HEIGHT),
            0
        );
        return element;
    }

    function examCalibrationFocusPage(modal) {
        const page = modal.querySelector('.exam-calibration-page');
        if (!page) return;
        try {
            page.focus({ preventScroll: true });
        } catch (error) {
            page.focus();
        }
    }

