    /*
     * v12.34.122：导入责任医师名单采用两级名单缓存。
     * 1. roundBookDrgRosterImportSnapshotCache：当前页面内存一级缓存；
     * 2. ROUND_BOOK_8997_ROSTER_CACHE_GM_KEY：8997标准化名单的GM持久二级缓存。
     * 与责任医师自动同步的8997 30秒短缓存完全分离。
     */
    let roundBookDrgRosterImportSnapshotCache = null;

    function roundBookReadPersistent8997RosterSnapshot() {
        try {
            if (typeof GM_getValue !== 'function') return null;
            let value = GM_getValue(
                ROUND_BOOK_8997_ROSTER_CACHE_GM_KEY,
                null
            );
            if (typeof value === 'string') {
                try {
                    value = JSON.parse(value);
                } catch (error) {
                    return null;
                }
            }
            if (!value || typeof value !== 'object' || Array.isArray(value)) {
                return null;
            }
            const snapshot =
                value.snapshot && typeof value.snapshot === 'object'
                    ? value.snapshot
                    : value;
            if (
                String(snapshot.sourceType || '') !== '8997' ||
                !Array.isArray(snapshot.patients) ||
                !snapshot.patients.length
            ) {
                return null;
            }
            const patients = snapshot.patients
                .map(function (patient) {
                    if (!patient || typeof patient !== 'object') return null;
                    const admissionNo = roundBookCleanAdmissionNo(
                        patient.admissionNo || ''
                    );
                    const name = roundBookCleanName(patient.name || '');
                    if (!admissionNo && !name) return null;
                    return {
                        admissionNo: admissionNo,
                        name: name,
                        bedNo: roundBookCleanBed(patient.bedNo || ''),
                        sex: /女/.test(String(patient.sex || ''))
                            ? '女'
                            : /男/.test(String(patient.sex || ''))
                                ? '男'
                                : '',
                        age: String(patient.age || '')
                            .replace(/[^0-9]/g, '')
                            .slice(0, 3),
                        admissionDate: roundBookOneLine(
                            patient.admissionDate || ''
                        ),
                        responsibleDoctor: roundBookClip(
                            patient.responsibleDoctor || '',
                            ROUND_BOOK_MAX_SHORT_TEXT
                        ),
                        hasResponsibleDoctor: true,
                        status: 'ward',
                        _roundBook8997: true
                    };
                })
                .filter(Boolean);
            if (!patients.length) return null;
            return {
                sourceLabel: '8997医疗管理系统缓存名单',
                sourceType: '8997',
                cacheMode: 'gm-persistent',
                capturedAt: roundBookOneLine(
                    snapshot.capturedAt || value.capturedAt || value.savedAt || ''
                ),
                patients: patients
            };
        } catch (error) {
            return null;
        }
    }

    function roundBookWritePersistent8997RosterSnapshot(snapshot) {
        try {
            if (
                typeof GM_setValue !== 'function' ||
                !snapshot ||
                String(snapshot.sourceType || '') !== '8997' ||
                !Array.isArray(snapshot.patients) ||
                !snapshot.patients.length
            ) {
                return false;
            }
            const patients = snapshot.patients
                .map(function (patient) {
                    if (!patient || typeof patient !== 'object') return null;
                    const admissionNo = roundBookCleanAdmissionNo(
                        patient.admissionNo || ''
                    );
                    const name = roundBookCleanName(patient.name || '');
                    if (!admissionNo && !name) return null;
                    return {
                        admissionNo: admissionNo,
                        name: name,
                        bedNo: roundBookCleanBed(patient.bedNo || ''),
                        sex: /女/.test(String(patient.sex || ''))
                            ? '女'
                            : /男/.test(String(patient.sex || ''))
                                ? '男'
                                : '',
                        age: String(patient.age || '')
                            .replace(/[^0-9]/g, '')
                            .slice(0, 3),
                        admissionDate: roundBookOneLine(
                            patient.admissionDate || ''
                        ),
                        responsibleDoctor: roundBookClip(
                            patient.responsibleDoctor || '',
                            ROUND_BOOK_MAX_SHORT_TEXT
                        ),
                        hasResponsibleDoctor: true,
                        status: 'ward',
                        _roundBook8997: true
                    };
                })
                .filter(Boolean);
            if (!patients.length) return false;
            GM_setValue(
                ROUND_BOOK_8997_ROSTER_CACHE_GM_KEY,
                {
                    schemaVersion: ROUND_BOOK_8997_ROSTER_CACHE_SCHEMA_VERSION,
                    savedAt: new Date().toISOString(),
                    snapshot: {
                        sourceLabel: '8997医疗管理系统实时名单',
                        sourceType: '8997',
                        capturedAt: roundBookOneLine(
                            snapshot.capturedAt || new Date().toISOString()
                        ),
                        patients: patients
                    }
                }
            );
            return true;
        } catch (error) {
            console.warn('[查房本8997名单缓存] GM持久化失败：', error);
            return false;
        }
    }
    let roundBookLastStore = null;
    let roundBookBatchAbort = false;
    let roundBookActiveModal = null;

    function roundBookResetAbort(modal) {
        roundBookBatchAbort = false;
        if (modal) modal._roundBookAbortRequested = false;
    }

    function roundBookAbortRequested(modal) {
        /*
         * v12.34.42：独立“基线数据”模块的LIS/PACS接口任务不属于查房本同步。
         * 使用专用请求上下文时，只响应该任务自己的中止标记，彻底隔离
         * 查房本工具栏“中止”留下的全局roundBookBatchAbort状态。
         */
        if (modal && modal._roundBookIgnoreGlobalAbort === true) {
            return Boolean(modal._roundBookAbortRequested);
        }
        return Boolean(
            roundBookBatchAbort ||
            (modal && modal._roundBookAbortRequested)
        );
    }

    function roundBookRequestAbort(modal) {
        roundBookBatchAbort = true;
        if (modal) modal._roundBookAbortRequested = true;
        roundBookSetStatus(
            modal,
            '已请求中止当前同步/读取任务；正在执行的单次网络请求完成后将停止后续步骤。',
            'warn'
        );
        roundBookRender(modal);
    }

    function roundBookThrowIfAborted(modal) {
        if (roundBookAbortRequested(modal)) {
            const error = new Error('同步已由用户中止');
            error.name = 'RoundBookAbortError';
            throw error;
        }
    }
    let roundBookMobileOhaAutoSyncTimer = null;
    let roundBookMobileOhaUploadBusy = false;
    let roundBookMobileOhaAutoSyncBlocked = false;
    const ROUND_BOOK_MOBILE_OHA_AUTO_SYNC_DELAY = 15000;

    /*
     * v12.34.22：查房本标签页实时同步。
     * v12.34.92：持久化写入前再读取GM最新整表并做updatedAt合并。
     *
     * 1. BroadcastChannel负责同源标签页之间的即时单元格补丁与整表通知；
     * 2. localStorage的storage事件作为持久化后的整表同步与兼容兜底；
     * 3. 远端标签页更新只刷新当前标签页内存/界面，不再次调用roundBookSaveStore，
     *    因此不会形成广播回环，也不会让每个标签页重复上传掌上OHA；
     * 4. 当前标签页存在450ms待保存编辑时，收到整表更新会先做记录级/每日数据级合并；
     * 5. 无论是否收到实时广播，本标签页真正写GM之前都会再次读取GM最新整表并合并，
     *    避免休眠/长时间未刷新的旧标签页把其他标签页较新内容整体覆盖回旧版本。
     */
    const ROUND_BOOK_TAB_SYNC_CHANNEL_NAME =
        'medicalPatientRoundBookRealtimeSyncV1';
    const ROUND_BOOK_TAB_SYNC_SESSION_KEY =
        'medicalPatientRoundBookTabInstanceIdV1';
    let roundBookTabSyncChannel = null;
    let roundBookTabSyncReady = false;
    let roundBookTabSyncCounter = 0;
    const roundBookTabSyncSeenEvents = new Set();

    /*
     * v12.34.92：写前合并以“并集”为基础，因此显式删除/身份重键必须
     * 单独记录旧键，待下一次持久化成功后再清除，避免合并把旧键重新带回。
     */
    const roundBookPendingDeletedRecordKeys = new Set();
    /*
     * v12.34.94：筛选分组删除同样需要跨“写前并集”保护。
     * 当前标签页删除后先记录groupId，待下一次成功持久化时在合并结果中
     * 再次清除该分组及所有患者/每日关联，防止GM旧副本把分组立即复活。
     */
    const roundBookPendingDeletedGroupIds = new Set();

    function roundBookMarkRecordKeyDeleted(recordKey) {
        const key = String(recordKey || '').trim();
        if (key) roundBookPendingDeletedRecordKeys.add(key);
    }

    function roundBookMarkGroupIdDeleted(groupId) {
        const id = String(groupId || '').trim();
        if (id && id !== 'all') {
            roundBookPendingDeletedGroupIds.add(id);
        }
    }

    function roundBookRemoveGroupIdFromStore(store, groupId) {
        const target = store && typeof store === 'object'
            ? store
            : null;
        const id = String(groupId || '').trim();
        if (!target || !id || id === 'all') return false;

        let changed = false;
        if (
            target.groups &&
            Object.prototype.hasOwnProperty.call(target.groups, id)
        ) {
            delete target.groups[id];
            changed = true;
        }

        Object.keys(target.records || {}).forEach(function (key) {
            const record = target.records[key];
            if (!record || typeof record !== 'object') return;

            const beforeRecordGroups = Array.isArray(record.groupIds)
                ? record.groupIds.length
                : 0;
            record.groupIds = (
                Array.isArray(record.groupIds) ? record.groupIds : []
            ).filter(function (value) {
                return String(value) !== id;
            });
            if (record.groupIds.length !== beforeRecordGroups) {
                changed = true;
                record.updatedAt = Date.now();
            }

            Object.keys(record.daily || {}).forEach(function (dateKey) {
                const daily = record.daily[dateKey];
                if (!daily || !Array.isArray(daily.groupIds)) return;
                const before = daily.groupIds.length;
                daily.groupIds = daily.groupIds.filter(function (value) {
                    return String(value) !== id;
                });
                if (daily.groupIds.length !== before) {
                    changed = true;
                    daily.updatedAt = Date.now();
                    record.updatedAt = Date.now();
                }
            });
        });

        return changed;
    }

    function roundBookTabInstanceId() {
        try {
            let value = String(
                sessionStorage.getItem(ROUND_BOOK_TAB_SYNC_SESSION_KEY) || ''
            ).trim();
            if (!value) {
                value = 'tab-' + Date.now().toString(36) + '-' +
                    Math.random().toString(36).slice(2, 10);
                sessionStorage.setItem(ROUND_BOOK_TAB_SYNC_SESSION_KEY, value);
            }
            return value;
        } catch (error) {
            return 'tab-' + Date.now().toString(36) + '-' +
                Math.random().toString(36).slice(2, 10);
        }
    }

    const ROUND_BOOK_TAB_INSTANCE_ID = roundBookTabInstanceId();

    function roundBookTabSyncEventId(kind) {
        roundBookTabSyncCounter += 1;
        return ROUND_BOOK_TAB_INSTANCE_ID + ':' +
            String(kind || 'event') + ':' +
            Date.now().toString(36) + ':' +
            roundBookTabSyncCounter.toString(36);
    }

    function roundBookTabSyncRemember(eventId) {
        const key = String(eventId || '').trim();
        if (!key) return false;
        if (roundBookTabSyncSeenEvents.has(key)) return true;
        roundBookTabSyncSeenEvents.add(key);
        while (roundBookTabSyncSeenEvents.size > 240) {
            const first = roundBookTabSyncSeenEvents.values().next();
            if (first.done) break;
            roundBookTabSyncSeenEvents.delete(first.value);
        }
        return false;
    }

    function roundBookPlain(value) {
        return String(value == null ? '' : value)
            .replace(/\u00a0/g, ' ')
            .replace(/\r\n?/g, '\n')
            .trim();
    }

    function roundBookOneLine(value) {
        return roundBookPlain(value)
            .replace(/[\n\t]+/g, ' ')
            .replace(/\s+/g, ' ')
            .trim();
    }

    function roundBookClip(value, maximumLength) {
        const text = roundBookPlain(value);
        const limit = Math.max(
            20,
            Number(maximumLength) || ROUND_BOOK_MAX_LONG_TEXT
        );
        return text.length > limit
            ? text.slice(0, limit)
            : text;
    }

    function roundBookNormalize(value) {
        return roundBookOneLine(value)
            .replace(/[-‐‑‒–—―－﹣]/g, '-')
            .toLowerCase();
    }

    function roundBookToday() {
        const date = new Date();
        const pad = function (number) {
            return String(number).padStart(2, '0');
        };
        return date.getFullYear() + '-' +
            pad(date.getMonth() + 1) + '-' +
            pad(date.getDate());
    }

    function roundBookDateKey(value) {
        const text = String(value || '').trim();
        return /^\d{4}-\d{2}-\d{2}$/.test(text)
            ? text
            : roundBookToday();
    }

    function roundBookDateOnlyUtc(dateKey) {
        const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(
            String(dateKey || '').trim()
        );
        if (!match) return NaN;
        return Date.UTC(
            Number(match[1]),
            Number(match[2]) - 1,
            Number(match[3])
        );
    }

    function roundBookHospitalDay(record, dateKey) {
        const admissionDate = roundBookNormalizeAdmissionDate(
            record && record.admissionDate
        );
        if (!admissionDate) return null;
        const referenceDate = roundBookDateKey(dateKey);
        const start = roundBookDateOnlyUtc(admissionDate);
        const end = roundBookDateOnlyUtc(referenceDate);
        if (!Number.isFinite(start) || !Number.isFinite(end) || end < start) {
            return null;
        }
        return Math.floor((end - start) / 86400000) + 1;
    }

    /*
     * “住院第N天”和病案首页“实际住院N天”不是同一种计数口径。
     * - 在病区的“住院第N天”：入院日算第1天，因此使用日期差 + 1；
     * - 已出区/已归档的“住院共N天”：沿用医学病案实际住院天数口径，
     *   按“出院日 - 入院日”计算；同日入出院按1天。
     */
    function roundBookTotalStayDays(record, dischargeDateKey) {
        const admissionDate = roundBookNormalizeAdmissionDate(
            record && record.admissionDate
        );
        if (!admissionDate) return null;
        const dischargeDate = roundBookDateKey(dischargeDateKey);
        const start = roundBookDateOnlyUtc(admissionDate);
        const end = roundBookDateOnlyUtc(dischargeDate);
        if (!Number.isFinite(start) || !Number.isFinite(end) || end < start) {
            return null;
        }
        return Math.max(1, Math.floor((end - start) / 86400000));
    }

    /*
     * v12.34.36：在病区继续按查房日期动态显示“住院第N天”；
     * 已出区/已归档改为固定“住院共N天”。
     * 固定总天数以该病案号daily中最早出现discharged/archived的日期
     * 作为本次住院出院日，后续日期即使继续沿用已出区或转为已归档，
     * 也始终继承同一个总住院天数，不再随查房日期继续增长。
     */
    function roundBookFirstDischargeDate(record, maximumDateKey) {
        const maximumDate = roundBookDateKey(maximumDateKey);
        const dailyMap = record && record.daily && typeof record.daily === 'object'
            ? record.daily
            : {};
        return Object.keys(dailyMap)
            .filter(function (dateKey) {
                if (!/^\d{4}-\d{2}-\d{2}$/.test(dateKey)) return false;
                if (dateKey > maximumDate) return false;
                const status = roundBookNormalizeStatus(
                    dailyMap[dateKey] && dailyMap[dateKey].status,
                    'ward'
                );
                return status === 'discharged' || status === 'archived';
            })
            .sort()[0] || '';
    }

    function roundBookHospitalDayText(record, dateKey) {
        const referenceDate = roundBookDateKey(dateKey);
        const daily = record && record.daily
            ? record.daily[referenceDate]
            : null;
        const status = roundBookNormalizeStatus(
            daily && daily.status,
            record && record.status
        );

        if (status === 'discharged' || status === 'archived') {
            const dischargeDate =
                roundBookFirstDischargeDate(record, referenceDate) ||
                referenceDate;
            const totalDays = roundBookTotalStayDays(record, dischargeDate);
            return Number.isFinite(totalDays)
                ? '住院共' + totalDays + '天'
                : '住院总天数：—';
        }

        const day = roundBookHospitalDay(record, referenceDate);
        return Number.isFinite(day)
            ? '住院第' + day + '天'
            : '住院天数：—';
    }

    function roundBookDefaultLayout() {
        const widths = {};
        const visibleColumns = {};
        const copyColumns = {};
        const printColumns = {};
        const lockedColumns = {};
        const clearColumns = {};
        ROUND_BOOK_COLUMNS.forEach(function (column) {
            widths[column.key] = column.width;
            visibleColumns[column.key] = true;
            copyColumns[column.key] = column.key !== 'actions';
            printColumns[column.key] = column.key !== 'actions';
            lockedColumns[column.key] = false;
            clearColumns[column.key] = false;
        });
        return {
            widths: widths,
            rowHeights: {},
            sortKey: 'bedNo',
            sortDirection: 'asc',
            visibleColumns: visibleColumns,
            copyColumns: copyColumns,
            printColumns: printColumns,
            lockedColumns: lockedColumns,
            preserveLockedColumnsOnReset: false,
            excludeDiagnosisBasisFromPrint: false,
            showDrgDailyCost: false,
            showResponsibleDoctor: false,
            clearColumns: clearColumns
        };
    }

    function roundBookLoadLayout() {
        const defaults = roundBookDefaultLayout();
        let saved = {};
        try {
            saved = JSON.parse(
                localStorage.getItem(ROUND_BOOK_LAYOUT_STORAGE_KEY) || '{}'
            ) || {};
        } catch (error) {
            saved = {};
        }
        const widths = {};
        ROUND_BOOK_COLUMNS.forEach(function (column) {
            const candidate = Number(
                saved.widths && saved.widths[column.key]
            );
            widths[column.key] = Number.isFinite(candidate)
                ? Math.max(column.minWidth, Math.min(720, Math.round(candidate)))
                : defaults.widths[column.key];
        });
        const rowHeights = {};
        const savedRows = saved.rowHeights && typeof saved.rowHeights === 'object'
            ? saved.rowHeights
            : {};
        Object.keys(savedRows).slice(0, 2000).forEach(function (key) {
            const value = Number(savedRows[key]);
            if (!Number.isFinite(value)) return;
            rowHeights[key] = Math.max(
                ROUND_BOOK_MIN_ROW_HEIGHT,
                Math.min(ROUND_BOOK_AUTO_FIT_MAX_ROW_HEIGHT, Math.round(value))
            );
        });
        const visibleColumns = {};
        const copyColumns = {};
        const printColumns = {};
        const lockedColumns = {};
        const clearColumns = {};
        ROUND_BOOK_COLUMNS.forEach(function (column) {
            visibleColumns[column.key] = saved.visibleColumns &&
                typeof saved.visibleColumns[column.key] === 'boolean'
                ? saved.visibleColumns[column.key]
                : defaults.visibleColumns[column.key];
            copyColumns[column.key] = saved.copyColumns &&
                typeof saved.copyColumns[column.key] === 'boolean'
                ? saved.copyColumns[column.key]
                : defaults.copyColumns[column.key];
            printColumns[column.key] = saved.printColumns &&
                typeof saved.printColumns[column.key] === 'boolean'
                ? saved.printColumns[column.key]
                : defaults.printColumns[column.key];
            lockedColumns[column.key] = saved.lockedColumns &&
                typeof saved.lockedColumns[column.key] === 'boolean'
                ? saved.lockedColumns[column.key]
                : defaults.lockedColumns[column.key];
            clearColumns[column.key] = saved.clearColumns &&
                typeof saved.clearColumns[column.key] === 'boolean'
                ? saved.clearColumns[column.key]
                : defaults.clearColumns[column.key];
        });
        if (!ROUND_BOOK_COLUMNS.some(function (column) {
            return visibleColumns[column.key];
        })) {
            visibleColumns.bedNo = true;
        }
        return {
            widths: widths,
            rowHeights: rowHeights,
            sortKey: saved.sortKey === 'admissionDate'
                ? 'admissionDate'
                : saved.sortKey === 'remainingDays'
                    ? 'remainingDays'
                    : 'bedNo',
            sortDirection: saved.sortDirection === 'desc'
                ? 'desc'
                : 'asc',
            visibleColumns: visibleColumns,
            copyColumns: copyColumns,
            printColumns: printColumns,
            lockedColumns: lockedColumns,
            preserveLockedColumnsOnReset:
                saved.preserveLockedColumnsOnReset === true,
            excludeDiagnosisBasisFromPrint:
                saved.excludeDiagnosisBasisFromPrint === true,
            showDrgDailyCost:
                saved.showDrgDailyCost === true,
            showResponsibleDoctor:
                saved.showResponsibleDoctor === true,
            clearColumns: clearColumns
        };
    }

    function roundBookSaveLayout(modal) {
        if (!modal || !modal._roundBookLayout) return;
        try {
            localStorage.setItem(
                ROUND_BOOK_LAYOUT_STORAGE_KEY,
                JSON.stringify(modal._roundBookLayout)
            );
        } catch (error) {
            // 布局保存失败不影响查房本数据。
        }
    }

    function roundBookRowHeight(modal, key) {
        const layout = modal && modal._roundBookLayout
            ? modal._roundBookLayout
            : roundBookDefaultLayout();
        const value = Number(layout.rowHeights && layout.rowHeights[key]);
        return Number.isFinite(value)
            ? Math.max(ROUND_BOOK_MIN_ROW_HEIGHT, Math.min(ROUND_BOOK_AUTO_FIT_MAX_ROW_HEIGHT, value))
            : ROUND_BOOK_DEFAULT_ROW_HEIGHT;
    }

    function roundBookColumnGroupHtml() {
        return '<colgroup>' + ROUND_BOOK_COLUMNS.map(function (column) {
            return '<col data-round-book-col="' + escapeHtml(column.key) + '">';
        }).join('') + '</colgroup>';
    }

    function roundBookHeaderHtml() {
        return '<tr>' + ROUND_BOOK_COLUMNS.map(function (column) {
            const syncAttributes = column.sync
                ? ' data-round-book-sync-column="' + escapeHtml(column.key) + '"' +
                    ' title="' + escapeHtml(column.syncTitle || ('点击同步“' + column.label + '”')) + '"'
                : '';
            return '<th data-round-book-col="' + escapeHtml(column.key) + '">' +
                '<span class="round-book-th-label' + (column.sync ? ' is-syncable' : '') + '"' +
                    syncAttributes + '>' + escapeHtml(column.label) +
                    (column.sync ? '<span class="round-book-sync-mark">↻</span>' : '') +
                '</span>' +
                '<span class="round-book-col-resizer" data-round-book-col-resize="' +
                    escapeHtml(column.key) + '" title="拖动调整列宽"></span>' +
                '</th>';
        }).join('') + '</tr>';
    }

    function roundBookApplyLayout(modal) {
        if (!modal) return;
        if (!modal._roundBookLayout) {
            modal._roundBookLayout = roundBookLoadLayout();
        }
        const layout = modal._roundBookLayout;
        const table = modal.querySelector('.round-book-table');
        let total = 0;
        let lockedLeft = 0;
        const lockedVisibleKeys = [];

        ROUND_BOOK_COLUMNS.forEach(function (column) {
            const width = Math.max(
                column.minWidth,
                Number(layout.widths[column.key]) || column.width
            );
            const visible = !layout.visibleColumns ||
                layout.visibleColumns[column.key] !== false;
            const locked = visible && layout.lockedColumns &&
                layout.lockedColumns[column.key] === true;

            layout.widths[column.key] = Math.round(width);
            if (visible) total += Math.round(width);

            modal.querySelectorAll(
                '[data-round-book-col="' + column.key + '"]'
            ).forEach(function (element) {
                element.style.display = visible ? '' : 'none';
            });

            const col = modal.querySelector(
                'col[data-round-book-col="' + column.key + '"]'
            );
            if (col) col.style.width = visible ? Math.round(width) + 'px' : '0px';

            modal.querySelectorAll(
                'th[data-round-book-col="' + column.key + '"],td[data-round-book-col="' + column.key + '"]'
            ).forEach(function (element) {
                element.removeAttribute('data-round-book-locked');
                element.removeAttribute('data-round-book-locked-last');
                element.style.left = '';
                element.style.zIndex = '';
                if (element.tagName === 'TD') {
                    element.style.position = '';
                }
            });

            if (locked) {
                lockedVisibleKeys.push(column.key);
                modal.querySelectorAll(
                    'th[data-round-book-col="' + column.key + '"],td[data-round-book-col="' + column.key + '"]'
                ).forEach(function (element) {
                    element.setAttribute('data-round-book-locked', '1');
                    element.style.position = 'sticky';
                    element.style.left = lockedLeft + 'px';
                    element.style.zIndex = element.tagName === 'TH' ? '12' : '4';
                });
                lockedLeft += Math.round(width);
            }
        });

        if (lockedVisibleKeys.length) {
            const lastLockedKey = lockedVisibleKeys[lockedVisibleKeys.length - 1];
            modal.querySelectorAll(
                'th[data-round-book-col="' + lastLockedKey + '"],td[data-round-book-col="' + lastLockedKey + '"]'
            ).forEach(function (element) {
                element.setAttribute('data-round-book-locked-last', '1');
            });
        }

        if (table) {
            table.style.width = total + 'px';
            table.style.minWidth = total + 'px';
        }
        modal.querySelectorAll('tr[data-round-book-row]').forEach(function (row) {
            const key = row.getAttribute('data-round-book-row') || '';
            row.style.setProperty(
                '--round-book-row-height',
                roundBookRowHeight(modal, key) + 'px'
            );
        });
        const sortKey = modal.querySelector('.round-book-sort-key');
        const sortDirection = modal.querySelector('.round-book-sort-direction');
        if (sortKey) sortKey.value = layout.sortKey;
        if (sortDirection) sortDirection.value = layout.sortDirection;
    }

    function roundBookResetLayout(modal) {
        const previousLayout = modal && modal._roundBookLayout
            ? modal._roundBookLayout
            : roundBookLoadLayout();
        const preserveLockedColumns =
            previousLayout.preserveLockedColumnsOnReset === true;
        const preservedLockedColumns = preserveLockedColumns
            ? Object.assign({}, previousLayout.lockedColumns || {})
            : null;
        const nextLayout = roundBookDefaultLayout();

        if (preserveLockedColumns) {
            ROUND_BOOK_COLUMNS.forEach(function (column) {
                nextLayout.lockedColumns[column.key] =
                    preservedLockedColumns &&
                    preservedLockedColumns[column.key] === true;
            });
            nextLayout.preserveLockedColumnsOnReset = true;
        }

        modal._roundBookLayout = nextLayout;
        roundBookSaveLayout(modal);
        roundBookRender(modal);
        roundBookSetStatus(
            modal,
            preserveLockedColumns
                ? '已恢复查房本默认列宽、默认行高、全部列显示、默认复制列、默认打印列和床号升序；当前锁定列已保留。'
                : '已恢复查房本默认列宽、默认行高、全部列显示、取消全部锁定、默认复制列、默认打印列和床号升序。',
            'ok'
        );
    }


    /*
     * v12.34.1：按当前可见内容自动适应每一行高度。
     *
     * 仅处理当前筛选后真正显示的患者行；隐藏列不会参与测量。
     * 从最小行高重新计算，逐轮读取 textarea / 操作区的 scrollHeight，
     * 直到全部内容完整展开，不再需要行内纵向滚动条。
     * 自动适应可突破手工拖动的680px上限，但仍设置50000px安全上限，
     * 以覆盖查房本单元格允许的极长文本，同时避免异常DOM造成无限放大。
     */
    function roundBookAutoFitRowHeights(modal) {
        if (!modal) return 0;
        if (!modal._roundBookLayout) {
            modal._roundBookLayout = roundBookLoadLayout();
        }
        if (!modal._roundBookLayout.rowHeights ||
            typeof modal._roundBookLayout.rowHeights !== 'object') {
            modal._roundBookLayout.rowHeights = {};
        }

        const rows = Array.from(
            modal.querySelectorAll('tr[data-round-book-row]')
        ).filter(function (row) {
            return row.isConnected && row.getClientRects().length > 0;
        });

        if (!rows.length) {
            roundBookSetStatus(
                modal,
                '当前筛选结果没有可适应行高的患者。',
                'warn'
            );
            return 0;
        }

        let adjustedCount = 0;
        let tallestHeight = 0;
        let unresolvedCount = 0;

        rows.forEach(function (row) {
            const key = row.getAttribute('data-round-book-row') || '';
            if (!key) return;

            let height = ROUND_BOOK_MIN_ROW_HEIGHT;
            row.style.setProperty('--round-book-row-height', height + 'px');

            for (let pass = 0; pass < 28; pass += 1) {
                /* 强制浏览器完成本轮布局后再测量真实溢出量。 */
                void row.offsetHeight;

                const scrollables = Array.from(
                    row.querySelectorAll(
                        'textarea.round-book-cell, .round-book-row-actions'
                    )
                ).filter(function (element) {
                    return element.getClientRects().length > 0 &&
                        element.clientHeight > 0;
                });

                let hasOverflow = false;
                let requiredHeight = height;

                scrollables.forEach(function (element) {
                    const clientHeight = Math.max(1, element.clientHeight);
                    const scrollHeight = Math.max(clientHeight, element.scrollHeight);
                    if (scrollHeight <= clientHeight + 2) return;

                    hasOverflow = true;
                    const ratio = scrollHeight / clientHeight;
                    requiredHeight = Math.max(
                        requiredHeight,
                        Math.ceil(height * ratio + 16),
                        height + (scrollHeight - clientHeight) + 16
                    );
                });

                if (!hasOverflow) break;

                const nextHeight = Math.min(
                    ROUND_BOOK_AUTO_FIT_MAX_ROW_HEIGHT,
                    Math.max(height + 16, requiredHeight)
                );
                if (nextHeight <= height) break;

                height = nextHeight;
                row.style.setProperty(
                    '--round-book-row-height',
                    Math.round(height) + 'px'
                );
            }

            /* 像素取整可能残留1~2px溢出，再做补偿循环。 */
            for (let finalPass = 0; finalPass < 6; finalPass += 1) {
                void row.offsetHeight;
                const overflowing = Array.from(
                    row.querySelectorAll(
                        'textarea.round-book-cell, .round-book-row-actions'
                    )
                ).filter(function (element) {
                    return element.getClientRects().length > 0 &&
                        element.clientHeight > 0 &&
                        element.scrollHeight > element.clientHeight + 2;
                });

                if (!overflowing.length) break;
                if (height >= ROUND_BOOK_AUTO_FIT_MAX_ROW_HEIGHT) break;

                let extra = 18;
                overflowing.forEach(function (element) {
                    extra = Math.max(
                        extra,
                        element.scrollHeight - element.clientHeight + 18
                    );
                });
                height = Math.min(
                    ROUND_BOOK_AUTO_FIT_MAX_ROW_HEIGHT,
                    Math.ceil(height + extra)
                );
                row.style.setProperty(
                    '--round-book-row-height',
                    Math.round(height) + 'px'
                );
            }

            void row.offsetHeight;
            const unresolved = Array.from(
                row.querySelectorAll(
                    'textarea.round-book-cell, .round-book-row-actions'
                )
            ).filter(function (element) {
                return element.getClientRects().length > 0 &&
                    element.clientHeight > 0;
            }).some(function (element) {
                return element.scrollHeight > element.clientHeight + 2;
            });

            if (unresolved) unresolvedCount += 1;

            /* 无溢出时复位滚动位置，确保看到内容起始处。 */
            if (!unresolved) {
                row.querySelectorAll(
                    'textarea.round-book-cell, .round-book-row-actions'
                ).forEach(function (element) {
                    try { element.scrollTop = 0; } catch (error) {}
                });
            }

            modal._roundBookLayout.rowHeights[key] = Math.round(height);
            tallestHeight = Math.max(tallestHeight, Math.round(height));
            adjustedCount += 1;
        });

        roundBookSaveLayout(modal);
        roundBookApplyLayout(modal);

        roundBookSetStatus(
            modal,
            unresolvedCount
                ? '已自动适应当前' + adjustedCount + '行；其中' +
                    unresolvedCount + '行达到50000px安全上限仍存在异常溢出，请检查该行内容。'
                : '已自动适应当前' + adjustedCount +
                    '行，所有可见行的多行文本框和操作区均已完整展开，无需纵向滚动；最高行约' +
                    tallestHeight + 'px。',
            unresolvedCount ? 'warn' : 'ok'
        );

        return adjustedCount;
    }

    function roundBookCleanBed(value) {
        const compact = roundBookOneLine(value)
            .replace(/^(?:床号|床位|病床)\s*[：:]?\s*/, '')
            .replace(/[-‐‑‒–—―－﹣]/g, '-')
            .replace(/\s+/g, '')
            .replace(/床(?:位)?$/, '');
        const match = compact.match(
            /^([A-Za-z0-9]{1,8}(?:-[A-Za-z0-9]{1,8}){0,3})$/
        );
        return match ? match[1] : '';
    }

    function roundBookCleanName(value) {
        return roundBookOneLine(value)
            .replace(/^(?:患者姓名|病人姓名|姓名)\s*[：:]?\s*/, '')
            .replace(/[^\u3400-\u9fff·]/g, '')
            .slice(0, 12);
    }

    function roundBookCleanAdmissionNo(value) {
        const text = roundBookOneLine(value)
            .replace(/^(?:住院号|病案号|住院病案号)\s*[：:]?\s*/, '')
            .replace(/[^A-Za-z0-9-]/g, '');
        return /^[A-Za-z0-9-]{4,30}$/.test(text)
            ? text
            : '';
    }


    function roundBookNumber(value) {
        const number = Number(
            String(
                value == null
                    ? ''
                    : value
            )
                .replace(/,/g, '')
                .replace(/[^\d.-]/g, '')
        );

        return Number.isFinite(number)
            ? number
            : NaN;
    }

    function roundBookFormatMoney(value) {
        if (!roundBookPlain(value)) return '';
        const number =
            roundBookNumber(value);

        return Number.isFinite(number)
            ? number.toLocaleString(
                'zh-CN',
                {
                    minimumFractionDigits: 0,
                    maximumFractionDigits: 2
                }
            )
            : '';
    }

    function roundBookDrgBridge() {
        const pageWindow =
            typeof unsafeWindow !== 'undefined'
                ? unsafeWindow
                : window;

        try {
            const bridge =
                pageWindow[
                    ROUND_BOOK_DRG_SNAPSHOT_BRIDGE_NAME
                ];

            return (
                bridge &&
                typeof bridge.getPatient ===
                    'function'
            )
                ? bridge
                : null;
        } catch (error) {
            return null;
        }
    }

    function roundBookReadInpatientSummaryDrgMap() {
        try {
            const raw = localStorage.getItem(
                ROUND_BOOK_INPATIENT_SUMMARY_DRG_MAP_STORAGE_KEY
            );
            if (!raw) return {};
            const parsed = JSON.parse(raw);
            return parsed && typeof parsed === 'object' && !Array.isArray(parsed)
                ? parsed
                : {};
        } catch (error) {
            return {};
        }
    }

    function roundBookReadInpatientSummaryDrgConfigs() {
        try {
            const raw = localStorage.getItem(
                ROUND_BOOK_INPATIENT_SUMMARY_DRG_CONFIG_STORAGE_KEY
            );
            if (!raw) return {};
            if (roundBookReadInpatientSummaryDrgConfigs._raw === raw) return roundBookReadInpatientSummaryDrgConfigs._value;
            const parsed = JSON.parse(raw);
            const value = parsed && typeof parsed === 'object' && !Array.isArray(parsed)
                ? parsed
                : {};
            roundBookReadInpatientSummaryDrgConfigs._raw = raw;
            roundBookReadInpatientSummaryDrgConfigs._value = value;
            return value;
        } catch (error) {
            return {};
        }
    }

    function roundBookReadInpatientSummarySharedDrgCache() {
        try {
            const raw = localStorage.getItem(
                ROUND_BOOK_DRG_SHARED_CACHE_STORAGE_KEY
            );
            if (!raw) return { records: [], groupProfiles: [] };
            if (roundBookReadInpatientSummarySharedDrgCache._raw === raw) return roundBookReadInpatientSummarySharedDrgCache._value;
            const parsed = JSON.parse(raw);
            if (!parsed || typeof parsed !== 'object') {
                return { records: [], groupProfiles: [] };
            }
            const value = {
                records: Array.isArray(parsed.records) ? parsed.records : [],
                groupProfiles: Array.isArray(parsed.groupProfiles)
                    ? parsed.groupProfiles
                    : []
            };
            roundBookReadInpatientSummarySharedDrgCache._raw = raw;
            roundBookReadInpatientSummarySharedDrgCache._value = value;
            return value;
        } catch (error) {
            return { records: [], groupProfiles: [] };
        }
    }

    function roundBookInpatientSummaryDrgKey(value) {
        const raw = roundBookPlain(value).toUpperCase();
        if (!raw) return '';
        const match = raw.match(/\b[A-Z]{1,4}\d{1,4}[A-Z]?\b/);
        return match ? match[0] : raw;
    }

    /* v12.34.124.15：费用按当前DRG分组独立解析，空值不能转换成零。 */
    function roundBookDrgNumber(value) {
        if (typeof value !== 'number' && typeof value !== 'string') return NaN;
        const text = String(value).trim()
            .replace(/[,，\s￥¥]/g, '')
            .replace(/元(?:\/天)?$/, '');
        if (!text) return NaN;
        const number = Number(text);
        return Number.isFinite(number) ? number : NaN;
    }

    function roundBookDrgFinancialValues(record, baseline) {
        const group = roundBookPlain(record && record.drgGroup);
        const key = roundBookInpatientSummaryDrgKey(group);
        if (!key) {
            return { allocationFee: '', dailyCost: '', allocationSource: '', dailyCostSource: '' };
        }
        const profile = roundBookInpatientSummaryGroupProfile(group);
        const source = baseline && typeof baseline === 'object' ? baseline : null;
        const matchingBaseline = source &&
            roundBookInpatientSummaryDrgKey(source.drgGroup) === key;
        const savedQuota = roundBookDrgNumber(matchingBaseline
            ? source.allocationFee : record && record.drgAllocationFee);
        const savedDaily = roundBookDrgNumber(matchingBaseline
            ? source.dailyCost : record && record.drgDailyCost);
        const hasProfileQuota = profile && Number.isFinite(profile.quota) && profile.quota >= 0;
        const hasProfileDaily = profile && profile.dailyCostSource &&
            Number.isFinite(profile.dailyCost) && profile.dailyCost > 0;
        const quota = hasProfileQuota ? profile.quota : savedQuota;
        const daily = hasProfileDaily ? profile.dailyCost
            : Number.isFinite(savedDaily) && savedDaily > 0 ? savedDaily
                : Number.isFinite(quota) && quota >= 0
                    ? ROUND_BOOK_INPATIENT_SUMMARY_DEFAULT_DAILY_COST : NaN;
        return {
            allocationFee: Number.isFinite(quota) && quota >= 0 ? String(quota) : '',
            dailyCost: Number.isFinite(daily) && daily > 0 ? String(daily) : '',
            allocationSource: hasProfileQuota ? profile.quotaSource
                : Number.isFinite(savedQuota) && savedQuota >= 0 ? '已保存DRG基线' : '',
            dailyCostSource: hasProfileDaily ? profile.dailyCostSource
                : Number.isFinite(savedDaily) && savedDaily > 0 ? '已保存DRG基线'
                    : Number.isFinite(daily) ? '默认每日花费' : ''
        };
    }

    function roundBookApplyDrgFinancialSettings(record, baseline) {
        if (!record) return [];
        const values = roundBookDrgFinancialValues(record, baseline);
        const changed = [];
        if (roundBookPlain(record.drgAllocationFee) !== values.allocationFee) {
            record.drgAllocationFee = values.allocationFee;
            changed.push('拨付费用');
        }
        if (roundBookPlain(record.drgDailyCost) !== values.dailyCost) {
            record.drgDailyCost = values.dailyCost;
            changed.push('每日花费');
        }
        if (changed.length) record.updatedAt = Date.now();
        return changed;
    }

    function roundBookRefreshDrgConfigurationView() {
        const modal = roundBookActiveModal;
        if (!modal || !modal.classList.contains('is-open') ||
            roundBookStorageLongTaskBusy(modal)) return;
        const state = roundBookTabSyncCaptureView(modal);
        roundBookRender(modal);
        roundBookTabSyncRestoreView(modal, state);
    }

    function roundBookInpatientSummaryGroupProfile(group) {
        const key = roundBookInpatientSummaryDrgKey(group);
        if (!key) return null;
        const configs = roundBookReadInpatientSummaryDrgConfigs();
        const localKey = Object.prototype.hasOwnProperty.call(configs, key) ? key
            : Object.keys(configs).find(function (name) {
                return roundBookInpatientSummaryDrgKey(name) === key;
            });
        const localValue = localKey ? configs[localKey] : null;
        const local = localValue && typeof localValue === 'object' && !Array.isArray(localValue)
            ? localValue : null;
        const shared = roundBookReadInpatientSummarySharedDrgCache();
        const synced = (shared.groupProfiles || []).find(function (item) {
            return roundBookInpatientSummaryDrgKey(
                item && (item.key || item.name || item.group)
            ) === key;
        }) || null;
        const localQuota = roundBookDrgNumber(local && local.quota);
        const syncedQuota = roundBookDrgNumber(synced && synced.quota);
        const localDaily = roundBookDrgNumber(local && local.dailyCost);
        const syncedDaily = roundBookDrgNumber(synced && synced.dailyCost);
        const hasLocalQuota = Number.isFinite(localQuota) && localQuota >= 0;
        const hasSharedQuota = Number.isFinite(syncedQuota) && syncedQuota >= 0;
        const hasLocalDaily = Number.isFinite(localDaily) && localDaily > 0;
        const hasSharedDaily = Number.isFinite(syncedDaily) && syncedDaily > 0;
        return {
            key: key,
            name: roundBookPlain(local && local.groupName) ||
                roundBookPlain(synced && (synced.name || synced.group)) ||
                roundBookPlain(group) || key,
            quota: hasLocalQuota ? localQuota : hasSharedQuota ? syncedQuota : NaN,
            dailyCost: hasLocalDaily ? localDaily : hasSharedDaily ? syncedDaily
                : ROUND_BOOK_INPATIENT_SUMMARY_DEFAULT_DAILY_COST,
            quotaSource: hasLocalQuota ? '住院患者一览DRG预警设置'
                : hasSharedQuota ? 'DRG共享分组字典' : '',
            dailyCostSource: hasLocalDaily ? '住院患者一览DRG预警设置'
                : hasSharedDaily ? 'DRG共享分组字典' : ''
        };
    }

    function roundBookDiagnosisMapCandidates(value) {
        const source = String(value == null ? '' : value)
            .replace(/\r\n?/g, '\n')
            .trim();
        if (!source) return [];

        const result = [];
        const seen = new Set();
        function add(candidate) {
            const current = roundBookPlain(candidate);
            if (!current || seen.has(current)) return;
            seen.add(current);
            result.push(current);
        }

        add(source);
        source.split(/\n+/).forEach(function (line) {
            let current = roundBookPlain(line);
            if (!current) return;
            current = current
                .replace(/^\s*(?:\(?\d+\)?|[一二三四五六七八九十]+)\s*[\.、．\)）:：-]\s*/, '')
                .replace(/^\s*(?:西医诊断|入院诊断|主要诊断|主诊断)\s*[：:]\s*/i, '')
                .trim();
            add(current);
        });
        return result;
    }

    function roundBookReadInpatientSummaryMappedDrg(record, diagnosisOverride) {
        const map = roundBookReadInpatientSummaryDrgMap();
        const normalized = new Map();
        Object.keys(map || {}).forEach(function (key) {
            const diagnosis = roundBookPlain(key);
            const group = roundBookClip(map[key], ROUND_BOOK_MAX_SHORT_TEXT);
            if (diagnosis && roundBookPlain(group) && !normalized.has(diagnosis)) {
                normalized.set(diagnosis, group);
            }
        });
        const candidates = roundBookDiagnosisMapCandidates(
            roundBookPlain(diagnosisOverride) || (record && record.diagnosis)
        );
        for (const candidate of candidates) {
            if (normalized.has(candidate)) {
                return {
                    diagnosis: candidate,
                    drgGroup: normalized.get(candidate)
                };
            }
        }
        return null;
    }

    function roundBookApplyInpatientSummaryDrgMapFallback(
        record,
        diagnosisOverride,
        sourceLabel
    ) {
        if (!record || roundBookPlain(record.drgGroup)) return [];
        const matched = roundBookReadInpatientSummaryMappedDrg(
            record,
            diagnosisOverride
        );
        if (!matched || !roundBookPlain(matched.drgGroup)) return [];

        const changed = [];
        const profile = roundBookInpatientSummaryGroupProfile(
            matched.drgGroup
        );
        const nextGroup = roundBookClip(
            profile && profile.name
                ? profile.name
                : matched.drgGroup,
            ROUND_BOOK_MAX_SHORT_TEXT
        );
        if (
            nextGroup &&
            roundBookPlain(record.drgGroup) !== roundBookPlain(nextGroup)
        ) {
            record.drgGroup = nextGroup;
            changed.push('DRG分组');
        }

        if (profile && Number.isFinite(profile.quota)) {
            const allocation = String(profile.quota);
            if (
                roundBookPlain(record.drgAllocationFee) !==
                roundBookPlain(allocation)
            ) {
                record.drgAllocationFee = allocation;
                changed.push('拨付费用');
            }
        }

        if (profile && Number.isFinite(profile.dailyCost) && profile.dailyCost > 0) {
            const dailyCost = String(profile.dailyCost);
            if (
                roundBookPlain(record.drgDailyCost) !==
                roundBookPlain(dailyCost)
            ) {
                record.drgDailyCost = dailyCost;
                changed.push('每日花费');
            }
        }

        record.drgBaselineSource = roundBookClip(
            sourceLabel || '住院患者一览映射兜底',
            80
        );
        record.drgBaselineUpdatedAt = Date.now();
        record.updatedAt = Date.now();
        return changed;
    }

    function roundBookPatientListWardCode() {
        try {
            const params = new URLSearchParams(location.search || '');
            const fromQuery = roundBookOneLine(
                params.get('bqCode') ||
                params.get('wardCode') ||
                params.get('WardCode') || ''
            );
            if (fromQuery) return fromQuery;
        } catch (error) {}

        const selectors = [
            '[name="bqCode"]', '#bqCode',
            '[name="wardCode"]', '#wardCode',
            '[name="WardCode"]', '#WardCode',
            '[data-bq-code]', '[data-ward-code]'
        ];
        for (const selector of selectors) {
            const element = document.querySelector(selector);
            if (!element) continue;
            const value = roundBookOneLine(
                element.value ||
                element.getAttribute('data-bq-code') ||
                element.getAttribute('data-ward-code') ||
                element.getAttribute('value') || ''
            );
            if (value) return value;
        }
        return ROUND_BOOK_PATIENT_LIST_DEFAULT_WARD_CODE;
    }

    function roundBookPatientListBody(page, wardCode) {
        return [
            'rows=' + encodeURIComponent(ROUND_BOOK_PATIENT_LIST_PAGE_SIZE),
            'page=' + encodeURIComponent(page),
            'bqCode=' + encodeURIComponent(wardCode || ''),
            'ys=',
            'bedCode=',
            'ryrqks=',
            'ryrqjs=',
            'ryrqsort='
        ].join('&');
    }

    function roundBookParsePatientListResponse(responseText) {
        let data = null;
        try {
            data = JSON.parse(responseText || '{}');
        } catch (error) {
            const preview = String(responseText || '').slice(0, 160).toLowerCase();
            throw new Error(
                /<!doctype|<html|login|登录/.test(preview)
                    ? '8003病区患者列表返回登录页'
                    : '8003病区患者列表未返回有效JSON'
            );
        }
        const rows = Array.isArray(data && data.rows)
            ? data.rows.filter(function (item) {
                return item && typeof item === 'object';
            })
            : [];
        return {
            rows: rows,
            totalPages: Math.max(1, Number(data && data.total) || 1)
        };
    }

    function roundBookRequestPatientListPageViaGm(page, wardCode) {
        return new Promise(function (resolve, reject) {
            const url = ROUND_BOOK_PATIENT_LIST_API_URL +
                '?rows=' + encodeURIComponent(ROUND_BOOK_PATIENT_LIST_PAGE_SIZE) +
                '&page=' + encodeURIComponent(page);
            suiteGlobalAiXmlhttpRequest({
                method: 'POST',
                url: url,
                headers: {
                    'Accept': 'application/json, text/javascript, */*; q=0.01',
                    'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8',
                    'X-Requested-With': 'XMLHttpRequest'
                },
                data: roundBookPatientListBody(page, wardCode),
                anonymous: false,
                timeout: 16000,
                onload: function (response) {
                    if (response.status < 200 || response.status >= 300) {
                        reject(new Error('8003病区患者列表HTTP ' + response.status));
                        return;
                    }
                    try {
                        resolve(roundBookParsePatientListResponse(response.responseText));
                    } catch (error) {
                        reject(error);
                    }
                },
                onerror: function () {
                    reject(new Error('8003病区患者列表网络请求失败'));
                },
                ontimeout: function () {
                    reject(new Error('8003病区患者列表请求超时'));
                }
            });
        });
    }

    async function roundBookRequestPatientListPage(page, wardCode) {
        const url = ROUND_BOOK_PATIENT_LIST_API_URL +
            '?rows=' + encodeURIComponent(ROUND_BOOK_PATIENT_LIST_PAGE_SIZE) +
            '&page=' + encodeURIComponent(page);
        let sameOrigin = false;
        try {
            sameOrigin = new URL(url, location.href).origin === location.origin;
        } catch (error) {}

        if (sameOrigin && typeof window.fetch === 'function') {
            const controller = typeof AbortController === 'function'
                ? new AbortController()
                : null;
            const timeout = controller
                ? window.setTimeout(function () { controller.abort(); }, 16000)
                : null;
            try {
                const response = await window.fetch(url, {
                    method: 'POST',
                    credentials: 'include',
                    headers: {
                        'Accept': 'application/json, text/javascript, */*; q=0.01',
                        'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8',
                        'X-Requested-With': 'XMLHttpRequest'
                    },
                    body: roundBookPatientListBody(page, wardCode),
                    signal: controller ? controller.signal : undefined
                });
                if (!response.ok) {
                    throw new Error('HTTP ' + response.status);
                }
                return roundBookParsePatientListResponse(
                    await response.text()
                );
            } catch (error) {
                /* OHA/WebView2同源fetch异常时继续回退GM通道。 */
            } finally {
                if (timeout !== null) window.clearTimeout(timeout);
            }
        }

        return roundBookRequestPatientListPageViaGm(page, wardCode);
    }

    async function roundBookReadPatientListMetadata() {
        const wardCode = roundBookPatientListWardCode();
        const cache = roundBookPatientListMetadataCache;
        const now = Date.now();
        if (
            cache.wardCode === wardCode &&
            Array.isArray(cache.rows) &&
            cache.rows.length &&
            now - cache.fetchedAt < ROUND_BOOK_PATIENT_LIST_CACHE_TTL_MS
        ) {
            return cache.rows;
        }
        if (cache.wardCode === wardCode && cache.promise) {
            return cache.promise;
        }

        const promise = (async function () {
            const first = await roundBookRequestPatientListPage(1, wardCode);
            let rows = first.rows.slice();
            const totalPages = Math.min(
                Math.max(1, first.totalPages),
                20
            );
            for (let page = 2; page <= totalPages; page += 1) {
                const next = await roundBookRequestPatientListPage(page, wardCode);
                rows = rows.concat(next.rows || []);
            }
            roundBookPatientListMetadataCache = {
                wardCode: wardCode,
                fetchedAt: Date.now(),
                rows: rows,
                promise: null
            };
            return rows;
        })();

        roundBookPatientListMetadataCache = {
            wardCode: wardCode,
            fetchedAt: cache.fetchedAt || 0,
            rows: cache.wardCode === wardCode ? (cache.rows || []) : [],
            promise: promise
        };
        try {
            return await promise;
        } catch (error) {
            if (roundBookPatientListMetadataCache.promise === promise) {
                roundBookPatientListMetadataCache.promise = null;
            }
            throw error;
        }
    }

    function roundBookFindPatientListRow(record, rows) {
        const targetNo = roundBookCleanAdmissionNo(record && record.admissionNo);
        if (targetNo) {
            const direct = (rows || []).find(function (item) {
                return roundBookCleanAdmissionNo(
                    item && (item.zyh || item.ZYH || item.admissionNo || item.inpatientNo)
                ) === targetNo;
            });
            if (direct) return direct;
        }

        const targetName = roundBookPlain(record && record.name);
        const targetBed = roundBookPlain(record && record.bedNo)
            .replace(/床$/, '');
        let matches = (rows || []).filter(function (item) {
            const name = roundBookPlain(item && (item.xm || item.XM || item.name));
            const bed = roundBookPlain(item && (item.cwmc || item.CWMC || item.bedNo))
                .replace(/床$/, '');
            return targetName && targetBed && name === targetName && bed === targetBed;
        });
        if (matches.length === 1) return matches[0];
        if (targetName) {
            matches = (rows || []).filter(function (item) {
                return roundBookPlain(item && (item.xm || item.XM || item.name)) === targetName;
            });
            if (matches.length === 1) return matches[0];
        }
        return null;
    }

    async function roundBookRead8003PatientListDiagnosis(record) {
        const rows = await roundBookReadPatientListMetadata();
        const row = roundBookFindPatientListRow(record, rows);
        if (!row) {
            throw new Error('8003病区患者列表未匹配当前患者');
        }
        const diagnosis = roundBookPlain(
            row.zdmc || row.ZDMC || row.diagnosis || ''
        );
        if (!diagnosis) {
            throw new Error('8003病区患者列表未返回可用诊断');
        }
        return diagnosis;
    }


    /* =========================================================
     * v12.34.124.4：同步掌上OHA时，住院页名单优先读取8997实时接口，
     * 无法获取完整名单时回退DRG助手最近提取的页面快照；不改动原DRG业务基线。
     * v12.34.120：8997医疗管理系统实时患者名单。
     * - 同一次8997响应同时服务责任医师同步和“导入DRG助手名单”；
     * - 责任医师字段严格只认attendDoc，空字符串同样是有效值；
     * - 不读取8997的DRG字段，避免改变现有手工DRG/诊断映射业务语义。
     * ========================================================= */
    const ROUND_BOOK_MEDICAL_MANAGEMENT_CACHE_TTL_MS = 30000;

    function roundBookMedicalManagementApiRows(data) {
        if (!data || typeof data !== 'object') return [];
        const candidates = [
            data.data,
            data.rows,
            data.records,
            data.list,
            data.result && data.result.data,
            data.result && data.result.records
        ];
        for (const candidate of candidates) {
            if (Array.isArray(candidate)) {
                return candidate.filter(function (item) {
                    return item && typeof item === 'object';
                });
            }
        }
        return [];
    }

    function roundBookMedicalManagementRequestPatients(forceRefresh) {
        const now = Date.now();
        const cache = roundBookMedicalManagementCache;
        if (
            forceRefresh !== true &&
            Array.isArray(cache.rows) &&
            cache.rows.length &&
            now - cache.fetchedAt <
                ROUND_BOOK_MEDICAL_MANAGEMENT_CACHE_TTL_MS
        ) {
            return Promise.resolve({
                rows: cache.rows,
                total: cache.total || cache.rows.length,
                cached: true
            });
        }
        if (forceRefresh !== true && cache.promise) {
            return cache.promise;
        }

        const auth = roundBookMedicalManagementReadAuth();
        if (!auth || !roundBookPlain(auth.token)) {
            return Promise.reject(
                new Error(
                    '尚未捕获8997认证；请先在8996在院患者/责任医师查询页执行一次查询'
                )
            );
        }

        const payload =
            roundBookMedicalManagementClone(auth.payload) || {};
        payload.pageNum = 1;
        payload.pageSize = 200;
        if (!payload.hospitalArea && auth.hospitalArea) {
            payload.hospitalArea = auth.hospitalArea;
        }

        const promise = new Promise(function (resolve, reject) {
            GM_xmlhttpRequest({
                method: 'POST',
                url: ROUND_BOOK_MEDICAL_MANAGEMENT_API_URL,
                headers: {
                    'Accept': 'application/json, text/plain, */*',
                    'Content-Type': 'application/json;charset=UTF-8',
                    'token': String(auth.token)
                },
                data: JSON.stringify(payload),
                anonymous: true,
                timeout: 16000,
                onload: function (response) {
                    if (
                        response.status === 401 ||
                        response.status === 403
                    ) {
                        reject(
                            new Error(
                                '8997认证失败（HTTP ' +
                                response.status +
                                '），请回8996重新查询刷新token'
                            )
                        );
                        return;
                    }
                    if (
                        response.status < 200 ||
                        response.status >= 300
                    ) {
                        reject(
                            new Error(
                                '8997患者接口HTTP ' +
                                response.status
                            )
                        );
                        return;
                    }
                    let data = null;
                    try {
                        data = JSON.parse(
                            response.responseText || '{}'
                        );
                    } catch (error) {
                        reject(
                            new Error('8997患者接口未返回有效JSON')
                        );
                        return;
                    }
                    const rows =
                        roundBookMedicalManagementApiRows(data);
                    const total =
                        Number(data.total || data.records || rows.length) ||
                        rows.length;
                    if (!rows.length && total > 0) {
                        reject(
                            new Error(
                                '8997返回记录数但未识别到患者数组'
                            )
                        );
                        return;
                    }
                    roundBookMedicalManagementCache = {
                        fetchedAt: Date.now(),
                        rows: rows,
                        total: total,
                        promise: null,
                        error: ''
                    };
                    resolve({
                        rows: rows,
                        total: total,
                        cached: false
                    });
                },
                onerror: function () {
                    reject(new Error('8997跨域请求失败'));
                },
                ontimeout: function () {
                    reject(new Error('8997患者接口请求超时'));
                }
            });
        });

        roundBookMedicalManagementCache = {
            fetchedAt: cache.fetchedAt || 0,
            rows: cache.rows || [],
            total: cache.total || 0,
            promise: promise,
            error: ''
        };

        return promise.catch(function (error) {
            if (roundBookMedicalManagementCache.promise === promise) {
                roundBookMedicalManagementCache.promise = null;
                roundBookMedicalManagementCache.error =
                    String(error && error.message || error || '');
            }
            throw error;
        });
    }

    function roundBookNormalizeMedicalManagementPatient(raw) {
        const source = raw && typeof raw === 'object'
            ? raw
            : {};
        const admissionNo = roundBookCleanAdmissionNo(
            source.mrId ||
            source.MRID ||
            source.zyh ||
            source.ZYH ||
            source.admissionNo ||
            ''
        );
        const name = roundBookCleanName(
            source.name ||
            source.xm ||
            source.XM ||
            ''
        );
        const bedNo = roundBookCleanBed(
            source.bedNumber ||
            source.cwmc ||
            source.CWMC ||
            source.bedNo ||
            ''
        );
        const sexText = roundBookOneLine(
            source.sex ||
            source.gender ||
            source.xb ||
            ''
        );
        const ageText = roundBookOneLine(
            source.age !== undefined
                ? source.age
                : source.patientAge
        );
        const inTime = roundBookOneLine(
            source.inTime ||
            source.admissionTime ||
            source.admissionDate ||
            ''
        );
        const dateMatch = inTime.match(/\d{4}-\d{1,2}-\d{1,2}/);

        if (!admissionNo && !name) return null;

        return {
            admissionNo: admissionNo,
            name: name,
            bedNo: bedNo,
            sex:
                /女/.test(sexText)
                    ? '女'
                    : /男/.test(sexText)
                        ? '男'
                        : '',
            age: ageText
                .replace(/[^0-9]/g, '')
                .slice(0, 3),
            admissionDate: dateMatch ? dateMatch[0] : '',
            responsibleDoctor: roundBookClip(
                source.attendDoc,
                ROUND_BOOK_MAX_SHORT_TEXT
            ),
            hasResponsibleDoctor: true,
            status: 'ward',
            _roundBook8997: true
        };
    }

    function roundBookFindMedicalManagementRawPatient(record, rows) {
        const targetNo = roundBookCleanAdmissionNo(
            record && record.admissionNo
        );
        if (targetNo) {
            const direct = (rows || []).find(function (item) {
                return roundBookCleanAdmissionNo(
                    item && (
                        item.mrId ||
                        item.MRID ||
                        item.zyh ||
                        item.ZYH ||
                        item.admissionNo ||
                        ''
                    )
                ) === targetNo;
            });
            if (direct) return direct;
        }

        const targetName = roundBookCleanName(
            record && record.name
        );
        const targetBed = roundBookCleanBed(
            record && record.bedNo
        );
        const matches = (rows || []).filter(function (item) {
            const itemName = roundBookCleanName(
                item && (item.name || item.xm || item.XM || '')
            );
            const itemBed = roundBookCleanBed(
                item && (
                    item.bedNumber ||
                    item.cwmc ||
                    item.CWMC ||
                    item.bedNo ||
                    ''
                )
            );
            return (
                targetName &&
                targetBed &&
                itemName === targetName &&
                itemBed === targetBed
            );
        });
        return matches.length === 1
            ? matches[0]
            : null;
    }

    function roundBookFindMedicalManagementPatient(record, rows) {
        const raw = roundBookFindMedicalManagementRawPatient(
            record,
            rows
        );
        return raw
            ? roundBookNormalizeMedicalManagementPatient(raw)
            : null;
    }

    async function roundBookTryMedicalManagementPatient(
        record,
        rowsOverride
    ) {
        try {
            const rows = Array.isArray(rowsOverride)
                ? rowsOverride
                : (await roundBookMedicalManagementRequestPatients(false)).rows;
            const patient =
                roundBookFindMedicalManagementPatient(record, rows);
            return {
                available: true,
                matched: Boolean(patient),
                patient: patient,
                error: ''
            };
        } catch (error) {
            return {
                available: false,
                matched: false,
                patient: null,
                error: String(error && error.message || error || '')
            };
        }
    }

    function roundBookApplyMedicalManagementResponsibleDoctor(
        record,
        patient
    ) {
        if (!record || !patient || patient.hasResponsibleDoctor !== true) {
            return false;
        }
        const next = roundBookClip(
            patient.responsibleDoctor,
            ROUND_BOOK_MAX_SHORT_TEXT
        );
        if (
            roundBookPlain(record.responsibleDoctor) ===
            roundBookPlain(next)
        ) {
            return false;
        }
        /* attendDoc为空同样是权威结果：明确清空，不读取其它医师字段兜底。 */
        record.responsibleDoctor = next || '';
        record.updatedAt = Date.now();
        return true;
    }

    async function roundBookApplyInpatientSummaryDrgFallback(
        record,
        personalInterfaceInfo,
        personalInterfaceAttempted
    ) {
        if (!record || roundBookPlain(record.drgGroup)) {
            return { changed: [], warning: '' };
        }

        /*
         * v12.34.116：DRG映射诊断来源按“在院批量接口 → 已出区病案首页 → 本地入院诊断”逐级兜底。
         * 1. 8003 GetzbqPatientList：在院患者一次病区列表即可批量复用；
         * 2. 8005 RYZD：8003无法定位患者时使用，主要覆盖已出区历史患者；
         * 3. record.diagnosis：保留v12.34.114本地诊断兜底，接口临时不可用时仍可工作。
         */
        let patientListDiagnosis = '';
        let patientListError = null;
        try {
            patientListDiagnosis = await roundBookRead8003PatientListDiagnosis(record);
        } catch (error) {
            patientListError = error;
        }

        if (patientListDiagnosis) {
            const changed = roundBookApplyInpatientSummaryDrgMapFallback(
                record,
                patientListDiagnosis,
                '8003诊断→住院患者一览映射兜底'
            );
            if (changed.length) {
                return {
                    changed: changed,
                    warning: '',
                    diagnosis: patientListDiagnosis,
                    diagnosisSource: '8003-zdmc'
                };
            }
        }

        /*
         * 只有8003未找到可用诊断时才进入8005，避免在院患者重复请求。
         * 整行/批量同步若本轮已经读取过8005，则直接复用传入结果；
         * personalInterfaceAttempted=true且结果为空表示本轮8005已失败，不再重复请求。
         */
        let personal = personalInterfaceInfo || null;
        let personalError = null;
        if (!patientListDiagnosis && !personal && personalInterfaceAttempted !== true) {
            try {
                personal = await roundBookReadPersonalInterface(record.admissionNo);
            } catch (error) {
                personalError = error;
            }
        }

        const admissionDiagnosis = roundBookPlain(
            personal && personal.admissionDiagnosis
        );
        if (!patientListDiagnosis && admissionDiagnosis) {
            const changed = roundBookApplyInpatientSummaryDrgMapFallback(
                record,
                admissionDiagnosis,
                '8005 RYZD→住院患者一览映射兜底'
            );
            if (changed.length) {
                return {
                    changed: changed,
                    warning: '',
                    diagnosis: admissionDiagnosis,
                    diagnosisSource: '8005-RYZD'
                };
            }
        }

        /* v12.34.114方案继续作为最后的本地离线兜底。 */
        const localDiagnosis = roundBookPlain(record && record.diagnosis);
        const localChanged = roundBookApplyInpatientSummaryDrgMapFallback(
            record,
            localDiagnosis,
            '查房本入院诊断→住院患者一览映射兜底'
        );
        if (localChanged.length) {
            const warningParts = [];
            if (patientListError) {
                warningParts.push(String(patientListError.message || patientListError));
            }
            if (personalError) {
                warningParts.push(String(personalError.message || personalError));
            }
            return {
                changed: localChanged,
                warning: warningParts.join('；'),
                diagnosis: localDiagnosis,
                diagnosisSource: 'round-book-diagnosis'
            };
        }

        const warningParts = [];
        if (patientListError) {
            warningParts.push(String(patientListError.message || patientListError));
        } else if (patientListDiagnosis) {
            warningParts.push(
                '8003诊断“' + patientListDiagnosis + '”尚未建立住院患者一览DRG映射'
            );
        }
        if (!patientListDiagnosis) {
            if (personalError) {
                warningParts.push(String(personalError.message || personalError));
            } else if (personalInterfaceAttempted === true && !personal) {
                warningParts.push('8005病案首页接口本轮读取失败');
            } else if (admissionDiagnosis) {
                warningParts.push(
                    '8005入院诊断“' + admissionDiagnosis + '”尚未建立住院患者一览DRG映射'
                );
            } else {
                warningParts.push('8005病案首页接口未返回可用于DRG映射的RYZD');
            }
        }
        if (localDiagnosis) {
            warningParts.push(
                '查房本入院诊断“' + localDiagnosis + '”亦未命中DRG映射'
            );
        } else {
            warningParts.push('查房本尚无可用于最终兜底的入院诊断');
        }

        return {
            changed: [],
            warning: warningParts.join('；') || '未找到可用于DRG映射的诊断',
            diagnosis: patientListDiagnosis || admissionDiagnosis || localDiagnosis,
            diagnosisSource: patientListDiagnosis
                ? '8003-zdmc'
                : admissionDiagnosis
                    ? '8005-RYZD'
                    : localDiagnosis
                        ? 'round-book-diagnosis'
                        : ''
        };
    }

    function roundBookReadDrgBaseline(
        admissionNo
    ) {
        const target =
            roundBookCleanAdmissionNo(
                admissionNo
            );

        if (!target) {
            throw new Error(
                '缺少住院号，无法读取DRG基线'
            );
        }

        const bridge =
            roundBookDrgBridge();

        if (!bridge) {
            throw new Error(
                '未检测到DRG助手读取接口。请升级并启用v2.5.16以上“医师DRG费用助手”，在DRG历史项管理中先点击“提取当前页面信息”，然后刷新8003页面'
            );
        }

        const value =
            bridge.getPatient(target);

        if (
            !value ||
            typeof value !== 'object'
        ) {
            throw new Error(
                '最近DRG基线中未找到住院号 ' +
                target +
                '；请在8996 DRG页面刷新患者列表后重新“提取当前页面信息”'
            );
        }

        return {
            admissionNo: target,
            drgGroup:
                roundBookClip(
                    value.drgGroup,
                    ROUND_BOOK_MAX_SHORT_TEXT
                ),
            drgSource:
                roundBookOneLine(
                    value.drgSource
                ),
            responsibleDoctor:
                roundBookClip(
                    value.responsibleDoctor,
                    ROUND_BOOK_MAX_SHORT_TEXT
                ),
            hasResponsibleDoctor:
                Object.prototype.hasOwnProperty.call(
                    value,
                    'responsibleDoctor'
                ),
            allocationFee:
                Number.isFinite(
                    roundBookDrgNumber(value.allocationFee)
                )
                    ? String(
                        roundBookDrgNumber(value.allocationFee)
                    )
                    : '',
            dailyCost:
                Number.isFinite(
                    roundBookDrgNumber(value.dailyCost)
                ) &&
                roundBookDrgNumber(value.dailyCost) > 0
                    ? String(
                        roundBookDrgNumber(value.dailyCost)
                    )
                    : '',
            capturedAt:
                roundBookClip(
                    (
                        bridge.getMeta &&
                        bridge.getMeta()
                    )?.capturedAt || '',
                    100
                )
        };
    }

    function roundBookApplyDrgBaseline(
        record,
        baseline,
        overwrite,
        options
    ) {
        const source =
            baseline &&
            typeof baseline === 'object'
                ? baseline
                : {};

        const config =
            options &&
            typeof options === 'object'
                ? options
                : {};

        const force =
            overwrite === true;

        const changed = [];

        const nextGroup =
            roundBookClip(
                source.drgGroup,
                ROUND_BOOK_MAX_SHORT_TEXT
            );

        const nextResponsibleDoctor =
            roundBookClip(
                source.responsibleDoctor,
                ROUND_BOOK_MAX_SHORT_TEXT
            );

        if (
            (force || !roundBookPlain(record.drgGroup)) &&
            roundBookPlain(record.drgGroup) !==
                roundBookPlain(nextGroup)
        ) {
            record.drgGroup =
                nextGroup || '';
            changed.push('DRG分组');
        }

        /* 按最终保留的分组读取预警设置；助手费用仅用于相同分组。 */
        changed.push.apply(changed, roundBookApplyDrgFinancialSettings(record, source));

        /*
         * 责任医师是v2.5.16完整快照新增字段。仅当桥接明确携带该字段时
         * 才覆盖，避免旧版DRG助手尚未升级时误清空已经保存的责任医师。
         * DRG分组本身仍严格沿用上方 force/空值规则。
         */
        if (
            config.applyResponsibleDoctor !== false &&
            source.hasResponsibleDoctor === true &&
            roundBookPlain(record.responsibleDoctor) !==
                roundBookPlain(nextResponsibleDoctor)
        ) {
            record.responsibleDoctor =
                nextResponsibleDoctor || '';
            changed.push('责任医师');
        }

        record.drgBaselineSource =
            roundBookClip(
                source.drgSource,
                40
            );

        record.drgBaselineCapturedAt =
            roundBookClip(
                source.capturedAt,
                100
            );

        record.drgBaselineUpdatedAt =
            Date.now();

        record.updatedAt =
            Date.now();

        return changed;
    }

    function roundBookReadInpatientSnapshot() {
        const bridge =
            roundBookDrgBridge();

        if (
            !bridge ||
            typeof bridge.getSnapshot !==
                'function'
        ) {
            return null;
        }

        try {
            const source =
                bridge.getSnapshot();

            if (
                !source ||
                typeof source !== 'object' ||
                !Array.isArray(source.columns)
            ) {
                return null;
            }

            const rows =
                Array.isArray(source.rows)
                    ? source.rows
                    : Object.keys(
                        source.records || {}
                    ).map(function (key) {
                        return source.records[key];
                    });

            if (!rows.length) {
                return null;
            }

            /*
             * DRG桥已返回JSON安全副本。移动快照只保留一份有序rows，
             * 不再重复携带按病案号索引的records，以免同一完整页面翻倍上传；
             * columns + rows 足以在掌上OHA无损还原所有列与字段。
             */
            return JSON.parse(JSON.stringify({
                kind:
                    source.kind ||
                    'medical-doctor-drg-inpatient-page-snapshot',
                sourceType: 'drg-snapshot',
                sourceLabel: 'DRG助手页面快照',
                schemaVersion:
                    Number(source.schemaVersion) || 2,
                fullSnapshot:
                    source.fullSnapshot !== false,
                capturedAt:
                    source.capturedAt || '',
                capturedAtLabel:
                    source.capturedAtLabel || '',
                sourceUrl:
                    source.sourceUrl || '',
                sourcePath:
                    source.sourcePath || '',
                count:
                    Number(source.count) ||
                    rows.length,
                columnCount:
                    Number(source.columnCount) ||
                    source.columns.length,
                columns:
                    source.columns,
                rows:
                    rows
            }));
        } catch (error) {
            return null;
        }
    }

    /*
     * 住院页名单与查房本分组名单分开：每次上传先读取8997实际查询结果。
     * 若8997分页缺失、认证失效或GM兼容层报错，整份住院名单回退DRG快照，
     * 不混用两份名单的患者范围，也不把8997的DRG字段当作业务基线。
     */
    async function roundBookMobile8997Rows(forceRefresh) {
        const first = await roundBookMedicalManagementRequestPatients(forceRefresh !== false);
        const rows = Array.isArray(first.rows) ? first.rows.slice() : [];
        const total = Number(first.total) || rows.length;
        if (!rows.length || total > 3000) {
            throw new Error('8997住院名单为空或超过安全分页范围');
        }
        if (total <= rows.length) return rows;

        const auth = roundBookMedicalManagementReadAuth();
        if (!auth || !roundBookPlain(auth.token)) {
            throw new Error('8997后续分页缺少有效认证');
        }
        /* 部分8997实现会限制每页返回数，后续按实际第一页长度分页。 */
        const pageSize = Math.min(200, rows.length);
        const pages = Math.ceil(total / pageSize);
        for (let pageNum = 2; pageNum <= pages; pageNum += 1) {
            const payload = roundBookMedicalManagementClone(auth.payload) || {};
            payload.pageNum = pageNum;
            payload.pageSize = pageSize;
            if (!payload.hospitalArea && auth.hospitalArea) {
                payload.hospitalArea = auth.hospitalArea;
            }
            const pageRows = await new Promise(function (resolve, reject) {
                GM_xmlhttpRequest({
                    method: 'POST',
                    url: ROUND_BOOK_MEDICAL_MANAGEMENT_API_URL,
                    headers: {
                        'Accept': 'application/json, text/plain, */*',
                        'Content-Type': 'application/json;charset=UTF-8',
                        'token': String(auth.token)
                    },
                    data: JSON.stringify(payload),
                    anonymous: true,
                    timeout: 16000,
                    onload: function (response) {
                        if (response.status < 200 || response.status >= 300) {
                            reject(new Error('8997分页HTTP ' + response.status));
                            return;
                        }
                        try {
                            const parsed = JSON.parse(response.responseText || '{}');
                            const found = roundBookMedicalManagementApiRows(parsed);
                            if (!found.length) throw new Error('8997分页为空');
                            resolve(found);
                        } catch (error) {
                            reject(error);
                        }
                    },
                    onerror: function () { reject(new Error('8997分页跨域请求失败')); },
                    ontimeout: function () { reject(new Error('8997分页请求超时')); }
                });
            });
            rows.push.apply(rows, pageRows);
        }
        if (rows.length < total) throw new Error('8997分页名单不完整');
        return rows;
    }

    function roundBookMobile8997InpatientSnapshot(rawRows, drgSnapshot) {
        const drgColumns = drgSnapshot && Array.isArray(drgSnapshot.columns)
            ? drgSnapshot.columns
            : [];
        const columns = drgColumns.map(function (column) {
            return Object.assign({}, column);
        });
        [
            ['sequence', '序号'], ['bedNo', '床号'],
            ['admissionNo', '病案号'], ['patientName', '姓名'],
            ['sex', '性别'], ['age', '年龄'],
            ['admissionDate', '入院时间'], ['responsibleDoctor', '责任医师'],
            ['drgGroup', 'DRG预分组']
        ].forEach(function (entry) {
            if (!columns.some(function (column) { return column.key === entry[0]; })) {
                columns.push({ key: entry[0], label: entry[1], index: columns.length });
            }
        });
        const drgByNo = new Map();
        (drgSnapshot && Array.isArray(drgSnapshot.rows) ? drgSnapshot.rows : [])
            .forEach(function (row) {
                const no = roundBookCleanAdmissionNo(row && row.admissionNo);
                if (no && !drgByNo.has(no)) drgByNo.set(no, row);
            });
        const seen = new Set();
        const rows = [];
        (rawRows || []).forEach(function (raw) {
            const patient = roundBookNormalizeMedicalManagementPatient(raw);
            const no = patient && patient.admissionNo;
            if (!no || seen.has(no)) return;
            seen.add(no);
            const baseline = drgByNo.get(no) || {};
            const fields = Object.assign({}, baseline.fields || {});
            const sequence = String(rows.length + 1);
            const values = {
                sequence: sequence,
                bedNo: patient.bedNo || baseline.bedNo || '',
                admissionNo: no,
                patientName: patient.name || baseline.patientName || baseline.name || '',
                sex: patient.sex || baseline.sex || '',
                age: patient.age || baseline.age || '',
                admissionDate: patient.admissionDate || baseline.admissionDate || '',
                responsibleDoctor: patient.responsibleDoctor || '',
                drgGroup: baseline.drgGroup || ''
            };
            Object.assign(fields, values);
            rows.push(Object.assign({}, baseline, values, {
                name: values.patientName,
                rowIndex: rows.length + 1,
                fields: fields
            }));
        });
        if (!rows.length) throw new Error('8997名单没有可识别住院号');
        const now = new Date();
        return {
            kind: 'medical-management-inpatient-roster-snapshot',
            schemaVersion: 3,
            sourceType: '8997',
            sourceLabel: '8997医疗管理系统实时名单',
            fullSnapshot: false,
            capturedAt: now.toISOString(),
            capturedAtLabel: now.toLocaleString(),
            count: rows.length,
            columnCount: columns.length,
            columns: columns,
            rows: rows
        };
    }

    async function roundBookBuildMobileUploadSnapshot(modal, options) {
        const drgSnapshot = roundBookReadInpatientSnapshot();
        let inpatientSnapshot = drgSnapshot;
        try {
            const rows = await roundBookMobile8997Rows(
                !(options && options.forceRefresh === false)
            );
            inpatientSnapshot = roundBookMobile8997InpatientSnapshot(rows, drgSnapshot);
        } catch (error) {
            /* 8997未授权/不可用时，保留原DRG快照路径，不影响患者数据上传。 */
            console.warn('[查房本掌上OHA住院名单] 8997不可用，使用DRG快照：', error);
        }
        const snapshot = roundBookBuildMobileSnapshot(modal, options);
        snapshot.inpatientSnapshot = inpatientSnapshot;
        if (inpatientSnapshot && inpatientSnapshot.sourceType === '8997') {
            const doctorsByNo = new Map(
                inpatientSnapshot.rows.map(function (row) {
                    return [roundBookCleanAdmissionNo(row.admissionNo), row.responsibleDoctor || ''];
                })
            );
            Object.keys(snapshot.records || {}).forEach(function (key) {
                const record = snapshot.records[key];
                const no = roundBookCleanAdmissionNo(record && record.admissionNo);
                if (no && doctorsByNo.has(no)) {
                    /* 只刷新本次上传值，不改动桌面记录或其它DRG业务字段。 */
                    record.responsibleDoctor = doctorsByNo.get(no);
                }
            });
        }
        return snapshot;
    }

    function roundBookDrgRemainingDays(record, daily) {
        const values = roundBookDrgFinancialValues(record);
        const allocationFee = roundBookDrgNumber(values.allocationFee);
        const currentFee = roundBookDrgNumber(daily && daily.inHospitalCost);
        const dailyCost = roundBookDrgNumber(values.dailyCost);
        if (!Number.isFinite(allocationFee) || allocationFee < 0 ||
            !Number.isFinite(currentFee) || !Number.isFinite(dailyCost) || dailyCost <= 0) {
            return NaN;
        }
        return currentFee >= allocationFee ? 0 : Math.ceil((allocationFee - currentFee) / dailyCost);
    }

    function roundBookDrgDisplayText(
        record,
        daily,
        includeResponsibleDoctor
    ) {
        const group =
            roundBookPlain(
                record &&
                record.drgGroup
            );

        const allocation =
            roundBookFormatMoney(
                record &&
                roundBookDrgFinancialValues(record).allocationFee
            );

        const remainingDays =
            roundBookDrgRemainingDays(
                record,
                daily
            );

        const lines = [];

        if (group) {
            lines.push(
                'DRG分组：' +
                group
            );
        }

        if (includeResponsibleDoctor === true) {
            lines.push(
                '责任医师：' +
                roundBookPlain(
                    record &&
                    record.responsibleDoctor
                )
            );
        }

        lines.push(
            '拨付费用：' +
            (
                allocation
                    ? allocation + '元'
                    : ''
            )
        );

        lines.push(
            '剩余天数：' +
            (
                Number.isFinite(
                    remainingDays
                )
                    ? remainingDays + '天'
                    : ''
            )
        );

        return lines.join('\n');
    }

    /*
     * v12.34.35：查房本状态扩展为三态。
     * archived（已归档）是按日期保存的正式状态，必须贯穿本地存储、
     * 备份恢复、跨标签同步和日期沿用，不能在规范化时降级为ward。
     */
    function roundBookNormalizeStatus(value, fallbackStatus) {
        const source = String(value || '').trim();
        if (source === 'archived') return 'archived';
        if (source === 'discharged') return 'discharged';
        if (source === 'ward') return 'ward';
        const fallback = String(fallbackStatus || '').trim();
        if (fallback === 'archived') return 'archived';
        if (fallback === 'discharged') return 'discharged';
        return 'ward';
    }

    function roundBookStatusLabel(status) {
        const normalized = roundBookNormalizeStatus(status);
        if (normalized === 'archived') return '已归档';
        if (normalized === 'discharged') return '已出区';
        return '在病区';
    }

    function roundBookEmptyDaily(status) {
        return {
            status: roundBookNormalizeStatus(status),
            groupIds: [],
            inHospitalCost: '',
            basicSituation: '',
            orderAdjustmentAuto: '',
            orderAdjustmentManual: '',
            orderAdjustmentSource: '',
            orderAdjustmentRange: '',
            orderAdjustmentCount: 0,
            orderAdjustmentUpdatedAt: 0,
            inpatientAuxiliary: '',
            roundVitalsAuto: '',
            roundVitalsSource: '',
            roundVitalsRange: '',
            roundVitalsCount: 0,
            roundVitalsUpdatedAt: 0,
            lisPacsAuto: '',
            lisPacsSource: '',
            lisPacsRange: '',
            lisPacsLisCount: 0,
            lisPacsPacsCount: 0,
            lisPacsUpdatedAt: 0,
            roundNote: '',
            capturedAt: '',
            carriedFromDate: '',
            backgroundHidden: false,
            backgroundHiddenAt: 0,
            backgroundHiddenStatus: '',
            updatedAt: Date.now()
        };
    }

    function roundBookNormalizeDaily(value, fallbackStatus) {
        const source = value && typeof value === 'object'
            ? value
            : {};
        const daily = roundBookEmptyDaily(
            source.status || fallbackStatus
        );
        daily.groupIds = Array.from(new Set(
            (Array.isArray(source.groupIds) ? source.groupIds : [])
                .map(function (item) {
                    return String(item || '').trim();
                })
                .filter(Boolean)
        ));
        daily.backgroundHidden = source.backgroundHidden === true;
        daily.backgroundHiddenAt = Number(source.backgroundHiddenAt) || 0;
        daily.backgroundHiddenStatus = daily.backgroundHidden
            ? roundBookNormalizeStatus(
                source.backgroundHiddenStatus || source.status
            )
            : '';
        [
            'inHospitalCost',
            'basicSituation',
            'orderAdjustmentAuto',
            'orderAdjustmentManual',
            'orderAdjustmentSource',
            'orderAdjustmentRange',
            'roundVitalsAuto',
            'roundVitalsSource',
            'roundVitalsRange',
            'lisPacsAuto',
            'lisPacsSource',
            'lisPacsRange',
            'roundNote',
            'capturedAt',
            'carriedFromDate'
        ].forEach(function (field) {
            daily[field] = roundBookClip(
                source[field],
                field === 'inHospitalCost'
                    ? ROUND_BOOK_MAX_SHORT_TEXT
                    : ROUND_BOOK_MAX_LONG_TEXT
            );
        });
        daily.orderAdjustmentCount = Math.max(
            0,
            Number(source.orderAdjustmentCount) || 0
        );
        daily.orderAdjustmentUpdatedAt = Number(
            source.orderAdjustmentUpdatedAt
        ) || 0;
        daily.roundVitalsCount = Math.max(
            0,
            Number(source.roundVitalsCount) || 0
        );
        daily.roundVitalsUpdatedAt = Number(
            source.roundVitalsUpdatedAt
        ) || 0;
        daily.lisPacsLisCount = Math.max(
            0,
            Number(source.lisPacsLisCount) || 0
        );
        daily.lisPacsPacsCount = Math.max(
            0,
            Number(source.lisPacsPacsCount) || 0
        );
        daily.lisPacsUpdatedAt = Number(
            source.lisPacsUpdatedAt
        ) || 0;
        /*
         * v12.14：原“辅助检查手工补充”升级为独立的
         * “辅助检查（住院）”纯手工列。仅做本地字段迁移，
         * 不从入院记录、医嘱或AI结果映射/自动填充。
         */
        daily.inpatientAuxiliary = roundBookClip(
            source.inpatientAuxiliary || source.auxiliaryManual,
            ROUND_BOOK_MAX_LONG_TEXT
        );
        daily.updatedAt = Number(source.updatedAt) || Date.now();
        return daily;
    }

