        record.groupIds = Array.from(new Set(
            (Array.isArray(source.groupIds) ? source.groupIds : [])
                .map(function (item) {
                    return String(item || '').trim();
                })
                .filter(Boolean)
        ));
        record.sourceText = roundBookClip(source.sourceText, 4000);
        record.createdAt = Number(source.createdAt) || Date.now();
        record.updatedAt = Number(source.updatedAt) || Date.now();
        record.daily = {};
        const dailySource = source.daily && typeof source.daily === 'object'
            ? source.daily
            : {};
        Object.keys(dailySource).forEach(function (dateKey) {
            if (/^\d{4}-\d{2}-\d{2}$/.test(dateKey)) {
                record.daily[dateKey] = roundBookNormalizeDaily(
                    dailySource[dateKey],
                    record.status
                );
            }
        });
        return record;
