    /* =========================================================
     * v12.32：医嘱调整AI汇总增加独立提示词与固化/松绑systemPrompt模式。
     * v12.31：医嘱调整改用HIS AdviceGridView接口
     * ---------------------------------------------------------
     * 正式同步不再依赖 localStorage 本机操作日志。
     * 仅依据服务器医嘱记录中的开始时间、停止时间、长/临类别和状态，
     * 在指定范围内重建“新增/停止/作废”事件，再生成结构化摘要或AI汇总。
     * 本机日志相关函数继续保留，仅供行内“本机日志摘要/AI汇总本机日志”辅助审计。
     * ========================================================= */

    function roundBookOrderChangeDateKey(value) {
        const text = roundBookPlain(value);
        const match = text.match(/(20\d{2})[年\-\/.](\d{1,2})[月\-\/.](\d{1,2})/);
        if (!match) return '';
        return match[1] + '-' +
            String(Number(match[2])).padStart(2, '0') + '-' +
            String(Number(match[3])).padStart(2, '0');
    }

    function roundBookOrderChangeTimeKey(value) {
        const text = roundBookPlain(value);
        const dateKey = roundBookOrderChangeDateKey(text);
        const timeMatch = text.match(/(?:\s|T)(\d{1,2}):(\d{2})(?::(\d{2}))?/);
        if (!dateKey) return text;
        return dateKey + (timeMatch
            ? ' ' + String(Number(timeMatch[1])).padStart(2, '0') + ':' + timeMatch[2]
            : '');
    }

    function roundBookOrderChangeInRange(dateKey, range) {
        return Boolean(
            dateKey &&
            range &&
            !range.empty &&
            dateKey >= range.startDate &&
            dateKey <= range.endDate
        );
    }

    function roundBookOrderChangeCompactOrder(record) {
        const parts = [];
        const category = roundBookPlain(record && record.orderCategory);
        const name = roundBookPlain(record && record.name);
        const dose = roundBookPlain(record && record.dose);
        const specification = roundBookPlain(record && record.specification);
        const route = roundBookPlain(record && record.route);
        const frequency = roundBookPlain(record && record.frequency);
        const group = roundBookPlain(record && record.group);
        if (category) parts.push(category);
        if (name) parts.push(name);
        if (dose) parts.push(dose);
        if (specification) parts.push(specification);
        if (route) parts.push(route);
        if (frequency) parts.push(frequency);
        if (group) parts.push('组' + group);
        return parts.join(' ');
    }

    function roundBookBuildOrderChangeBaseline(record, records, dateKey, rangeMode) {
        const range = roundBookLogRange(record, dateKey, rangeMode);
        const events = [];
        const seen = new Set();

        (Array.isArray(records) ? records : []).forEach(function (source) {
            const item = source && Object.prototype.hasOwnProperty.call(source, 'name')
                ? source
                : roundBookNormalizeOrderApiRecord(source);
            const name = roundBookPlain(item && item.name);
            if (!name) return;

            const startDate = roundBookOrderChangeDateKey(item.startTime);
            const stopDate = roundBookOrderChangeDateKey(item.stopTime);
            const statusText = roundBookPlain(item.status);
            const normalizedStatus = roundBookNormalize(statusText);
            const categoryText = roundBookPlain(item.orderCategory);
            const isTemporary = /临|临时/.test(categoryText) && !/长|长期/.test(categoryText);
            const statusCodeFour = /^0*4$/.test(statusText);
            const voided = (isTemporary && statusCodeFour) ||
                /作废/.test(statusText) ||
                normalizedStatus === roundBookNormalize('已作废');

            function pushEvent(action, timeValue) {
                const time = roundBookOrderChangeTimeKey(timeValue);
                const eventDate = roundBookOrderChangeDateKey(timeValue);
                if (!roundBookOrderChangeInRange(eventDate, range)) return;
                const event = {
                    time: time || eventDate,
                    date: eventDate,
                    action: action,
                    orderCategory: roundBookPlain(item.orderCategory),
                    orderType: roundBookPlain(item.orderType),
                    name: name,
                    dose: roundBookPlain(item.dose),
                    specification: roundBookPlain(item.specification),
                    route: roundBookPlain(item.route),
                    frequency: roundBookPlain(item.frequency),
                    group: roundBookPlain(item.group),
                    doctor: roundBookPlain(item.doctor),
                    stopDoctor: roundBookPlain(item.stopDoctor),
                    status: roundBookPlain(item.status)
                };
                const signature = [
                    event.time,
                    event.action,
                    event.orderCategory,
                    event.name,
                    event.dose,
                    event.route,
                    event.frequency,
                    event.group,
                    event.status
                ].map(roundBookNormalize).join('|');
                if (seen.has(signature)) return;
                seen.add(signature);
                events.push(event);
            }

            /* 作废且没有独立停止时间时，只记录“作废”，避免同一条同时显示新增+作废。 */
            if (voided && !roundBookPlain(item.stopTime)) {
                pushEvent('作废', item.startTime);
            } else {
                pushEvent('新增', item.startTime);
                if (roundBookPlain(item.stopTime)) {
                    pushEvent(voided ? '作废' : '停止', item.stopTime);
                }
            }
        });

        const actionOrder = { '停止': 0, '作废': 1, '新增': 2 };
        events.sort(function (first, second) {
            const byTime = String(first.time || '').localeCompare(String(second.time || ''));
            if (byTime) return byTime;
            const firstOrder = Object.prototype.hasOwnProperty.call(actionOrder, first.action)
                ? actionOrder[first.action]
                : 9;
            const secondOrder = Object.prototype.hasOwnProperty.call(actionOrder, second.action)
                ? actionOrder[second.action]
                : 9;
            return firstOrder - secondOrder;
        });

        const lines = events.map(function (event) {
            const orderText = [
                event.orderCategory,
                event.name,
                event.dose,
                event.specification,
                event.route,
                event.frequency,
                event.group ? '组' + event.group : ''
            ].filter(Boolean).join(' ');
            const statusSuffix = event.status && event.action !== '新增'
                ? '（状态：' + event.status + '）'
                : '';
            return (event.time || event.date) + ' ' + event.action + '：' +
                orderText + statusSuffix;
        });

        return {
            events: events,
            count: events.length,
            text: roundBookClip(lines.join('\n'), ROUND_BOOK_MAX_LONG_TEXT),
            range: range
        };
    }

