    function roundBookInsuranceConsistencyPromptSolidified() {
        try {
            const raw = localStorage.getItem(
                ROUND_BOOK_INSURANCE_CONSISTENCY_SOLIDIFIED_STORAGE_KEY
            );
            if (raw === null || raw === '') return true;
            return raw !== 'false' && raw !== '0';
        } catch (error) {
            return true;
        }
    }

    function roundBookInsuranceConsistencyPromptSave(prompt, solidified) {
        const value = roundBookPlain(prompt);
        if (!value) {
            throw new Error('医保一致性校验提示词不能为空');
        }
        if (value.length > 20000) {
            throw new Error('医保一致性校验提示词不能超过20000字');
        }
        localStorage.setItem(
            ROUND_BOOK_INSURANCE_CONSISTENCY_PROMPT_STORAGE_KEY,
            value
        );
        localStorage.setItem(
            ROUND_BOOK_INSURANCE_CONSISTENCY_SOLIDIFIED_STORAGE_KEY,
            solidified === false ? 'false' : 'true'
        );
        return {
            prompt: value,
            solidified: solidified !== false,
            mode: solidified === false ? 'flexible' : 'solidified'
        };
    }

    function roundBookInsuranceConsistencySystemPrompt(solidified, markdownEnabled) {
        const useMarkdown = markdownEnabled !== false;
        if (solidified === false) {
            return [
                '你是住院医保资料一致性复核助手，结果仅供执业医师人工复核。',
                'customPrompt是本次任务的主要业务规则，必须严格执行；但本次窗口的输出格式（Markdown或纯文本）由界面开关决定，并优先于customPrompt中历史遗留的格式要求。',
                '只能依据用户提供的insuranceData判断诊断、药品/治疗、辅助检查之间的资料一致性；不得补造诊断、适应证、症状、体征、检验值、影像结论或医保政策。',
                '不得为了使药品或检查与医保诊断匹配而建议添加没有临床证据支持的诊断。',
                '未提供当地医保目录、限定支付条件、适应证限制、剂量/疗程/频次规则时，不得断言医保违规、拒付或超限；只能提示需要结合真实医保政策人工核对。',
                '资料不足时明确写“资料不足/需人工核实”，不要把缺失资料当成异常或违规。',
                useMarkdown
                    ? '直接使用简洁Markdown输出最终结果，可使用标题、项目符号和加粗；不使用Markdown表格，不输出代码块、JSON包装或无关分析过程。'
                    : '直接输出结构化纯文本。可使用普通中文分段标题、数字序号和换行，但不得使用Markdown标题符号、加粗符号、项目符号语法、代码块、表格、JSON包装或无关分析过程。'
            ].join('\n');
        }
        const outputRules = useMarkdown
            ? [
                '输出简洁Markdown，不使用Markdown表格，固定按以下结构并使用二级标题：',
                '## 一、医保诊断基线',
                '## 二、药品/治疗—医保诊断一致性',
                '## 三、辅助检查—医保诊断一致性',
                '## 四、需人工核实的诊断/资料缺口',
                '## 五、总体提示'
            ]
            : [
                '输出结构化纯文本，不使用任何Markdown语法；固定按以下普通文本标题分段，可在段内使用数字序号：',
                '一、医保诊断基线',
                '二、药品/治疗—医保诊断一致性',
                '三、辅助检查—医保诊断一致性',
                '四、需人工核实的诊断/资料缺口',
                '五、总体提示',
                '不得使用#、**、```、Markdown项目符号或Markdown表格。'
            ];
        return [
            '你是中国医院住院医保资料一致性复核助手，结果只用于执业医师和医保管理人员人工复核，不替代医保规则引擎、医保结算审核或临床判断。',
            '用户提供的customPrompt是自定义校验要求，必须执行；若与以下事实与合规边界冲突，以以下边界为准。本次窗口的输出格式（Markdown或纯文本）由界面开关决定，并优先于customPrompt中历史遗留的格式要求。',
            'insuranceData.insuranceDiagnosisBaseline来自当前查房本“入院诊断”，本任务将其作为本次医保诊断基线；不得自行新增、删除、改写或推测诊断。',
            '药品/治疗资料来自当前患者HIS医嘱基线、查房本基本情况及近期医嘱调整；辅助检查资料来自入院辅助检查、住院辅助检查和LIS/PACS基线。只能依据这些真实输入进行一致性复核。',
            '一致性复核的目标是识别：现有诊断是否能够为当前药品/治疗和辅助检查提供合理的临床指向；以及是否存在“当前资料中未见明确诊断支持、需要人工核实”的项目。',
            '“当前诊断未见支持”不等于医保违规。若某项目可能由未提供的症状、体征、并发症、既往病史、检验异常或鉴别诊断支持，应标记“需人工核实”，不得擅自判定不合理。',
            '绝对禁止为了医保匹配、收费或避免审核而建议添加没有临床证据支持的诊断；只能指出“诊断记录/临床依据是否完整需人工核实”。',
            '未提供当地医保目录、限定支付范围、药品适应证限制、支付标准、检查频次、疗程、医院等级或地区政策时，不得断言医保违规、拒付、超限或可报销；需要政策依据的项目统一提示“需结合当地医保政策/限定支付条件人工核对”。',
            '药品/治疗部分优先核对药名/治疗项目与诊断之间的临床对应关系；剂量、用法、疗程只有在输入资料足够时才可提示疑点，资料不足不得自行推断。',
            '辅助检查部分同时考虑确诊、鉴别诊断、病情评估、用药安全监测和并发症筛查等合理目的；如果当前资料无法判断目的，标记“需核实检查目的/诊断依据”。'
        ].concat(outputRules).concat([
            '每个疑点尽量指出具体药品或检查项目及其当前诊断支持情况；不得输出患者姓名、病案号、床号等直接身份信息。'
        ]).join('\n');
    }

    function roundBookInsuranceConsistencyPromptConfig(markdownEnabled) {
        const solidified = roundBookInsuranceConsistencyPromptSolidified();
        const useMarkdown = markdownEnabled !== false;
        return {
            prompt: roundBookInsuranceConsistencyPromptRead(),
            solidified: solidified,
            mode: solidified ? 'solidified' : 'flexible',
            outputFormat: useMarkdown ? 'markdown' : 'plain',
            systemPrompt: roundBookInsuranceConsistencySystemPrompt(
                solidified,
                useMarkdown
            )
        };
    }

