                    '<span data-archive-ingest-count style="color:#6b7f8a;font-size:12px;white-space:nowrap;">显示 ' + items.length + '/' + items.length + ' 人</span>' +
                    '<button type="button" data-archive-ingest-all>全选</button>' +
                    '<button type="button" data-archive-ingest-none>全不选</button>' +
                    '<button type="button" data-archive-ingest-selected style="color:#7c5d12;">收纳所选</button>' +
                    '<span style="color:#6b7f8a;font-size:12px;">先完整写入冷档案库，再从主store移除。</span>' +
                '</div>' +
                '<div style="overflow:auto;flex:1;padding:0 12px 12px;">' +
                    '<table style="width:100%;border-collapse:collapse;font-size:12px;"><thead style="position:sticky;top:0;background:#eef7fb;z-index:1;"><tr><th></th><th style="text-align:left;padding:7px;">床号</th><th style="text-align:left;padding:7px;">姓名</th><th style="text-align:left;padding:7px;">病案号</th><th style="text-align:left;padding:7px;">诊断</th><th style="text-align:left;padding:7px;">操作</th></tr></thead><tbody>' + rows + '</tbody></table>' +
                '</div>' +
            '</div>';
        modal.appendChild(overlay);
